CREATE OR REPLACE FUNCTION private.apply_sale_inventory_effects(p_license_id uuid, p_sale_id text, p_allocations jsonb, p_actor_device_id uuid DEFAULT NULL::uuid, p_actor_staff_user_id uuid DEFAULT NULL::uuid, p_actor_key text DEFAULT NULL::text, p_actor_name text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_response jsonb;
  v_allocation record;
  v_product_id text;
  v_batch_id text;
  v_sale_item_id text;
  v_quantity numeric;
  v_movement_idem text;
  v_movement_id text;
  v_component jsonb;
  v_components jsonb := '[]'::jsonb;
begin
  v_response := private.apply_sale_inventory_effects_direct_rest_inv5(
    p_license_id, p_sale_id, p_allocations,
    p_actor_device_id, p_actor_staff_user_id, p_actor_key, p_actor_name, p_idempotency_key
  );

  for v_allocation in select value as payload, ordinality from jsonb_array_elements(coalesce(p_allocations, '[]'::jsonb)) with ordinality loop
    v_product_id := nullif(v_allocation.payload->>'product_id', '');
    v_batch_id := nullif(v_allocation.payload->>'batch_id', '');
    v_sale_item_id := nullif(v_allocation.payload->>'sale_item_id', '');
    v_quantity := coalesce(nullif(v_allocation.payload->>'quantity', '')::numeric, 0);

    if v_product_id is null or v_sale_item_id is null or v_quantity <= 0 then
      continue;
    end if;

    v_movement_idem := coalesce(p_idempotency_key, p_sale_id) || ':inventory:' || v_sale_item_id || ':' || v_product_id || ':' || coalesce(v_batch_id, 'product') || ':' || v_allocation.ordinality::text;

    select im.id into v_movement_id
    from public.pos_inventory_movements im
    where im.license_id = p_license_id
      and im.idempotency_key = v_movement_idem
    limit 1;

    if v_movement_id is null then
      continue;
    end if;

    v_component := jsonb_build_object(
      'movement_id', v_movement_id,
      'sale_id', p_sale_id,
      'sale_item_id', v_sale_item_id,
      'source', coalesce(v_allocation.payload->>'inventory_source', 'product'),
      'source_product_id', nullif(v_allocation.payload->>'source_product_id', ''),
      'source_product_name', nullif(v_allocation.payload->>'source_product_name', ''),
      'product_id', v_product_id,
      'product_name', nullif(v_allocation.payload->>'product_name', ''),
      'ingredient_id', v_product_id,
      'batch_id', v_batch_id,
      'batch_sku', nullif(v_allocation.payload->>'batch_sku', ''),
      'batch_expiry_date', nullif(v_allocation.payload->>'batch_expiry_date', ''),
      'quantity', v_quantity,
      'unit', nullif(v_allocation.payload->>'component_unit', ''),
      'component_quantity', nullif(v_allocation.payload->>'component_quantity', '')::numeric,
      'modifier_id', nullif(v_allocation.payload->>'modifier_id', ''),
      'modifier_name', nullif(v_allocation.payload->>'modifier_name', ''),
      'component_key', nullif(v_allocation.payload->>'component_key', ''),
      'stock_source', coalesce(v_allocation.payload->>'stock_source', case when v_batch_id is null then 'product' else 'batch' end),
      'unit_cost', nullif(v_allocation.payload->>'unit_cost', '')::numeric,
      'phase', 'rest_inv_5_cloud_restaurant_inventory'
    );

    v_components := v_components || jsonb_build_array(v_component);

    update public.pos_inventory_movements im
    set metadata = coalesce(im.metadata, '{}'::jsonb) || jsonb_build_object(
      'phase', 'rest_inv_5_cloud_restaurant_inventory',
      'inventory_component', v_component,
      'inventory_source', coalesce(v_allocation.payload->>'inventory_source', 'product'),
      'source_product_id', nullif(v_allocation.payload->>'source_product_id', ''),
      'modifier_id', nullif(v_allocation.payload->>'modifier_id', '')
    )
    where im.license_id = p_license_id
      and im.id = v_movement_id;

    update public.pos_sale_items si
    set metadata = coalesce(si.metadata, '{}'::jsonb) || jsonb_build_object(
      'inventoryComponentsUsed', coalesce(si.metadata->'inventoryComponentsUsed', '[]'::jsonb) || jsonb_build_array(v_component),
      'restaurantInventoryPhase', 'rest_inv_5_cloud_restaurant_inventory'
    ),
    server_version = si.server_version + 1
    where si.license_id = p_license_id
      and si.sale_id = p_sale_id
      and si.id = v_sale_item_id;
  end loop;

  update public.pos_sales s
  set metadata = coalesce(s.metadata, '{}'::jsonb) || jsonb_build_object(
    'restaurantInventoryPhase', 'rest_inv_5_cloud_restaurant_inventory',
    'inventoryComponentsUsed', v_components,
    'inventoryComponentsUsedCount', jsonb_array_length(v_components)
  ),
  server_version = s.server_version + 1,
  updated_at = now()
  where s.license_id = p_license_id
    and s.id = p_sale_id;

  perform private.record_pos_sale_audit_event(
    p_license_id,
    p_sale_id,
    'sale.restaurant_inventory_components_audited',
    p_actor_device_id,
    p_actor_staff_user_id,
    p_actor_name,
    jsonb_build_object('sale_id', p_sale_id, 'component_count', jsonb_array_length(v_components), 'components', v_components, 'idempotency_key', p_idempotency_key, 'phase', 'rest_inv_5_cloud_restaurant_inventory')
  );

  return v_response || jsonb_build_object('restaurant_inventory_components', v_components, 'restaurant_inventory_component_count', jsonb_array_length(v_components));
end;
$function$
CREATE OR REPLACE FUNCTION private.apply_sale_inventory_effects_direct_rest_inv5(p_license_id uuid, p_sale_id text, p_allocations jsonb, p_actor_device_id uuid DEFAULT NULL::uuid, p_actor_staff_user_id uuid DEFAULT NULL::uuid, p_actor_key text DEFAULT NULL::text, p_actor_name text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_allocation record;
  v_product public.pos_products;
  v_batch public.pos_product_batches;
  v_movement public.pos_inventory_movements;
  v_movements jsonb := '[]'::jsonb;
  v_product_id text;
  v_batch_id text;
  v_sale_item_id text;
  v_quantity numeric;
  v_unit_cost numeric;
  v_previous_stock numeric;
  v_new_stock numeric;
  v_previous_batch_stock numeric;
  v_new_batch_stock numeric;
  v_new_product_version integer;
  v_new_batch_version integer;
  v_sale_item_version bigint;
  v_movement_idem text;
  v_applied_count integer := 0;
  v_first_movement_id text;
  v_stock_source text;
begin
  if p_license_id is null or nullif(btrim(coalesce(p_sale_id, '')), '') is null then
    raise exception 'INVENTORY_EFFECT_CONTEXT_REQUIRED' using errcode = 'P0001';
  end if;

  if jsonb_typeof(coalesce(p_allocations, '[]'::jsonb)) <> 'array' then
    raise exception 'INVENTORY_ALLOCATIONS_INVALID' using errcode = 'P0001';
  end if;

  for v_allocation in
    select value as payload, ordinality
    from jsonb_array_elements(coalesce(p_allocations, '[]'::jsonb)) with ordinality
  loop
    v_product_id := nullif(v_allocation.payload->>'product_id', '');
    v_batch_id := nullif(v_allocation.payload->>'batch_id', '');
    v_sale_item_id := nullif(v_allocation.payload->>'sale_item_id', '');
    v_quantity := coalesce(nullif(v_allocation.payload->>'quantity', '')::numeric, 0);
    v_unit_cost := nullif(v_allocation.payload->>'unit_cost', '')::numeric;
    v_stock_source := coalesce(v_allocation.payload->>'stock_source', case when v_batch_id is null then 'product' else 'batch' end);

    if v_product_id is null or v_sale_item_id is null or v_quantity <= 0 then
      raise exception 'INVENTORY_ALLOCATION_INVALID' using errcode = 'P0001';
    end if;

    v_movement_idem := coalesce(p_idempotency_key, p_sale_id) || ':inventory:' || v_sale_item_id || ':' || v_product_id || ':' || coalesce(v_batch_id, 'product') || ':' || v_allocation.ordinality::text;

    if v_batch_id is null then
      select * into v_product
      from public.pos_products p
      where p.license_id = p_license_id
        and p.id = v_product_id
        and p.deleted_at is null
      for update;

      if v_product.id is null then
        raise exception 'PRODUCT_NOT_SYNCED_FOR_CLOUD_SALE:%', v_product_id using errcode = 'P0001';
      end if;

      v_previous_stock := coalesce(v_product.stock, 0);

      if greatest(v_previous_stock - coalesce(v_product.committed_stock, 0), 0) < v_quantity then
        raise exception 'INSUFFICIENT_CLOUD_STOCK:%', v_product_id using errcode = 'P0001';
      end if;

      update public.pos_products
      set stock = stock - v_quantity,
          updated_at = now(),
          server_version = server_version + 1,
          updated_by_device_id = p_actor_device_id,
          updated_by_staff_user_id = p_actor_staff_user_id,
          last_idempotency_key = v_movement_idem,
          metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('lastInventorySaleId', p_sale_id, 'lastInventoryMovementAt', now())
      where license_id = p_license_id
        and id = v_product_id
      returning stock, server_version into v_new_stock, v_new_product_version;

      v_movement := private.record_pos_inventory_movement(
        p_license_id, v_product_id, null, p_sale_id, v_sale_item_id,
        'sale_out', v_quantity, v_previous_stock, v_new_stock, null, null,
        v_unit_cost, 'Venta cloud confirmada', 'sale',
        p_actor_device_id, p_actor_staff_user_id, p_actor_key, p_actor_name,
        v_movement_idem,
        jsonb_build_object('stock_source', 'product', 'phase', 'fase6c_cloud_sales_inventory')
      );

      perform private.record_pos_sync_event(p_license_id, 'product', v_product_id, 'update', p_actor_device_id, p_actor_staff_user_id, v_movement_idem, jsonb_build_object('reason', 'sale_inventory_out', 'sale_id', p_sale_id, 'movement_id', v_movement.id), v_new_product_version);
      perform private.record_pos_sale_audit_event(p_license_id, p_sale_id, 'sale.product_stock_updated', p_actor_device_id, p_actor_staff_user_id, p_actor_name, jsonb_build_object('sale_id', p_sale_id, 'sale_item_id', v_sale_item_id, 'product_id', v_product_id, 'quantity', v_quantity, 'stock_before', v_previous_stock, 'stock_after', v_new_stock, 'idempotency_key', v_movement_idem));
    else
      select * into v_batch
      from public.pos_product_batches b
      where b.license_id = p_license_id
        and b.product_id = v_product_id
        and b.id = v_batch_id
        and b.deleted_at is null
      for update;

      if v_batch.id is null then
        raise exception 'CLOUD_BATCH_NOT_AVAILABLE:%', v_batch_id using errcode = 'P0001';
      end if;

      select * into v_product
      from public.pos_products p
      where p.license_id = p_license_id
        and p.id = v_product_id
        and p.deleted_at is null
      for update;

      if v_product.id is null then
        raise exception 'PRODUCT_NOT_SYNCED_FOR_CLOUD_SALE:%', v_product_id using errcode = 'P0001';
      end if;

      v_previous_stock := coalesce(v_product.stock, 0);
      v_previous_batch_stock := coalesce(v_batch.stock, 0);

      if greatest(v_previous_batch_stock - coalesce(v_batch.committed_stock, 0), 0) < v_quantity then
        raise exception 'INSUFFICIENT_CLOUD_STOCK:%', v_product_id using errcode = 'P0001';
      end if;

      update public.pos_product_batches
      set stock = stock - v_quantity,
          updated_at = now(),
          server_version = server_version + 1,
          updated_by_device_id = p_actor_device_id,
          updated_by_staff_user_id = p_actor_staff_user_id,
          last_idempotency_key = v_movement_idem,
          metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('lastInventorySaleId', p_sale_id, 'lastInventoryMovementAt', now())
      where license_id = p_license_id
        and id = v_batch_id
      returning stock, server_version into v_new_batch_stock, v_new_batch_version;

      select coalesce(sum(coalesce(b.stock, 0)) filter (where b.deleted_at is null and b.is_active is true), 0)
      into v_new_stock
      from public.pos_product_batches b
      where b.license_id = p_license_id
        and b.product_id = v_product_id;

      update public.pos_products
      set stock = coalesce(v_new_stock, 0),
          updated_at = now(),
          server_version = server_version + 1,
          updated_by_device_id = p_actor_device_id,
          updated_by_staff_user_id = p_actor_staff_user_id,
          last_idempotency_key = v_movement_idem,
          metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('lastInventorySaleId', p_sale_id, 'lastInventoryMovementAt', now())
      where license_id = p_license_id
        and id = v_product_id
      returning stock, server_version into v_new_stock, v_new_product_version;

      v_movement := private.record_pos_inventory_movement(
        p_license_id, v_product_id, v_batch_id, p_sale_id, v_sale_item_id,
        'sale_out', v_quantity, v_previous_stock, v_new_stock, v_previous_batch_stock, v_new_batch_stock,
        v_unit_cost, 'Venta cloud confirmada', 'sale',
        p_actor_device_id, p_actor_staff_user_id, p_actor_key, p_actor_name,
        v_movement_idem,
        jsonb_build_object('stock_source', 'batch', 'phase', 'fase6c_cloud_sales_inventory', 'fefo', coalesce((v_allocation.payload->>'fefo')::boolean, false))
      );

      perform private.record_pos_sync_event(p_license_id, 'product_batch', v_batch_id, 'update', p_actor_device_id, p_actor_staff_user_id, v_movement_idem, jsonb_build_object('reason', 'sale_inventory_out', 'sale_id', p_sale_id, 'product_id', v_product_id, 'movement_id', v_movement.id), v_new_batch_version);
      perform private.record_pos_sync_event(p_license_id, 'product', v_product_id, 'update', p_actor_device_id, p_actor_staff_user_id, v_movement_idem, jsonb_build_object('reason', 'sale_inventory_out', 'sale_id', p_sale_id, 'batch_id', v_batch_id, 'movement_id', v_movement.id), v_new_product_version);
      perform private.record_pos_sale_audit_event(p_license_id, p_sale_id, 'sale.batch_stock_updated', p_actor_device_id, p_actor_staff_user_id, p_actor_name, jsonb_build_object('sale_id', p_sale_id, 'sale_item_id', v_sale_item_id, 'product_id', v_product_id, 'batch_id', v_batch_id, 'quantity', v_quantity, 'stock_before', v_previous_stock, 'stock_after', v_new_stock, 'batch_stock_before', v_previous_batch_stock, 'batch_stock_after', v_new_batch_stock, 'idempotency_key', v_movement_idem));
    end if;

    v_first_movement_id := coalesce(v_first_movement_id, v_movement.id);
    v_movements := v_movements || jsonb_build_array(private.pos_inventory_movement_to_jsonb(v_movement));

    update public.pos_sale_items
    set inventory_effect_status = 'applied',
        inventory_movement_id = coalesce(inventory_movement_id, v_movement.id),
        stock_source = v_stock_source,
        stock_before = coalesce(stock_before, v_previous_stock),
        stock_after = v_new_stock,
        batch_stock_before = coalesce(batch_stock_before, v_previous_batch_stock),
        batch_stock_after = coalesce(v_new_batch_stock, batch_stock_after),
        batch_id = coalesce(batch_id, v_batch_id),
        metadata = coalesce(metadata, '{}'::jsonb)
          || jsonb_build_object(
            'inventoryEffectStatus', 'applied',
            'stockSource', v_stock_source,
            'inventoryMovementIds', coalesce(metadata->'inventoryMovementIds', '[]'::jsonb) || jsonb_build_array(v_movement.id)
          ),
        server_version = server_version + 1
    where license_id = p_license_id
      and sale_id = p_sale_id
      and id = v_sale_item_id
    returning server_version into v_sale_item_version;

    perform private.record_pos_sync_event(
      p_license_id,
      'sale_item',
      v_sale_item_id,
      'update',
      p_actor_device_id,
      p_actor_staff_user_id,
      v_movement_idem,
      jsonb_build_object('sale_id', p_sale_id, 'reason', 'inventory_effect_applied', 'movement_id', v_movement.id, 'product_id', v_product_id, 'batch_id', v_batch_id),
      coalesce(v_sale_item_version, 1)::integer
    );

    perform private.record_pos_sync_event(
      p_license_id,
      'inventory_movement',
      v_movement.id,
      'create',
      p_actor_device_id,
      p_actor_staff_user_id,
      v_movement_idem,
      jsonb_build_object('sale_id', p_sale_id, 'sale_item_id', v_sale_item_id, 'product_id', v_product_id, 'batch_id', v_batch_id),
      v_movement.server_version::integer
    );

    perform private.record_pos_sale_audit_event(
      p_license_id,
      p_sale_id,
      'sale.inventory_movement_created',
      p_actor_device_id,
      p_actor_staff_user_id,
      p_actor_name,
      jsonb_build_object('sale_id', p_sale_id, 'sale_item_id', v_sale_item_id, 'product_id', v_product_id, 'batch_id', v_batch_id, 'quantity', v_quantity, 'movement_id', v_movement.id, 'idempotency_key', v_movement_idem)
    );
  end loop;

  v_applied_count := jsonb_array_length(v_movements);

  update public.pos_sales
  set inventory_effect_status = case when v_applied_count > 0 then 'applied' else 'not_required' end,
      updated_at = now(),
      server_version = server_version + 1,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'inventoryEffectStatus', case when v_applied_count > 0 then 'applied' else 'not_required' end,
        'inventoryMovementCount', v_applied_count
      )
  where license_id = p_license_id
    and id = p_sale_id;

  perform private.record_pos_sale_audit_event(
    p_license_id,
    p_sale_id,
    'sale.inventory_applied',
    p_actor_device_id,
    p_actor_staff_user_id,
    p_actor_name,
    jsonb_build_object('sale_id', p_sale_id, 'inventory_effect_status', case when v_applied_count > 0 then 'applied' else 'not_required' end, 'movement_count', v_applied_count, 'idempotency_key', p_idempotency_key)
  );

  return jsonb_build_object(
    'success', true,
    'inventory_effect_status', case when v_applied_count > 0 then 'applied' else 'not_required' end,
    'inventory_movements', v_movements
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.assert_cash_permission(p_context jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor_type text := private.resolve_pos_actor_type(p_context);
  v_permissions jsonb := coalesce(p_context->'actor_permissions', p_context->'staff_permissions', '{}'::jsonb);
begin
  if v_actor_type = 'admin' then return; end if;
  if v_actor_type = 'staff' and (coalesce((v_permissions->>'cash_register')::boolean, false) is true or coalesce((v_permissions->>'caja')::boolean, false) is true) then return; end if;
  raise exception 'POS_PERMISSION_DENIED:cash_register' using errcode = 'P0001';
end;
$function$
CREATE OR REPLACE FUNCTION private.assert_cash_sale_station_for_request_v1(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text, p_cash_session_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_device_id uuid;
begin
  if nullif(btrim(p_cash_session_id), '') is null then
    return;
  end if;

  v_context := private.validate_pos_sync_context(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token
  );
  v_license_id := (v_context->>'license_id')::uuid;
  v_device_id := nullif(v_context->>'device_id', '')::uuid;
  perform private.assert_cash_session_station(v_license_id, v_device_id, p_cash_session_id);
end;
$function$
CREATE OR REPLACE FUNCTION private.assert_cash_session_station(p_license_id uuid, p_device_id uuid, p_cash_session_id text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_station public.pos_cash_stations;
  v_session public.pos_cash_sessions;
begin
  v_station := private.resolve_cash_station_for_device(p_license_id, p_device_id, false);
  select * into v_session
  from public.pos_cash_sessions s
  where s.license_id = p_license_id
    and s.id = p_cash_session_id
    and s.deleted_at is null
  for update;

  if v_session.id is null or v_session.cash_station_id is null then
    raise exception 'CASH_STATION_UNRESOLVED' using errcode = 'P0001';
  end if;
  if v_session.cash_station_id <> v_station.id then
    raise exception 'CASH_SESSION_STATION_MISMATCH' using errcode = 'P0001';
  end if;
  return v_station.id;
end;
$function$
CREATE OR REPLACE FUNCTION private.assert_cloud_cash_sync_enabled(p_context jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  perform private.assert_cloud_pos_sync_enabled(p_context);

  if coalesce((p_context->'features'->>'cloud_cash_sync')::boolean, false) is not true then
    raise exception 'CLOUD_CASH_SYNC_DISABLED' using errcode = 'P0001';
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION private.assert_cloud_customer_credit_sync_enabled(p_context jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
begin
  perform private.assert_cloud_pos_sync_enabled(p_context);
  perform private.assert_cloud_cash_sync_enabled(p_context);

  if coalesce((p_context->'features'->>'cloud_customer_credit_sync')::boolean, false) is not true then
    raise exception 'CLOUD_CUSTOMER_CREDIT_SYNC_DISABLED' using errcode = 'P0001';
  end if;
end;
$function$
CREATE OR REPLACE FUNCTION private.assert_cloud_layaways_enabled(p_context jsonb)
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  perform private.assert_cloud_pos_sync_enabled(p_context);
  perform private.assert_cloud_sales_sync_base_enabled(p_context);
  perform private.assert_cloud_cash_sync_enabled(p_context);
  perform private.assert_cloud_products_sync_enabled(p_context);

  -- Deliberately no plan/license backfill exists in this migration.  The
  -- dedicated capability is therefore false everywhere until an explicit
  -- rollout grants `cloud_layaways` to a license/plan.
  if coalesce((p_context->'features'->>'cloud_layaways')::boolean, false) is not true then
    raise exception 'CLOUD_LAYAWAYS_DISABLED' using errcode = 'P0001';
  end if;
end;
