 SET search_path TO ''
AS $function$
begin
  update public.pos_idempotency_keys
  set status = 'completed',
      response_payload = p_response_payload,
      expires_at = now() + interval '7 days'
  where license_id = p_license_id
    and idempotency_key = p_idempotency_key;
end;
$function$
CREATE OR REPLACE FUNCTION private.consume_layaway_stock_v1(p_license_id uuid, p_layaway_id text, p_sale_id text, p_actor_device_id uuid, p_actor_staff_user_id uuid, p_actor_key text, p_actor_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reservation public.pos_layaway_inventory_reservations;
  v_product public.pos_products;
  v_batch public.pos_product_batches;
  v_movement public.pos_inventory_movements;
  v_product_committed numeric;
  v_previous_stock numeric;
  v_new_stock numeric;
  v_previous_batch_stock numeric;
  v_new_batch_stock numeric;
  v_operation_key text;
  v_sale_item_id text;
  v_movements jsonb := '[]'::jsonb;
begin
  for v_reservation in
    select *
      from public.pos_layaway_inventory_reservations r
     where r.license_id = p_license_id
       and r.layaway_id = p_layaway_id
       and r.status = 'reserved'
     order by r.product_id, coalesce(r.batch_id, ''), r.item_index
     for update
  loop
    v_operation_key := coalesce(p_idempotency_key, p_sale_id) || ':inventory:' || v_reservation.item_index::text;
    v_sale_item_id := p_sale_id || ':item:' || v_reservation.item_index::text;
    v_product := null;
    v_batch := null;
    if v_reservation.batch_id is not null then
      select * into v_product
        from public.pos_products p
       where p.license_id = p_license_id and p.id = v_reservation.product_id and p.deleted_at is null
       for update;
      select * into v_batch
        from public.pos_product_batches b
       where b.license_id = p_license_id and b.id = v_reservation.batch_id and b.deleted_at is null
       for update;
      if v_batch.id is null or v_product.id is null then
        raise exception 'LAYAWAY_RESERVATION_SOURCE_MISSING:%', v_reservation.product_id using errcode = 'P0001';
      end if;
      if coalesce(v_batch.stock, 0) < v_reservation.quantity then
        raise exception 'LAYAWAY_RESERVED_STOCK_UNAVAILABLE:%', v_reservation.product_id using errcode = 'P0001';
      end if;
      v_previous_stock := coalesce(v_product.stock, 0);
      v_previous_batch_stock := coalesce(v_batch.stock, 0);
      update public.pos_product_batches
         set stock = stock - v_reservation.quantity,
             committed_stock = greatest(coalesce(committed_stock, 0) - v_reservation.quantity, 0),
             updated_at = now(), server_version = server_version + 1,
             updated_by_device_id = p_actor_device_id,
             updated_by_staff_user_id = p_actor_staff_user_id,
             last_idempotency_key = v_operation_key
       where license_id = p_license_id and id = v_reservation.batch_id
       returning * into v_batch;
      v_new_batch_stock := v_batch.stock;
      select coalesce(sum(coalesce(b.stock, 0)) filter (where b.deleted_at is null and b.is_active is true), 0),
             coalesce(sum(coalesce(b.committed_stock, 0)), 0)
        into v_new_stock, v_product_committed
        from public.pos_product_batches b
       where b.license_id = p_license_id and b.product_id = v_reservation.product_id;
      update public.pos_products
         set stock = v_new_stock,
             committed_stock = v_product_committed,
             updated_at = now(), server_version = server_version + 1,
             updated_by_device_id = p_actor_device_id,
             updated_by_staff_user_id = p_actor_staff_user_id,
             last_idempotency_key = v_operation_key
       where license_id = p_license_id and id = v_reservation.product_id
       returning * into v_product;
      v_movement := private.record_pos_inventory_movement(
        p_license_id, v_reservation.product_id, v_reservation.batch_id, p_sale_id, v_sale_item_id,
        'sale_out', v_reservation.quantity, v_previous_stock, v_new_stock,
        v_previous_batch_stock, v_new_batch_stock, v_reservation.unit_cost,
        'Entrega de apartado cloud', 'sale', p_actor_device_id, p_actor_staff_user_id,
        p_actor_key, p_actor_name, v_operation_key,
        jsonb_build_object('phase', 'cloud_layaways_server_contract_r1', 'layaway_id', p_layaway_id, 'reservation_id', v_reservation.id)
      );
      update public.pos_sale_items
         set inventory_effect_status = 'applied', inventory_movement_id = v_movement.id,
             stock_source = 'batch', stock_before = v_previous_stock, stock_after = v_new_stock,
             batch_stock_before = v_previous_batch_stock, batch_stock_after = v_new_batch_stock
       where license_id = p_license_id and sale_id = p_sale_id and id = v_sale_item_id;
      perform private.record_pos_sync_event(
        p_license_id, 'product_batch', v_reservation.batch_id, 'update', p_actor_device_id,
        p_actor_staff_user_id, v_operation_key,
        jsonb_build_object('reason', 'layaway_stock_consumed', 'layaway_id', p_layaway_id, 'sale_id', p_sale_id, 'movement_id', v_movement.id),
        v_batch.server_version
      );
      perform private.record_pos_sync_event(
        p_license_id, 'product', v_reservation.product_id, 'update', p_actor_device_id,
        p_actor_staff_user_id, v_operation_key,
        jsonb_build_object('reason', 'layaway_stock_consumed', 'layaway_id', p_layaway_id, 'sale_id', p_sale_id, 'movement_id', v_movement.id),
        v_product.server_version
      );
    else
      select * into v_product
        from public.pos_products p
       where p.license_id = p_license_id and p.id = v_reservation.product_id and p.deleted_at is null
       for update;
      if v_product.id is null then
        raise exception 'LAYAWAY_RESERVATION_SOURCE_MISSING:%', v_reservation.product_id using errcode = 'P0001';
      end if;
      if coalesce(v_product.stock, 0) < v_reservation.quantity then
        raise exception 'LAYAWAY_RESERVED_STOCK_UNAVAILABLE:%', v_reservation.product_id using errcode = 'P0001';
      end if;
      v_previous_stock := coalesce(v_product.stock, 0);
      v_new_stock := v_previous_stock - v_reservation.quantity;
      update public.pos_products
         set stock = v_new_stock,
             committed_stock = greatest(coalesce(committed_stock, 0) - v_reservation.quantity, 0),
             updated_at = now(), server_version = server_version + 1,
             updated_by_device_id = p_actor_device_id,
             updated_by_staff_user_id = p_actor_staff_user_id,
             last_idempotency_key = v_operation_key
       where license_id = p_license_id and id = v_reservation.product_id
       returning * into v_product;
      v_new_stock := v_product.stock;
      v_movement := private.record_pos_inventory_movement(
        p_license_id, v_reservation.product_id, null, p_sale_id, v_sale_item_id,
        'sale_out', v_reservation.quantity, v_previous_stock, v_new_stock,
        null, null, v_reservation.unit_cost, 'Entrega de apartado cloud', 'sale',
        p_actor_device_id, p_actor_staff_user_id, p_actor_key, p_actor_name,
        v_operation_key,
        jsonb_build_object('phase', 'cloud_layaways_server_contract_r1', 'layaway_id', p_layaway_id, 'reservation_id', v_reservation.id)
      );
      update public.pos_sale_items
         set inventory_effect_status = 'applied', inventory_movement_id = v_movement.id,
             stock_source = 'product', stock_before = v_previous_stock, stock_after = v_new_stock
       where license_id = p_license_id and sale_id = p_sale_id and id = v_sale_item_id;
      perform private.record_pos_sync_event(
        p_license_id, 'product', v_reservation.product_id, 'update', p_actor_device_id,
        p_actor_staff_user_id, v_operation_key,
        jsonb_build_object('reason', 'layaway_stock_consumed', 'layaway_id', p_layaway_id, 'sale_id', p_sale_id, 'movement_id', v_movement.id),
        v_product.server_version
      );
    end if;

    update public.pos_layaway_inventory_reservations
       set status = 'consumed', consumed_at = now(), server_version = server_version + 1,
           idempotency_key = v_operation_key,
           metadata = coalesce(metadata, '{}'::jsonb)
             || jsonb_build_object('consumedByActorKey', p_actor_key, 'sale_id', p_sale_id, 'movement_id', v_movement.id)
     where license_id = p_license_id and id = v_reservation.id;
    v_movements := v_movements || jsonb_build_array(private.pos_inventory_movement_to_jsonb(v_movement));
  end loop;

  return v_movements;
end;
$function$
CREATE OR REPLACE FUNCTION private.derive_pos_operational_prefix_v1(p_license_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_business_name text;
  v_normalized_name text;
  v_parts text[];
begin
  if p_license_id is null then
    return 'LZ';
  end if;

  select b.business_name
    into v_business_name
    from public.business_profiles b
   where b.license_id = p_license_id
   order by b.updated_at desc nulls last, b.created_at desc nulls last, b.id
   limit 1;

  v_normalized_name := btrim(regexp_replace(
    upper(coalesce(v_business_name, '')),
    '[^A-Z0-9ÁÉÍÓÚÜÑ]+',
    ' ',
    'g'
  ));

  if v_normalized_name = '' then
    return 'LZ';
  end if;

  v_parts := regexp_split_to_array(v_normalized_name, '\s+');

  if coalesce(array_length(v_parts, 1), 0) >= 2 then
    return left(v_parts[1], 1) || left(v_parts[2], 1);
  end if;

  if length(v_parts[1]) = 1 then
    return v_parts[1] || 'X';
  end if;

  return left(v_parts[1], 2);
exception
  when others then
    return 'LZ';
end;
$function$
CREATE OR REPLACE FUNCTION private.execute_admin_cash_close_v2(p_license_id uuid, p_device_id uuid, p_admin_user_id uuid, p_admin_session_id uuid, p_admin_name text, p_actor_key text, p_cash_session_id text, p_closing_mode text, p_counted_amount numeric, p_next_shift_fund numeric, p_reason_code text, p_comments text, p_expected_version integer, p_idempotency_key text, p_operation_type text, p_reconciliation_source text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_session public.pos_cash_sessions;
  v_event public.pos_sync_events;
  v_response jsonb;
  v_idem public.pos_idempotency_keys;
  v_inserted_idem boolean;
  v_mode text := lower(nullif(btrim(coalesce(p_closing_mode, '')), ''));
  v_reason text := lower(nullif(btrim(coalesce(p_reason_code, '')), ''));
  v_comments text := nullif(btrim(coalesce(p_comments, '')), '');
  v_counted numeric := p_counted_amount;
  v_next_fund numeric := coalesce(p_next_shift_fund, 0);
  v_difference numeric := null;
  v_reconciliation text;
  v_event_type text;
  v_expected_before numeric;
  v_entries_before numeric;
  v_exits_before numeric;
  v_request_hash text := null;
  v_bridge_evidence jsonb := null;
  v_audit_extra jsonb := '{}'::jsonb;
begin
  if p_license_id is null or p_device_id is null or p_admin_user_id is null or p_admin_session_id is null then
    raise exception 'ADMIN_SESSION_REQUIRED' using errcode = 'P0001';
  end if;
  if v_mode not in ('admin_audited', 'admin_unverified') then
    raise exception 'ADMIN_CLOSE_MODE_INVALID' using errcode = 'P0001';
  end if;
  if v_reason not in ('historical_test', 'device_replaced', 'device_lost', 'abandoned_session', 'operational_error', 'other') then
    raise exception 'ADMIN_CLOSE_REASON_REQUIRED' using errcode = 'P0001';
  end if;
  if (v_reason = 'other' or v_mode = 'admin_unverified') and v_comments is null then
    raise exception 'ADMIN_CLOSE_COMMENT_REQUIRED' using errcode = 'P0001';
  end if;
  if v_mode = 'admin_audited' and (v_counted is null or v_counted < 0) then
    raise exception 'ADMIN_CLOSE_COUNTED_AMOUNT_REQUIRED' using errcode = 'P0001';
  end if;
  if v_mode = 'admin_unverified' and v_counted is not null then
    raise exception 'ADMIN_CLOSE_UNVERIFIED_COUNTED_FORBIDDEN' using errcode = 'P0001';
  end if;
  if v_next_fund < 0 then
    raise exception 'NEXT_SHIFT_FUND_INVALID' using errcode = 'P0001';
  end if;
  if v_mode = 'admin_unverified' and v_next_fund <> 0 then
    raise exception 'ADMIN_CLOSE_UNVERIFIED_NEXT_FUND_FORBIDDEN' using errcode = 'P0001';
  end if;
  if v_mode = 'admin_audited' and v_next_fund > v_counted then
    raise exception 'NEXT_SHIFT_FUND_EXCEEDS_COUNTED' using errcode = 'P0001';
  end if;

  if p_reconciliation_source = 'POST_DOWNGRADE_CASH_RECONCILIATION' then
    v_request_hash := encode(extensions.digest(
      jsonb_build_object(
        'cash_session_id', p_cash_session_id,
        'closing_mode', v_mode,
        'counted_amount', v_counted,
        'next_shift_fund', v_next_fund,
        'reason_code', v_reason,
        'comments', v_comments,
        'expected_version', p_expected_version,
        'operation_type', p_operation_type
      )::text,
      'sha256'
    ), 'hex');
  end if;

  v_inserted_idem := private.insert_pos_idempotency_processing(
    p_license_id,
    p_idempotency_key,
    p_operation_type,
    'cash_session',
    p_cash_session_id,
    v_request_hash
  );

  if not v_inserted_idem then
    select * into v_idem
    from public.pos_idempotency_keys
    where license_id = p_license_id
      and idempotency_key = p_idempotency_key
    limit 1;

    if p_reconciliation_source = 'POST_DOWNGRADE_CASH_RECONCILIATION'
       and (
         v_idem.operation_type is distinct from p_operation_type
         or v_idem.entity_type is distinct from 'cash_session'
         or v_idem.entity_id is distinct from p_cash_session_id
       ) then
      raise exception 'IDEMPOTENCY_CONFLICT' using errcode = 'P0001';
    end if;

    if v_idem.status = 'completed' and v_idem.response_payload is not null then
      return v_idem.response_payload;
    end if;

    return jsonb_build_object(
      'success', false,
      'code', 'IDEMPOTENCY_PROCESSING',
      'message', 'El cierre administrativo ya esta en proceso.',
      'idempotency_key', p_idempotency_key
    );
  end if;

  select * into v_session
  from public.pos_cash_sessions s
  where s.license_id = p_license_id
    and s.id = p_cash_session_id
    and s.deleted_at is null
  for update;

  if v_session.id is null then
    raise exception 'CASH_SESSION_NOT_FOUND' using errcode = 'P0001';
  end if;

  if v_session.status <> 'open' then
    if p_reconciliation_source = 'POST_DOWNGRADE_CASH_RECONCILIATION' then
      raise exception 'POST_DOWNGRADE_CASH_ALREADY_CLOSED' using errcode = 'P0001';
    end if;
    raise exception 'CASH_SESSION_NOT_OPEN' using errcode = 'P0001';
  end if;

  if p_reconciliation_source = 'POST_DOWNGRADE_CASH_RECONCILIATION' then
    v_bridge_evidence := private.post_downgrade_cash_session_evidence_v1(p_license_id, p_cash_session_id);
    if v_bridge_evidence is null then
      raise exception 'POST_DOWNGRADE_CASH_NOT_ELIGIBLE' using errcode = 'P0001';
    end if;

    v_audit_extra := jsonb_build_object(
      'reconciliation_source', 'POST_DOWNGRADE_CASH_RECONCILIATION',
      'downgraded_at', v_bridge_evidence->>'downgraded_at',
      'boundary_source', v_bridge_evidence->>'boundary_source',
      'previous_plan_code', v_bridge_evidence->>'previous_plan_code',
      'opening_plan_code', v_bridge_evidence->>'opening_plan_code',
      'downgrade_event_id', v_bridge_evidence->>'downgrade_event_id',
      'opening_plan_event_id', v_bridge_evidence->>'opening_plan_event_id'
    );
  end if;

  if p_expected_version is null or p_expected_version <> v_session.server_version then
    v_response := jsonb_build_object(
      'success', false,
      'code', 'VERSION_CONFLICT',
      'message', 'La caja cambio desde que la revisaste. Actualizamos los datos; vuelve a confirmar el cierre.',
      'cash_session', private.pos_cash_session_to_jsonb(v_session),
      'idempotency_key', p_idempotency_key
    );
    perform private.complete_pos_idempotency(p_license_id, p_idempotency_key, v_response);
    return v_response;
  end if;

  v_expected_before := v_session.expected_cash_total;
  v_entries_before := v_session.cash_entries_total;
  v_exits_before := v_session.cash_exits_total;
  v_session := private.recalculate_pos_cash_session_totals(p_license_id, v_session.id, false);

  if v_session.expected_cash_total is distinct from v_expected_before
     or v_session.cash_entries_total is distinct from v_entries_before
     or v_session.cash_exits_total is distinct from v_exits_before then
    update public.pos_cash_sessions
    set server_version = server_version + 1,
        updated_at = now()
    where license_id = p_license_id
      and id = v_session.id
    returning * into v_session;

    v_response := jsonb_build_object(
      'success', false,
      'code', 'CASH_TOTALS_CHANGED',
      'message', 'La caja cambio mientras la revisabas. Actualizamos el efectivo esperado; revisa nuevamente los datos antes de confirmar.',
      'cash_session', private.pos_cash_session_to_jsonb(v_session),
      'cash_total_snapshot_before_recalculation', jsonb_build_object(
        'expected_cash_total', v_expected_before,
        'cash_entries_total', v_entries_before,
        'cash_exits_total', v_exits_before
      ),
      'idempotency_key', p_idempotency_key
    );
    perform private.complete_pos_idempotency(p_license_id, p_idempotency_key, v_response);
    return v_response;
  end if;

  if v_mode = 'admin_audited' then
    v_difference := v_counted - v_session.expected_cash_total;
    v_reconciliation := case when v_difference = 0 then 'verified' else 'verified_with_difference' end;
    v_event_type := 'ADMIN_CLOSED_AUDITED';
  else
    v_counted := null;
    v_next_fund := 0;
    v_reconciliation := 'unverified';
    v_event_type := 'ADMIN_CLOSED_UNVERIFIED';
  end if;

  update public.pos_cash_sessions
  set status = 'closed',
      closed_at = now(),
      closing_counted_amount = v_counted,
      next_shift_fund = v_next_fund,
      cash_difference = v_difference,
      closing_mode = v_mode,
      reconciliation_status = v_reconciliation,
      closure_reason_code = v_reason,
      closed_by_device_id = p_device_id,
      closed_by_staff_user_id = null,
      closed_by_admin_user_id = p_admin_user_id,
      closed_by_actor_key = p_actor_key,
      audit_comments = v_comments,
      close_detail = jsonb_build_object(
        'closing_mode', v_mode,
        'reconciliation_status', v_reconciliation,
        'reason_code', v_reason,
        'comments', v_comments,
        'expected_cash_total', v_session.expected_cash_total,
        'closing_counted_amount', v_counted,
        'cash_difference', v_difference,
        'next_shift_fund', v_next_fund,
        'closed_by_admin_user_id', p_admin_user_id,
        'closed_by_admin_session_id', p_admin_session_id,
        'closed_by_device_id', p_device_id,
        'closed_from_server_version', v_session.server_version
      ) || v_audit_extra,
      updated_at = now(),
      server_version = server_version + 1,
      last_idempotency_key = p_idempotency_key
  where license_id = p_license_id
    and id = v_session.id
  returning * into v_session;

  insert into public.pos_cash_audit_events (
    license_id,
    cash_session_id,
    event_type,
    actor_device_id,
    actor_staff_user_id,
    actor_admin_user_id,
    actor_name,
    payload
  ) values (
    p_license_id,
    v_session.id,
    v_event_type,
    p_device_id,
    null,
    p_admin_user_id,
    p_admin_name,
    jsonb_strip_nulls(jsonb_build_object(
      'admin_user_id', p_admin_user_id,
      'admin_session_id', p_admin_session_id,
      'device_id', p_device_id,
      'expected_cash_total', v_session.expected_cash_total,
      'counted_amount', v_counted,
      'cash_difference', v_difference,
      'next_shift_fund', v_next_fund,
      'reason_code', v_reason,
      'comment', v_comments,
      'closing_mode', v_mode,
      'reconciliation_status', v_reconciliation,
      'closed_from_server_version', v_session.server_version - 1
    ) || v_audit_extra)
  );

  v_event := private.record_pos_sync_event(
    p_license_id,
    'cash_session',
    v_session.id,
    'close',
    p_device_id,
    null,
    p_idempotency_key,
    jsonb_build_object(
      'cash_session_id', v_session.id,
      'actor_key', v_session.actor_key,
      'closing_mode', v_mode,
      'admin_user_id', p_admin_user_id
    ) || v_audit_extra,
    v_session.server_version
  );

  v_response := jsonb_build_object(
    'success', true,
    'cash_session', private.pos_cash_session_to_jsonb(v_session),
    'event', to_jsonb(v_event),
    'change_seq', v_event.change_seq,
    'idempotency_key', p_idempotency_key
  );
  perform private.complete_pos_idempotency(p_license_id, p_idempotency_key, v_response);
  return v_response;
end;
$function$
CREATE OR REPLACE FUNCTION private.execute_layaway_cancel_financial_v1(p_context jsonb, p_request jsonb, p_idempotency_key text, p_request_hash text, p_cash_station_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_license_id uuid := (p_context->>'license_id')::uuid;
  v_device_id uuid := nullif(p_context->>'device_id', '')::uuid;
  v_staff_user_id uuid := nullif(p_context->>'staff_user_id', '')::uuid;
  v_actor_key text := private.resolve_cash_actor_key(p_context);
  v_actor_name text := private.resolve_cash_actor_name(p_context);
  v_layaway_id text := private.layaway_request_id_v1(p_request);
  v_cash_session_id text := private.layaway_request_cash_session_id_v1(p_request);
  v_retain_money boolean := private.layaway_request_bool_v1(p_request, array['retain_money','retainMoney','retained_money']);
  v_refund_id text;
  v_layaway public.pos_layaways;
  v_session public.pos_cash_sessions;
  v_cash_movement public.pos_cash_movements;
  v_event public.pos_sync_events;
  v_reservations jsonb := '[]'::jsonb;
  v_payments jsonb := '[]'::jsonb;
  v_cash_movements jsonb := '[]'::jsonb;
  v_latest_change_seq bigint;
  v_reason text := private.layaway_request_text_v1(p_request, array['reason','motivo'], 'Cancelación de apartado');
begin
  perform private.assert_cloud_layaways_enabled(p_context);
  perform private.assert_pos_permission(p_context, 'pos');
  if v_layaway_id is null then
    raise exception 'LAYAWAY_ID_REQUIRED' using errcode = 'P0001';
  end if;

  select * into v_layaway
    from public.pos_layaways l
   where l.license_id = v_license_id and l.id = v_layaway_id
   for update;
  if v_layaway.id is null then
    raise exception 'LAYAWAY_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_layaway.status = 'completed' then
    raise exception 'LAYAWAY_ALREADY_COMPLETED' using errcode = 'P0001';
  end if;
  if v_layaway.status = 'cancelled' then
    raise exception 'LAYAWAY_ALREADY_CANCELLED' using errcode = 'P0001';
  end if;

  if not v_retain_money and v_layaway.paid_amount > 0 then
    v_session := private.layaway_cash_session_v1(
      v_license_id, v_device_id, v_actor_key, v_cash_session_id, p_cash_station_id
    );
    v_session := private.recalculate_pos_cash_session_totals(v_license_id, v_session.id, false);
    if coalesce(v_session.expected_cash_total, 0) + 0.005 < v_layaway.paid_amount then
      raise exception 'CASH_INSUFFICIENT_FOR_LAYAWAY_REFUND' using errcode = 'P0001';
    end if;
    v_refund_id := coalesce(
      private.layaway_request_text_v1(p_request, array['refund_id','refundId']),
      v_layaway_id || ':refund'
    );
    insert into public.pos_cash_movements (
      id, license_id, cash_session_id, device_id, staff_user_id, actor_key,
      type, amount, concept, source, reference_type, reference_id,
      created_by_device_id, created_by_staff_user_id, actor_name,
      cash_station_id, performed_by_actor_key, idempotency_key, metadata
    ) values (
      'mov_' || replace(gen_random_uuid()::text, '-', ''), v_license_id, v_session.id,
      v_session.device_id, v_session.staff_user_id, v_session.actor_key,
      'salida', round(v_layaway.paid_amount, 2), 'Reembolso Apartado ' || v_layaway_id,
      'layaway_refund', 'layaway', v_layaway_id,
      v_device_id, v_staff_user_id, v_actor_name,
      v_session.cash_station_id, v_actor_key, p_idempotency_key || ':refund_cash',
      jsonb_build_object(
        'phase', 'cloud_layaways_server_contract_r1',
        'source', 'layaway_refund',
        'layaway_id', v_layaway_id,
        'refund_id', v_refund_id,
        'refund_amount', round(v_layaway.paid_amount, 2),
        'idempotency_key', p_idempotency_key
      )
    ) returning * into v_cash_movement;
    v_session := private.recalculate_pos_cash_session_totals(v_license_id, v_session.id, true);
    update public.pos_layaway_payments
       set status = 'refunded', refunded_at = now(), server_version = server_version + 1,
           metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('refund_id', v_refund_id)
     where license_id = v_license_id and layaway_id = v_layaway_id and status = 'confirmed';
  else
    v_refund_id := private.layaway_request_text_v1(p_request, array['refund_id','refundId']);
  end if;

  v_reservations := private.release_layaway_stock_v1(
    v_license_id, v_layaway_id, v_device_id, v_staff_user_id,
    v_actor_key, v_actor_name, p_idempotency_key
  );
  update public.pos_layaways
     set status = 'cancelled', cancelled_at = now(), updated_at = now(),
         server_version = server_version + 1, last_idempotency_key = p_idempotency_key,
         retained_money = v_retain_money,
         retained_amount = case when v_retain_money then paid_amount else 0 end,
         refund_id = case when v_retain_money then null else v_refund_id end,
         refund_cash_movement_id = case when v_cash_movement.id is null then null else v_cash_movement.id end,
         notes = v_reason || case when v_retain_money then ' - Fondos retenidos' else ' - Fondos reembolsados' end,
         metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
           'cancel_reason', v_reason,
           'refund_id', v_refund_id,
           'refund_amount', case when v_retain_money then 0 else paid_amount end,
           'retained_money', v_retain_money
         )
   where license_id = v_license_id and id = v_layaway_id
   returning * into v_layaway;

  v_event := private.record_pos_sync_event(
    v_license_id, 'layaway', v_layaway_id, 'cancel', v_device_id, v_staff_user_id,
    p_idempotency_key,
    jsonb_build_object('reason', v_reason, 'retain_money', v_retain_money,
      'refund_id', v_refund_id, 'cash_movement_id', case when v_cash_movement.id is null then null else v_cash_movement.id end),
    v_layaway.server_version::integer
  );
  if v_cash_movement.id is not null then
    perform private.record_pos_sync_event(
      v_license_id, 'cash_movement', v_cash_movement.id, 'create', v_device_id, v_staff_user_id,
      p_idempotency_key, jsonb_build_object('layaway_id', v_layaway_id, 'refund_id', v_refund_id),
      v_cash_movement.server_version
    );
  end if;

  select coalesce(jsonb_agg(private.pos_layaway_payment_financial_to_jsonb_v2(p) order by p.created_at, p.id), '[]'::jsonb)
    into v_payments
    from public.pos_layaway_payments p
   where p.license_id = v_license_id and p.layaway_id = v_layaway_id;
  select coalesce(jsonb_agg(private.pos_layaway_cash_movement_financial_to_jsonb_v2(m) order by m.created_at, m.id), '[]'::jsonb)
    into v_cash_movements
    from public.pos_cash_movements m
   where m.license_id = v_license_id and m.reference_type = 'layaway' and m.reference_id = v_layaway_id;
  select coalesce(max(change_seq), 0) into v_latest_change_seq
    from public.pos_sync_events where license_id = v_license_id;

  return jsonb_build_object(
    'success', true,
    'mode', 'cloud_layaway',
    'layaway', private.pos_layaway_financial_to_jsonb_v2(v_layaway),
    'payments', v_payments,
    'inventory_reservations', private.financial_layaway_reservations_allowlist_v2(v_reservations),
    'cash_movements', v_cash_movements,
    'cash_movement', case when v_cash_movement.id is null then null else private.pos_layaway_cash_movement_financial_to_jsonb_v2(v_cash_movement) end,
    'cash_session', null,
    'folio', null,
    'sale', null,
    'event', private.pos_layaway_event_financial_to_jsonb_v2(v_event),
    'change_seq', v_event.change_seq,
    'latest_change_seq', v_latest_change_seq,
    'idempotency_key', p_idempotency_key
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.execute_layaway_completion_financial_v1(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text, p_request jsonb, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_device_id uuid;
  v_staff_user_id uuid;
  v_actor_key text;
  v_actor_name text;
  v_layaway_id text;
  v_sale_id text;
  v_local_sale_id text;
  v_sale_payload jsonb;
  v_request_items jsonb;
  v_request_payments jsonb;
  v_server_items jsonb;
  v_request_normalized jsonb;
  v_layaway public.pos_layaways;
  v_existing public.pos_sales;
  v_sale public.pos_sales;
  v_sale_payment public.pos_sale_payments;
  v_item jsonb;
  v_payment jsonb;
  v_item_id text;
  v_payment_id text;
  v_item_index integer := 0;
  v_item_count integer;
  v_total numeric;
  v_paid_total numeric;
  v_requested_total numeric;
  v_unit_price numeric;
  v_quantity numeric;
  v_line_total numeric;
  v_line_subtotal numeric;
  v_unit_cost numeric;
  v_discount numeric;
  v_tax numeric;
  v_subtotal numeric;
  v_discount_total numeric;
  v_folio jsonb;
  v_cloud_folio text;
  v_pos_folio text;
  v_folio_sequence bigint;
  v_sold_at timestamptz;
  v_created_at timestamptz;
  v_event public.pos_sync_events;
  v_inventory_movements jsonb := '[]'::jsonb;
  v_sale_items jsonb := '[]'::jsonb;
  v_sale_payments jsonb := '[]'::jsonb;
  v_layaway_payments jsonb := '[]'::jsonb;
  v_cash_movements jsonb := '[]'::jsonb;
  v_latest_change_seq bigint;
begin
  if jsonb_typeof(coalesce(p_request, '{}'::jsonb)) <> 'object' then
    raise exception 'FINANCIAL_LAYAWAY_CONTRACT_INVALID' using errcode = 'P0001';
  end if;

  v_context := private.validate_pos_sync_context(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token
  );
  perform private.assert_cloud_layaways_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'pos');
  v_license_id := (v_context->>'license_id')::uuid;
  v_device_id := nullif(v_context->>'device_id', '')::uuid;
  v_staff_user_id := nullif(v_context->>'staff_user_id', '')::uuid;
  v_actor_key := private.resolve_cash_actor_key(v_context);
  v_actor_name := private.resolve_cash_actor_name(v_context);

  v_layaway_id := private.layaway_request_text_v1(p_request, array['layaway_id','layawayId']);
  if v_layaway_id is null then
    raise exception 'LAYAWAY_ID_REQUIRED' using errcode = 'P0001';
  end if;
  perform pg_advisory_xact_lock(hashtext(v_license_id::text), hashtext('layaway_completion:' || v_layaway_id));

  select * into v_layaway
    from public.pos_layaways l
   where l.license_id = v_license_id and l.id = v_layaway_id
   for update;
  if v_layaway.id is null then
    raise exception 'LAYAWAY_NOT_FOUND' using errcode = 'P0001';
  end if;

  v_sale_payload := coalesce(p_request->'sale', '{}'::jsonb);
  if jsonb_typeof(v_sale_payload) <> 'object' then
    raise exception 'FINANCIAL_LAYAWAY_CONTRACT_INVALID' using errcode = 'P0001';
  end if;
  v_sale_id := private.layaway_request_text_v1(v_sale_payload, array['id','cloud_sale_id','cloudSaleId']);
  v_local_sale_id := coalesce(
    private.layaway_request_text_v1(v_sale_payload, array['local_sale_id','localSaleId']), v_sale_id
  );
  if v_sale_id is null or v_local_sale_id is null then
    raise exception 'LAYAWAY_SALE_ID_REQUIRED' using errcode = 'P0001';
  end if;

  select * into v_existing
    from public.pos_sales s
   where s.license_id = v_license_id
     and s.layaway_id = v_layaway_id
     and s.deleted_at is null
   limit 1
   for update;
  if v_existing.id is not null then
    if v_existing.id is distinct from v_sale_id then
      raise exception 'LAYAWAY_ALREADY_CONVERTED_CLOUD' using errcode = 'P0001';
    end if;
    select coalesce(jsonb_agg(private.pos_layaway_sale_item_financial_to_jsonb_v2(i) order by i.created_at, i.id), '[]'::jsonb)
      into v_sale_items
      from public.pos_sale_items i
     where i.license_id = v_license_id and i.sale_id = v_existing.id;
    select coalesce(jsonb_agg(private.pos_layaway_sale_payment_financial_to_jsonb_v2(p) order by p.created_at, p.id), '[]'::jsonb)
      into v_sale_payments
      from public.pos_sale_payments p
     where p.license_id = v_license_id and p.sale_id = v_existing.id;
    select coalesce(jsonb_agg(private.pos_layaway_payment_financial_to_jsonb_v2(p) order by p.created_at, p.id), '[]'::jsonb)
      into v_layaway_payments
      from public.pos_layaway_payments p
     where p.license_id = v_license_id and p.layaway_id = v_layaway_id;
    select coalesce(jsonb_agg(private.pos_layaway_cash_movement_financial_to_jsonb_v2(m) order by m.created_at, m.id), '[]'::jsonb)
      into v_cash_movements
      from public.pos_cash_movements m
     where m.license_id = v_license_id
       and m.reference_type = 'layaway'
       and m.reference_id = v_layaway_id;
    select coalesce(jsonb_agg(private.pos_layaway_inventory_movement_financial_to_jsonb_v2(m) order by m.created_at, m.id), '[]'::jsonb)
      into v_inventory_movements
      from public.pos_inventory_movements m
     where m.license_id = v_license_id and m.sale_id = v_existing.id;
    select coalesce(max(change_seq), 0) into v_latest_change_seq
      from public.pos_sync_events where license_id = v_license_id;
    return jsonb_build_object(
      'success', true,
      'duplicate', true,
      'mode', 'cloud_layaway_completion',
      'layaway', private.pos_layaway_financial_to_jsonb_v2(v_layaway),
      'sale', private.pos_layaway_sale_financial_to_jsonb_v2(v_existing),
      'items', v_sale_items,
      'payments', v_sale_payments,
      'layaway_payments', v_layaway_payments,
      'cash_movements', v_cash_movements,
      'cash_movement', null,
      'inventory_movements', private.financial_inventory_movements_allowlist_v2(v_inventory_movements),
      'folio', v_existing.pos_folio,
      'cash_session', null,
      'event', null,
      'change_seq', v_latest_change_seq,
      'latest_change_seq', v_latest_change_seq,
      'idempotency_key', p_idempotency_key
    );
  end if;

  if v_layaway.status = 'cancelled' then
    raise exception 'LAYAWAY_ALREADY_CANCELLED' using errcode = 'P0001';
  end if;
  if v_layaway.status = 'completed' then
    raise exception 'LAYAWAY_COMPLETED_WITHOUT_SALE' using errcode = 'P0001';
  end if;
  v_total := round(v_layaway.total_amount, 2);
  select coalesce(sum(p.amount), 0)
    into v_paid_total
    from public.pos_layaway_payments p
   where p.license_id = v_license_id and p.layaway_id = v_layaway_id and p.status = 'confirmed';
  if abs(v_paid_total - v_total) > 0.005 or abs(v_layaway.paid_amount - v_total) > 0.005 then
    raise exception 'LAYAWAY_PAYMENT_TOTAL_MISMATCH' using errcode = 'P0001';
  end if;

  v_request_items := coalesce(p_request->'items', '[]'::jsonb);
  v_request_payments := coalesce(p_request->'payments', '[]'::jsonb);
  if jsonb_typeof(v_request_items) <> 'array' or jsonb_typeof(v_request_payments) <> 'array' then
    raise exception 'FINANCIAL_LAYAWAY_CONTRACT_INVALID' using errcode = 'P0001';
  end if;
  if jsonb_array_length(v_request_payments) <> 1 then
    raise exception 'FINANCIAL_LAYAWAY_PAYMENTS_INVALID' using errcode = 'P0001';
  end if;
  v_requested_total := private.layaway_request_numeric_v1(v_sale_payload, array['total']);
  if v_requested_total is not null and abs(v_requested_total - v_total) > 0.005 then
    raise exception 'LAYAWAY_TOTAL_MISMATCH' using errcode = 'P0001';
  end if;
  if jsonb_array_length(v_request_items) <> jsonb_array_length(v_layaway.items) then
    raise exception 'LAYAWAY_ITEMS_MISMATCH' using errcode = 'P0001';
  end if;
  v_request_normalized := private.normalize_layaway_items_v1(v_request_items, v_total);
  if (
    select coalesce(jsonb_agg(private.canonical_layaway_item_v1(value) order by ordinality), '[]'::jsonb)
      from jsonb_array_elements(v_request_normalized->'items') with ordinality
  ) is distinct from (
    select coalesce(jsonb_agg(private.canonical_layaway_item_v1(value) order by ordinality), '[]'::jsonb)
      from jsonb_array_elements(v_layaway.items) with ordinality
  ) then
    raise exception 'LAYAWAY_ITEMS_MISMATCH' using errcode = 'P0001';
  end if;
  for v_payment in select value from jsonb_array_elements(v_request_payments) loop
    if lower(coalesce(private.layaway_request_text_v1(v_payment, array['method','payment_method','paymentMethod']), '')) <> 'layaway_completed'
       or abs(coalesce(private.layaway_request_numeric_v1(v_payment, array['amount','total']), 0) - v_total) > 0.005 then
      raise exception 'FINANCIAL_LAYAWAY_PAYMENTS_INVALID' using errcode = 'P0001';
    end if;
  end loop;

  v_server_items := v_layaway.items;
  v_item_count := jsonb_array_length(v_server_items);
  if v_item_count <= 0 then
    raise exception 'LAYAWAY_ITEMS_REQUIRED' using errcode = 'P0001';
  end if;

  -- Recompute the financial breakdown from the server snapshot.  The client
  -- may replay the same layaway, but it never gets to choose the sale totals
  -- recorded at delivery.
  v_subtotal := 0;
  v_discount_total := 0;
  for v_item in select value from jsonb_array_elements(v_server_items) loop
    v_quantity := private.layaway_request_numeric_v1(v_item, array['quantity','qty']);
    v_unit_price := private.layaway_request_numeric_v1(v_item, array['unit_price','unitPrice','price']);
    if v_quantity is null or v_quantity <= 0 or v_unit_price is null or v_unit_price < 0 then
      raise exception 'LAYAWAY_ITEM_AMOUNT_INVALID' using errcode = 'P0001';
    end if;
    v_line_subtotal := round(v_quantity * v_unit_price, 2);
    v_discount := greatest(coalesce(private.layaway_request_numeric_v1(
      v_item, array['discount_amount','discountAmount'], 0
    ), 0), 0);
    v_tax := greatest(coalesce(private.layaway_request_numeric_v1(
      v_item, array['tax_amount','taxAmount'], 0
    ), 0), 0);
    if v_discount > v_line_subtotal + 0.005 then
      raise exception 'DISCOUNT_AMOUNT_INVALID' using errcode = 'P0001';
    end if;
    if v_tax > 0.005 then
      raise exception 'LAYAWAY_TAX_SOURCE_UNRESOLVED' using errcode = 'P0001';
    end if;
    v_line_total := round(v_line_subtotal - v_discount, 2);
    if private.layaway_request_numeric_v1(v_item, array['line_subtotal','lineSubtotal'], null) is not null
       and abs(private.layaway_request_numeric_v1(v_item, array['line_subtotal','lineSubtotal'], null) - v_line_subtotal) > 0.005 then
      raise exception 'LAYAWAY_ITEM_TOTAL_MISMATCH' using errcode = 'P0001';
    end if;
    if private.layaway_request_numeric_v1(v_item, array['line_total','lineTotal','total','exactTotal'], null) is not null
       and abs(private.layaway_request_numeric_v1(v_item, array['line_total','lineTotal','total','exactTotal'], null) - v_line_total) > 0.005 then
      raise exception 'LAYAWAY_ITEM_TOTAL_MISMATCH' using errcode = 'P0001';
    end if;
    v_subtotal := v_subtotal + v_line_subtotal;
    v_discount_total := v_discount_total + v_discount;
  end loop;
  if abs(round(v_subtotal - v_discount_total, 2) - v_total) > 0.005 then
    raise exception 'LAYAWAY_TOTAL_MISMATCH' using errcode = 'P0001';
  end if;

  begin
    v_sold_at := coalesce(
      nullif(private.layaway_request_text_v1(v_sale_payload, array['sold_at','soldAt','timestamp']), '')::timestamptz,
      now()
    );
    v_created_at := coalesce(
      nullif(private.layaway_request_text_v1(v_sale_payload, array['created_at','createdAt','timestamp']), '')::timestamptz,
      v_sold_at
    );
  exception when invalid_text_representation or datetime_field_overflow then
    raise exception 'LAYAWAY_TIMESTAMP_INVALID' using errcode = 'P0001';
  end;

  v_folio := private.next_pos_sale_folio(v_license_id);
  v_cloud_folio := v_folio->>'folio';
  v_pos_folio := v_folio->>'pos_folio';
  v_folio_sequence := (v_folio->>'sequence')::bigint;

  insert into public.pos_sales (
    id, license_id, local_sale_id, device_id, staff_user_id, device_role, actor_key, actor_name,
    origin, source_mode, effects_status, status, fulfillment_status,
    payment_method, payment_status, folio, local_folio, cloud_folio, pos_folio, folio_sequence,
    sale_number, customer_id, customer_name, customer_phone,
    subtotal, discount_total, tax_total, total, amount_paid, change_amount, balance_due, currency,
    sold_at, created_at, updated_at, committed_at,
    cash_session_id, cash_movement_id, customer_ledger_id,
    cash_effect_status, inventory_effect_status, credit_effect_status,
    local_payload, metadata, idempotency_key, server_version, layaway_id
  ) values (
    v_sale_id, v_license_id, v_local_sale_id, v_device_id, v_staff_user_id,
    coalesce(v_context->>'device_role', 'staff'), v_actor_key, v_actor_name,
    'cloud', 'cloud_committed', 'payment_recorded', 'closed', 'fulfilled',
    'layaway_completed', 'paid', v_cloud_folio,
    private.layaway_request_text_v1(v_sale_payload, array['local_folio','localFolio','folio']),
    v_cloud_folio, v_pos_folio, v_folio_sequence, v_folio_sequence,
    v_layaway.customer_id, v_layaway.customer_name, v_layaway.customer_phone,
    round(v_subtotal, 2), round(v_discount_total, 2), 0, v_total, v_total, 0, 0, v_layaway.currency,
    v_sold_at, v_created_at, now(), now(), null, null, null,
    'not_required', 'not_applied', 'not_applied',
    v_sale_payload,
    coalesce(v_sale_payload->'metadata', '{}'::jsonb) || jsonb_build_object(
      'phase', 'cloud_layaways_server_contract_r1',
      'layaway_id', v_layaway_id,
      'source_mode', 'cloud_committed',
      'no_cloud_cash_effects', true,
      'payment_verified_from_layaway_payments', true
    ),
    p_idempotency_key, 1, v_layaway_id
  ) returning * into v_sale;

  for v_item in select value from jsonb_array_elements(v_server_items) loop
    v_item_index := v_item_index + 1;
    v_item_id := v_sale.id || ':item:' || v_item_index::text;
    v_quantity := private.layaway_request_numeric_v1(v_item, array['quantity','qty']);
    v_unit_price := private.layaway_request_numeric_v1(v_item, array['unit_price','unitPrice','price']);
    v_line_subtotal := round(v_quantity * v_unit_price, 2);
    v_discount := greatest(coalesce(private.layaway_request_numeric_v1(v_item, array['discount_amount','discountAmount'], 0), 0), 0);
    v_tax := greatest(coalesce(private.layaway_request_numeric_v1(v_item, array['tax_amount','taxAmount'], 0), 0), 0);
    v_line_total := round(v_line_subtotal - v_discount, 2);
    v_unit_cost := coalesce(
      (select r.unit_cost from public.pos_layaway_inventory_reservations r
        where r.license_id = v_license_id and r.layaway_id = v_layaway_id and r.item_index = v_item_index
        limit 1),
      null
    );
    if v_unit_cost is null then
      select greatest(coalesce(
        case when private.layaway_request_text_v1(v_item, array['batch_id','batchId']) is not null
          then b.cost else p.cost end,
        0
      ), 0)
        into v_unit_cost
        from public.pos_products p
        left join public.pos_product_batches b
          on b.license_id = p.license_id
         and b.product_id = p.id
         and b.id = private.layaway_request_text_v1(v_item, array['batch_id','batchId'])
         and b.deleted_at is null
       where p.license_id = v_license_id
         and p.id = private.layaway_request_text_v1(v_item, array['product_id','productId','parentId'])
         and p.deleted_at is null;
      if not found then
        raise exception 'LAYAWAY_PRODUCT_NOT_SYNCED:%', private.layaway_request_text_v1(v_item, array['product_id','productId','parentId']) using errcode = 'P0001';
      end if;
      if private.layaway_request_text_v1(v_item, array['batch_id','batchId']) is not null
         and not exists (
           select 1
             from public.pos_product_batches b
            where b.license_id = v_license_id
              and b.product_id = private.layaway_request_text_v1(v_item, array['product_id','productId','parentId'])
              and b.id = private.layaway_request_text_v1(v_item, array['batch_id','batchId'])
              and b.deleted_at is null
         ) then
        raise exception 'LAYAWAY_RESERVATION_SOURCE_MISSING:%', private.layaway_request_text_v1(v_item, array['batch_id','batchId']) using errcode = 'P0001';
      end if;
    end if;
    if v_unit_cost is null then
      raise exception 'LAYAWAY_PRODUCT_NOT_SYNCED:%', private.layaway_request_text_v1(v_item, array['product_id','productId','parentId']) using errcode = 'P0001';
    end if;
    insert into public.pos_sale_items (
      id, license_id, sale_id, product_id, product_name, product_sku, barcode,
      category_id, category_name, quantity, unit_price, unit_cost, discount_amount,
      tax_amount, line_total, batch_id, batch_sku, batch_expiry_date, rubro,
      inventory_effect_status, stock_source, metadata, server_version
    ) values (
      v_item_id, v_license_id, v_sale.id,
      private.layaway_request_text_v1(v_item, array['product_id','productId','parentId']),
      coalesce(private.layaway_request_text_v1(v_item, array['product_name','productName','name']), 'Producto'),
      private.layaway_request_text_v1(v_item, array['product_sku','productSku','sku']),
      private.layaway_request_text_v1(v_item, array['barcode','barCode']),
      private.layaway_request_text_v1(v_item, array['category_id','categoryId']),
      private.layaway_request_text_v1(v_item, array['category_name','categoryName','rubro','category']),
      v_quantity, v_unit_price, greatest(v_unit_cost, 0), v_discount, v_tax, v_line_total,
      private.layaway_request_text_v1(v_item, array['batch_id','batchId']),
      private.layaway_request_text_v1(v_item, array['batch_sku','batchSku']),
      nullif(private.layaway_request_text_v1(v_item, array['batch_expiry_date','batchExpiryDate','expiryDate']), '')::date,
      private.layaway_request_text_v1(v_item, array['rubro','category','categoryName']),
      'not_applied', case when private.layaway_request_text_v1(v_item, array['batch_id','batchId']) is null then 'product' else 'batch' end,
      coalesce(v_item->'metadata', '{}'::jsonb) || jsonb_build_object(
        'phase', 'cloud_layaways_server_contract_r1',
        'layaway_id', v_layaway_id,
        'snapshot_only', true
      ),
      1
    );
  end loop;

  v_payment_id := v_sale.id || ':payment:completion';
  insert into public.pos_sale_payments (
    id, license_id, sale_id, method, amount, received_amount, change_amount,
    reference, cash_session_id, cash_movement_id, customer_ledger_id, metadata, server_version
  ) values (
    v_payment_id, v_license_id, v_sale.id, 'layaway_completed', v_total, v_total, 0,
    null, null, null, null,
    jsonb_build_object('phase', 'cloud_layaways_server_contract_r1', 'layaway_id', v_layaway_id,
      'cashAlreadyRecorded', true, 'noAdditionalCashMovement', true), 1
  ) returning * into v_sale_payment;

  v_inventory_movements := private.consume_layaway_stock_v1(
    v_license_id, v_layaway_id, v_sale.id, v_device_id, v_staff_user_id,
    v_actor_key, v_actor_name, p_idempotency_key
  );
  update public.pos_sales
     set inventory_effect_status = case when jsonb_array_length(v_inventory_movements) > 0 then 'applied' else 'not_required' end,
         effects_status = case when jsonb_array_length(v_inventory_movements) > 0 then 'inventory_applied' else 'payment_recorded' end,
         updated_at = now(), server_version = server_version + 1
   where license_id = v_license_id and id = v_sale.id
   returning * into v_sale;
  update public.pos_layaways
     set status = 'completed', conversion_sale_id = v_sale.id, completed_at = now(),
         updated_at = now(), server_version = server_version + 1,
         last_idempotency_key = p_idempotency_key,
         metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
           'completedSaleId', v_sale.id, 'completedByActorKey', v_actor_key,
           'folio', v_pos_folio, 'inventory_effect_status', v_sale.inventory_effect_status
         )
   where license_id = v_license_id and id = v_layaway_id
   returning * into v_layaway;

  v_event := private.record_pos_sync_event(
    v_license_id, 'sale', v_sale.id, 'cloud_commit', v_device_id, v_staff_user_id,
    p_idempotency_key,
    jsonb_build_object('sale_id', v_sale.id, 'layaway_id', v_layaway_id,
      'folio', v_pos_folio, 'cash_effect_status', 'not_required',
      'inventory_effect_status', v_sale.inventory_effect_status),
    v_sale.server_version::integer
  );
  perform private.record_pos_sync_event(
    v_license_id, 'layaway', v_layaway_id, 'update', v_device_id, v_staff_user_id,
    p_idempotency_key,
    jsonb_build_object('status', 'completed', 'sale_id', v_sale.id, 'folio', v_pos_folio),
    v_layaway.server_version::integer
  );
  perform private.record_pos_sale_audit_event(
    v_license_id, v_sale.id, 'sale.layaway_completed', v_device_id, v_staff_user_id,
    v_actor_name,
    jsonb_build_object('sale_id', v_sale.id, 'layaway_id', v_layaway_id,
      'folio', v_pos_folio, 'paid_total', v_paid_total,
      'cash_effect_status', 'not_required', 'inventory_effect_status', v_sale.inventory_effect_status,
      'idempotency_key', p_idempotency_key)
  );

  select coalesce(jsonb_agg(private.pos_layaway_sale_item_financial_to_jsonb_v2(i) order by i.created_at, i.id), '[]'::jsonb)
    into v_sale_items from public.pos_sale_items i where i.license_id = v_license_id and i.sale_id = v_sale.id;
  select coalesce(jsonb_agg(private.pos_layaway_sale_payment_financial_to_jsonb_v2(p) order by p.created_at, p.id), '[]'::jsonb)
    into v_sale_payments from public.pos_sale_payments p where p.license_id = v_license_id and p.sale_id = v_sale.id;
  select coalesce(jsonb_agg(private.pos_layaway_payment_financial_to_jsonb_v2(p) order by p.created_at, p.id), '[]'::jsonb)
    into v_layaway_payments from public.pos_layaway_payments p where p.license_id = v_license_id and p.layaway_id = v_layaway_id;
  select coalesce(jsonb_agg(private.pos_layaway_cash_movement_financial_to_jsonb_v2(m) order by m.created_at, m.id), '[]'::jsonb)
    into v_cash_movements from public.pos_cash_movements m
   where m.license_id = v_license_id and m.reference_type = 'layaway' and m.reference_id = v_layaway_id;
  select coalesce(max(change_seq), 0) into v_latest_change_seq
    from public.pos_sync_events where license_id = v_license_id;

  return jsonb_build_object(
    'success', true,
    'mode', 'cloud_layaway_completion',
    'layaway', private.pos_layaway_financial_to_jsonb_v2(v_layaway),
    'sale', private.pos_layaway_sale_financial_to_jsonb_v2(v_sale),
    'items', v_sale_items,
    'payments', v_sale_payments,
    'layaway_payments', v_layaway_payments,
    'cash_movements', v_cash_movements,
    'cash_movement', null,
    'cash_session', null,
    'inventory_movements', private.financial_inventory_movements_allowlist_v2(v_inventory_movements),
    'folio', v_pos_folio,
    'event', private.pos_layaway_event_financial_to_jsonb_v2(v_event),
    'server_version', v_sale.server_version,
    'change_seq', v_event.change_seq,
    'latest_change_seq', v_latest_change_seq,
    'idempotency_key', p_idempotency_key
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.execute_layaway_create_financial_v1(p_context jsonb, p_request jsonb, p_idempotency_key text, p_request_hash text, p_cash_station_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_license_id uuid := (p_context->>'license_id')::uuid;
  v_device_id uuid := nullif(p_context->>'device_id', '')::uuid;
  v_staff_user_id uuid := nullif(p_context->>'staff_user_id', '')::uuid;
  v_actor_key text := private.resolve_cash_actor_key(p_context);
  v_actor_name text := private.resolve_cash_actor_name(p_context);
  v_layaway_payload jsonb;
  v_initial_payment jsonb;
  v_items jsonb;
  v_normalized jsonb;
  v_layaway_id text;
  v_customer_id text;
  v_customer_name text;
  v_customer_phone text;
  v_currency text;
  v_deadline timestamptz;
  v_total numeric;
  v_payment_amount numeric := 0;
  v_payment_id text;
  v_payment_method text;
  v_cash_session_id text;
  v_layaway public.pos_layaways;
  v_session public.pos_cash_sessions;
  v_payment public.pos_layaway_payments;
  v_cash_movement public.pos_cash_movements;
  v_reservations jsonb := '[]'::jsonb;
  v_cash_movements jsonb := '[]'::jsonb;
  v_payments jsonb := '[]'::jsonb;
  v_event public.pos_sync_events;
  v_latest_change_seq bigint;
begin
  perform private.assert_cloud_layaways_enabled(p_context);
  perform private.assert_pos_permission(p_context, 'pos');

  v_layaway_payload := private.layaway_record_v1(p_request);
  if jsonb_typeof(v_layaway_payload) <> 'object' then
    raise exception 'LAYAWAY_PAYLOAD_INVALID' using errcode = 'P0001';
  end if;
  v_layaway_id := private.layaway_request_text_v1(v_layaway_payload, array['id','layaway_id','layawayId']);
  if v_layaway_id is null then
    raise exception 'LAYAWAY_ID_REQUIRED' using errcode = 'P0001';
  end if;
  v_total := private.layaway_request_numeric_v1(v_layaway_payload, array['total_amount','totalAmount','total']);
  v_normalized := private.normalize_layaway_items_v1(
    coalesce(v_layaway_payload->'items', '[]'::jsonb), v_total
  );
  select coalesce(
    jsonb_agg(
      value || jsonb_build_object(
        'id', coalesce(nullif(btrim(value->>'id'), ''), v_layaway_id || ':item:' || ordinality::text)
      ) order by ordinality
    ),
    '[]'::jsonb
  )
    into v_items
    from jsonb_array_elements(v_normalized->'items') with ordinality;
  if exists (
    select 1
      from jsonb_array_elements(v_items) as item
     where private.layaway_request_numeric_v1(item.value, array['discount_amount','discountAmount'], 0) > 0
  ) then
    perform private.assert_pos_permission(p_context, 'discounts');
  end if;
  v_currency := upper(coalesce(private.layaway_request_text_v1(v_layaway_payload, array['currency']), 'MXN'));
  if v_currency !~ '^[A-Z]{3}$' then
    raise exception 'LAYAWAY_CURRENCY_INVALID' using errcode = 'P0001';
  end if;

  begin
    if private.layaway_request_text_v1(v_layaway_payload, array['deadline','due_date','dueDate']) ~ '^\d{4}-\d{2}-\d{2}$' then
      v_deadline := (private.layaway_request_text_v1(v_layaway_payload, array['deadline','due_date','dueDate']) || 'T00:00:00+00')::timestamptz;
    else
      v_deadline := private.layaway_request_text_v1(v_layaway_payload, array['deadline','due_date','dueDate'])::timestamptz;
    end if;
  exception when invalid_text_representation or datetime_field_overflow then
    raise exception 'LAYAWAY_DEADLINE_INVALID' using errcode = 'P0001';
  end;
  if v_deadline is null then
    raise exception 'LAYAWAY_DEADLINE_REQUIRED' using errcode = 'P0001';
  end if;

  select * into v_layaway
    from public.pos_layaways l
   where l.license_id = v_license_id and l.id = v_layaway_id
   for update;
  if v_layaway.id is not null then
    raise exception 'LAYAWAY_ALREADY_EXISTS' using errcode = 'P0001';
  end if;

  v_initial_payment := private.layaway_payment_payload_v1(p_request);
  v_payment_amount := coalesce(private.layaway_request_numeric_v1(v_initial_payment, array['amount','total'], 0), 0);
  if v_payment_amount < 0 then
    raise exception 'LAYAWAY_PAYMENT_AMOUNT_INVALID' using errcode = 'P0001';
  end if;
  if v_payment_amount > v_total + 0.005 then
    raise exception 'LAYAWAY_PAYMENT_EXCEEDS_TOTAL' using errcode = 'P0001';
  end if;
  v_payment_method := lower(coalesce(private.layaway_request_text_v1(v_initial_payment, array['method','payment_method','paymentMethod']), 'cash'));
  if v_payment_method = 'efectivo' then v_payment_method := 'cash'; end if;
  if v_payment_amount > 0 and v_payment_method <> 'cash' then
    raise exception 'LAYAWAY_PAYMENT_METHOD_NOT_ALLOWED' using errcode = 'P0001';
  end if;
  v_cash_session_id := private.layaway_request_cash_session_id_v1(p_request);
  if v_payment_amount > 0 then
    v_session := private.layaway_cash_session_v1(
      v_license_id, v_device_id, v_actor_key, v_cash_session_id, p_cash_station_id
    );
  end if;

  v_customer_id := private.layaway_request_text_v1(v_layaway_payload, array['customer_id','customerId']);
  v_customer_name := private.layaway_request_text_v1(v_layaway_payload, array['customer_name','customerName']);
  v_customer_phone := private.layaway_request_text_v1(v_layaway_payload, array['customer_phone','customerPhone']);

  insert into public.pos_layaways (
    id, license_id, customer_id, customer_name, customer_phone, total_amount,
    paid_amount, balance_due, currency, deadline, status, items, cash_station_id,
    created_by_device_id, created_by_staff_user_id, actor_key, actor_name,
    created_at, updated_at, server_version, last_idempotency_key, metadata
  ) values (
    v_layaway_id, v_license_id, v_customer_id, v_customer_name, v_customer_phone, round(v_total, 2),
    0, round(v_total, 2), v_currency, v_deadline, 'active', v_items, p_cash_station_id,
    v_device_id, v_staff_user_id, v_actor_key, v_actor_name,
    now(), now(), 1, p_idempotency_key,
    coalesce(v_layaway_payload->'metadata', '{}'::jsonb) || jsonb_build_object(
      'phase', 'cloud_layaways_server_contract_r1',
      'source_mode', 'cloud_committed',
      'cash_station_id', p_cash_station_id
    )
  ) returning * into v_layaway;

  v_reservations := private.reserve_layaway_stock_v1(
    v_license_id, v_layaway_id, v_items, v_device_id, v_staff_user_id,
    v_actor_key, v_actor_name, p_idempotency_key
  );

  if v_payment_amount > 0 then
    v_payment_id := coalesce(
      private.layaway_request_text_v1(v_initial_payment, array['id','payment_id','paymentId']),
      v_layaway_id || ':payment:initial'
    );
    insert into public.pos_cash_movements (
      id, license_id, cash_session_id, device_id, staff_user_id, actor_key,
      type, amount, concept, source, reference_type, reference_id,
      created_by_device_id, created_by_staff_user_id, actor_name,
      cash_station_id, performed_by_actor_key, idempotency_key, metadata
    ) values (
      'mov_' || replace(gen_random_uuid()::text, '-', ''), v_license_id, v_session.id,
      v_session.device_id, v_session.staff_user_id, v_session.actor_key,
      'entrada', round(v_payment_amount, 2), 'Abono inicial Apartado ' || v_layaway_id,
      'layaway_payment', 'layaway', v_layaway_id,
      v_device_id, v_staff_user_id, v_actor_name,
      v_session.cash_station_id, v_actor_key, p_idempotency_key || ':cash',
      jsonb_build_object(
        'phase', 'cloud_layaways_server_contract_r1',
        'source', 'layaway_payment',
        'layaway_id', v_layaway_id,
        'payment_id', v_payment_id,
        'payment_type', coalesce(private.layaway_request_text_v1(v_initial_payment, array['payment_type','paymentType','type']), 'initial_deposit'),
        'idempotency_key', p_idempotency_key
      )
    ) returning * into v_cash_movement;

    insert into public.pos_layaway_payments (
      id, license_id, layaway_id, payment_method, amount, status,
      cash_session_id, cash_station_id, cash_movement_id, reference,
      request_hash, idempotency_key, created_by_device_id, created_by_staff_user_id,
      actor_key, actor_name, metadata
    ) values (
      v_payment_id, v_license_id, v_layaway_id, 'cash', round(v_payment_amount, 2), 'confirmed',
      v_session.id, v_session.cash_station_id, v_cash_movement.id,
      private.layaway_request_text_v1(v_initial_payment, array['reference','ref']),
      p_request_hash, p_idempotency_key, v_device_id, v_staff_user_id,
      v_actor_key, v_actor_name,
      jsonb_build_object('payment_type', coalesce(private.layaway_request_text_v1(v_initial_payment, array['payment_type','paymentType','type']), 'initial_deposit'))
    ) returning * into v_payment;

    v_session := private.recalculate_pos_cash_session_totals(v_license_id, v_session.id, true);
    update public.pos_layaways
       set paid_amount = round(v_payment_amount, 2),
           balance_due = greatest(round(total_amount - v_payment_amount, 2), 0),
           status = case when v_payment_amount >= total_amount - 0.005 then 'ready' else 'active' end,
           updated_at = now(), server_version = server_version + 1,
           last_idempotency_key = p_idempotency_key
     where license_id = v_license_id and id = v_layaway_id
     returning * into v_layaway;
  end if;

  v_event := private.record_pos_sync_event(
    v_license_id, 'layaway', v_layaway_id, 'create', v_device_id, v_staff_user_id,
    p_idempotency_key,
    jsonb_build_object('status', v_layaway.status, 'total_amount', v_layaway.total_amount,
      'paid_amount', v_layaway.paid_amount, 'cash_station_id', p_cash_station_id,
      'payment_id', case when v_payment.id is null then null else v_payment.id end),
    v_layaway.server_version::integer
  );
  if v_payment.id is not null then
    perform private.record_pos_sync_event(
      v_license_id, 'layaway_payment', v_payment.id, 'create', v_device_id, v_staff_user_id,
      p_idempotency_key, jsonb_build_object('layaway_id', v_layaway_id, 'cash_movement_id', v_payment.cash_movement_id),
      v_payment.server_version::integer
    );
    perform private.record_pos_sync_event(
      v_license_id, 'cash_movement', v_cash_movement.id, 'create', v_device_id, v_staff_user_id,
      p_idempotency_key, jsonb_build_object('layaway_id', v_layaway_id, 'payment_id', v_payment.id),
      v_cash_movement.server_version
    );
  end if;

  select coalesce(jsonb_agg(private.pos_layaway_payment_financial_to_jsonb_v2(p) order by p.created_at, p.id), '[]'::jsonb)
    into v_payments
    from public.pos_layaway_payments p
   where p.license_id = v_license_id and p.layaway_id = v_layaway_id;
  select coalesce(jsonb_agg(private.pos_layaway_cash_movement_financial_to_jsonb_v2(m) order by m.created_at, m.id), '[]'::jsonb)
    into v_cash_movements
    from public.pos_cash_movements m
   where m.license_id = v_license_id and m.reference_type = 'layaway' and m.reference_id = v_layaway_id;
  select coalesce(max(change_seq), 0) into v_latest_change_seq
    from public.pos_sync_events where license_id = v_license_id;

  return jsonb_build_object(
    'success', true,
    'mode', 'cloud_layaway',
    'layaway', private.pos_layaway_financial_to_jsonb_v2(v_layaway),
    'payments', v_payments,
    'inventory_reservations', private.financial_layaway_reservations_allowlist_v2(v_reservations),
    'cash_movements', v_cash_movements,
    'cash_movement', case when v_cash_movement.id is null then null else private.pos_layaway_cash_movement_financial_to_jsonb_v2(v_cash_movement) end,
    'cash_session', null,
    'folio', null,
    'sale', null,
    'event', private.pos_layaway_event_financial_to_jsonb_v2(v_event),
    'change_seq', v_event.change_seq,
    'latest_change_seq', v_latest_change_seq,
    'idempotency_key', p_idempotency_key
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.execute_layaway_payment_financial_v1(p_context jsonb, p_request jsonb, p_idempotency_key text, p_request_hash text, p_cash_station_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_license_id uuid := (p_context->>'license_id')::uuid;
  v_device_id uuid := nullif(p_context->>'device_id', '')::uuid;
  v_staff_user_id uuid := nullif(p_context->>'staff_user_id', '')::uuid;
  v_actor_key text := private.resolve_cash_actor_key(p_context);
  v_actor_name text := private.resolve_cash_actor_name(p_context);
  v_layaway_id text := private.layaway_request_id_v1(p_request);
  v_payment_payload jsonb := coalesce(p_request->'payment', '{}'::jsonb);
  v_payment_id text;
  v_payment_amount numeric;
  v_payment_method text;
  v_cash_session_id text := private.layaway_request_cash_session_id_v1(p_request);
  v_layaway public.pos_layaways;
  v_existing_payment public.pos_layaway_payments;
  v_payment public.pos_layaway_payments;
  v_session public.pos_cash_sessions;
  v_cash_movement public.pos_cash_movements;
  v_event public.pos_sync_events;
  v_payments jsonb := '[]'::jsonb;
  v_reservations jsonb := '[]'::jsonb;
  v_cash_movements jsonb := '[]'::jsonb;
  v_latest_change_seq bigint;
begin
  perform private.assert_cloud_layaways_enabled(p_context);
  perform private.assert_pos_permission(p_context, 'pos');
  if v_layaway_id is null then
    raise exception 'LAYAWAY_ID_REQUIRED' using errcode = 'P0001';
  end if;
  if jsonb_typeof(v_payment_payload) <> 'object' then
    raise exception 'LAYAWAY_PAYMENT_INVALID' using errcode = 'P0001';
  end if;

  v_payment_id := private.layaway_request_text_v1(v_payment_payload, array['id','payment_id','paymentId']);
  if v_payment_id is null then
    raise exception 'LAYAWAY_PAYMENT_ID_REQUIRED' using errcode = 'P0001';
  end if;
  v_payment_amount := private.layaway_request_numeric_v1(v_payment_payload, array['amount','total']);
  v_payment_method := lower(coalesce(private.layaway_request_text_v1(v_payment_payload, array['method','payment_method','paymentMethod']), 'cash'));
  if v_payment_method = 'efectivo' then v_payment_method := 'cash'; end if;
  if v_payment_amount is null or v_payment_amount <= 0 then
    raise exception 'LAYAWAY_PAYMENT_AMOUNT_INVALID' using errcode = 'P0001';
  end if;
  if v_payment_method <> 'cash' then
    raise exception 'LAYAWAY_PAYMENT_METHOD_NOT_ALLOWED' using errcode = 'P0001';
  end if;

  select * into v_layaway
    from public.pos_layaways l
   where l.license_id = v_license_id and l.id = v_layaway_id
   for update;
  if v_layaway.id is null then
    raise exception 'LAYAWAY_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_layaway.status = 'cancelled' then
    raise exception 'LAYAWAY_ALREADY_CANCELLED' using errcode = 'P0001';
  end if;
  if v_layaway.status = 'completed' then
    raise exception 'LAYAWAY_ALREADY_COMPLETED' using errcode = 'P0001';
  end if;

  select * into v_existing_payment
    from public.pos_layaway_payments p
   where p.license_id = v_license_id and p.layaway_id = v_layaway_id and p.id = v_payment_id
   for update;
  if v_existing_payment.id is not null then
    if abs(v_existing_payment.amount - v_payment_amount) > 0.005
       or v_existing_payment.payment_method <> v_payment_method then
      raise exception 'LAYAWAY_PAYMENT_ID_CONFLICT' using errcode = 'P0001';
    end if;
    raise exception 'LAYAWAY_PAYMENT_ALREADY_EXISTS' using errcode = 'P0001';
  end if;

  if v_payment_amount > v_layaway.balance_due + 0.005 then
    raise exception 'LAYAWAY_PAYMENT_EXCEEDS_BALANCE' using errcode = 'P0001';
  end if;
  v_session := private.layaway_cash_session_v1(
    v_license_id, v_device_id, v_actor_key, v_cash_session_id, p_cash_station_id
  );

  insert into public.pos_cash_movements (
    id, license_id, cash_session_id, device_id, staff_user_id, actor_key,
    type, amount, concept, source, reference_type, reference_id,
    created_by_device_id, created_by_staff_user_id, actor_name,
    cash_station_id, performed_by_actor_key, idempotency_key, metadata
  ) values (
    'mov_' || replace(gen_random_uuid()::text, '-', ''), v_license_id, v_session.id,
    v_session.device_id, v_session.staff_user_id, v_session.actor_key,
    'entrada', round(v_payment_amount, 2), 'Abono Apartado ' || v_layaway_id,
    'layaway_payment', 'layaway', v_layaway_id,
    v_device_id, v_staff_user_id, v_actor_name,
    v_session.cash_station_id, v_actor_key, p_idempotency_key || ':cash',
    jsonb_build_object(
      'phase', 'cloud_layaways_server_contract_r1',
      'source', 'layaway_payment',
      'layaway_id', v_layaway_id,
      'payment_id', v_payment_id,
      'payment_type', coalesce(private.layaway_request_text_v1(v_payment_payload, array['payment_type','paymentType','type']), 'installment'),
      'idempotency_key', p_idempotency_key
    )
  ) returning * into v_cash_movement;

  insert into public.pos_layaway_payments (
    id, license_id, layaway_id, payment_method, amount, status,
    cash_session_id, cash_station_id, cash_movement_id, reference,
    request_hash, idempotency_key, created_by_device_id, created_by_staff_user_id,
    actor_key, actor_name, metadata
  ) values (
    v_payment_id, v_license_id, v_layaway_id, 'cash', round(v_payment_amount, 2), 'confirmed',
    v_session.id, v_session.cash_station_id, v_cash_movement.id,
    private.layaway_request_text_v1(v_payment_payload, array['reference','ref']),
    p_request_hash, p_idempotency_key, v_device_id, v_staff_user_id,
    v_actor_key, v_actor_name,
    jsonb_build_object('payment_type', coalesce(private.layaway_request_text_v1(v_payment_payload, array['payment_type','paymentType','type']), 'installment'))
  ) returning * into v_payment;

  v_session := private.recalculate_pos_cash_session_totals(v_license_id, v_session.id, true);
  update public.pos_layaways
     set paid_amount = round(paid_amount + v_payment_amount, 2),
         balance_due = greatest(round(total_amount - (paid_amount + v_payment_amount), 2), 0),
         status = case when paid_amount + v_payment_amount >= total_amount - 0.005 then 'ready' else status end,
         updated_at = now(), server_version = server_version + 1,
         last_idempotency_key = p_idempotency_key
   where license_id = v_license_id and id = v_layaway_id
   returning * into v_layaway;

  v_event := private.record_pos_sync_event(
    v_license_id, 'layaway', v_layaway_id, 'update', v_device_id, v_staff_user_id,
    p_idempotency_key,
    jsonb_build_object('reason', 'layaway_payment_confirmed', 'payment_id', v_payment.id,
      'cash_movement_id', v_cash_movement.id, 'paid_amount', v_layaway.paid_amount,
      'balance_due', v_layaway.balance_due),
    v_layaway.server_version::integer
  );
  perform private.record_pos_sync_event(
    v_license_id, 'layaway_payment', v_payment.id, 'create', v_device_id, v_staff_user_id,
    p_idempotency_key, jsonb_build_object('layaway_id', v_layaway_id, 'cash_movement_id', v_cash_movement.id),
    v_payment.server_version::integer
  );
  perform private.record_pos_sync_event(
    v_license_id, 'cash_movement', v_cash_movement.id, 'create', v_device_id, v_staff_user_id,
    p_idempotency_key, jsonb_build_object('layaway_id', v_layaway_id, 'payment_id', v_payment.id),
    v_cash_movement.server_version
  );

  select coalesce(jsonb_agg(private.pos_layaway_payment_financial_to_jsonb_v2(p) order by p.created_at, p.id), '[]'::jsonb)
    into v_payments
    from public.pos_layaway_payments p
   where p.license_id = v_license_id and p.layaway_id = v_layaway_id;
  select coalesce(jsonb_agg(private.pos_layaway_reservation_financial_to_jsonb_v2(r) order by r.item_index), '[]'::jsonb)
    into v_reservations
    from public.pos_layaway_inventory_reservations r
   where r.license_id = v_license_id and r.layaway_id = v_layaway_id;
  select coalesce(jsonb_agg(private.pos_layaway_cash_movement_financial_to_jsonb_v2(m) order by m.created_at, m.id), '[]'::jsonb)
    into v_cash_movements
    from public.pos_cash_movements m
   where m.license_id = v_license_id and m.reference_type = 'layaway' and m.reference_id = v_layaway_id;
  select coalesce(max(change_seq), 0) into v_latest_change_seq
    from public.pos_sync_events where license_id = v_license_id;

  return jsonb_build_object(
    'success', true,
    'mode', 'cloud_layaway',
    'layaway', private.pos_layaway_financial_to_jsonb_v2(v_layaway),
    'payment', private.pos_layaway_payment_financial_to_jsonb_v2(v_payment),
    'payments', v_payments,
    'inventory_reservations', private.financial_layaway_reservations_allowlist_v2(v_reservations),
    'cash_movements', v_cash_movements,
    'cash_movement', private.pos_layaway_cash_movement_financial_to_jsonb_v2(v_cash_movement),
    'cash_session', null,
    'folio', null,
    'sale', null,
    'event', private.pos_layaway_event_financial_to_jsonb_v2(v_event),
    'change_seq', v_event.change_seq,
    'latest_change_seq', v_latest_change_seq,
    'idempotency_key', p_idempotency_key
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.execute_split_sale_financial_v1(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text, p_split jsonb, p_internal_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_device_id uuid;
  v_staff_user_id uuid;
  v_parent_order_id text;
  v_split_group_id text;
  v_cash_session_id text;
  v_parent_order_version text;
  v_parent_order_version_at timestamptz;
  v_split_intent text := coalesce(
    private.financial_text_v1(private.financial_first_nonblank_scalar_v1(
      coalesce(p_split, '{}'::jsonb), array['split_intent','splitIntent']
    )),
    'by_items'
  );
  v_split_payers jsonb := coalesce(p_split->'split_payers', p_split->'splitPayers', '[]'::jsonb);
  v_split_payer jsonb;
  v_payment jsonb;
  v_split_payer_count integer := 0;
  v_split_payer_index integer := 0;
  v_equal_base_cents integer := 0;
  v_equal_remainder_cents integer := 0;
  v_credit_payer_count integer := 0;
  v_split_payer_total numeric := 0;
  v_payer_id text;
  v_payer_method text;
  v_payer_customer_id text;
  v_credit_customer_id text;
  v_customer_id_snake text;
  v_customer_id_camel text;
  v_child_customer_id text;
  v_child_customer_alias_id text;
  v_sale_customer_id text;
  v_sale_customer_alias_id text;
  v_payer_initial_method text;
  v_payer_amount numeric;
  v_payer_initial_amount numeric;
  v_expected_payment_method text;
  v_expected_payment_amount numeric;
  v_payment_payer_id text;
  v_payment_method_normalized text;
  v_payment_amount numeric;
  v_payer_payment_total numeric;
  v_payer_ids text[] := array[]::text[];
  v_child_count integer;
  v_child_index integer := 0;
  v_child jsonb;
  v_child_sale jsonb;
  v_child_response jsonb;
  v_child_sale_id text;
  v_child_label text;
  v_child_key text;
  v_payment_method text;
  v_is_credit boolean;
  v_inventory boolean;
  v_sales jsonb := '[]'::jsonb;
  v_items jsonb := '[]'::jsonb;
  v_payments jsonb := '[]'::jsonb;
  v_children jsonb := '[]'::jsonb;
  v_tickets jsonb := '[]'::jsonb;
  v_total numeric := 0;
  v_payment_summary jsonb;
  v_close_response jsonb;
  v_order public.pos_restaurant_orders;
  v_labels text[] := array[]::text[];
  v_sale_ids text[] := array[]::text[];
  v_latest_change_seq bigint;
  v_primary_sale_id text;
  v_primary_sale_folio text;
begin
  if jsonb_typeof(coalesce(p_split, '{}'::jsonb)) <> 'object' then
    raise exception 'FINANCIAL_SPLIT_CONTRACT_INVALID' using errcode = 'P0001';
  end if;

  v_context := private.validate_pos_sync_context(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token
  );
  perform private.assert_cloud_sales_sync_base_enabled(v_context);
  perform private.assert_pos_permission(v_context, 'pos');

  v_parent_order_id := nullif(btrim(coalesce(p_split->>'parent_order_id', p_split->>'parentOrderId', '')), '');
  v_split_group_id := nullif(btrim(coalesce(p_split->>'split_group_id', p_split->>'splitGroupId', '')), '');
  v_cash_session_id := nullif(btrim(coalesce(p_split->>'cash_session_id', p_split->>'cashSessionId', '')), '');
  v_parent_order_version := nullif(btrim(coalesce(p_split->>'parent_order_version', p_split->>'parentOrderVersion', '')), '');
  if v_split_intent in ('equal_payment', 'custom_payment')
     and (v_parent_order_version is null
       or v_parent_order_version !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,6})?([zZ]|[+-][0-9]{2}:[0-9]{2})$') then
    raise exception 'RESTAURANT_ORDER_VERSION_CONFLICT' using errcode = 'P0001';
  end if;
  if v_parent_order_version is not null then
    begin
      v_parent_order_version_at := v_parent_order_version::timestamptz;
    exception
      when invalid_text_representation or datetime_field_overflow or invalid_datetime_format then
        raise exception 'RESTAURANT_ORDER_VERSION_CONFLICT' using errcode = 'P0001';
    end;
  end if;
  if v_parent_order_id is null then
    raise exception 'RESTAURANT_PARENT_ORDER_REQUIRED' using errcode = 'P0001';
  end if;
  if v_split_group_id is null then
    raise exception 'SPLIT_GROUP_ID_REQUIRED' using errcode = 'P0001';
  end if;
  if v_cash_session_id is null then
    raise exception 'FINANCIAL_CASH_SESSION_ID_REQUIRED' using errcode = 'P0001';
  end if;

  v_license_id := (v_context->>'license_id')::uuid;
  v_device_id := (v_context->>'device_id')::uuid;
  v_staff_user_id := nullif(v_context->>'staff_user_id', '')::uuid;

  -- Shared settlement lock is also acquired by the normal cashier dispatcher.
  v_order := private.lock_restaurant_order_settlement_v1(v_license_id, v_parent_order_id);

  if v_order.id is null then
    raise exception 'RESTAURANT_ORDER_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_order.deleted_at is not null then
    raise exception 'RESTAURANT_ORDER_NOT_ACTIVE' using errcode = 'P0001';
  end if;

  perform private.assert_cash_session_station(
    v_license_id,
    v_device_id,
    v_cash_session_id
  );

  if v_order.id is null then
    raise exception 'RESTAURANT_ORDER_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_parent_order_version is not null
     and v_order.updated_at is distinct from v_parent_order_version_at then
    raise exception 'RESTAURANT_ORDER_VERSION_CONFLICT' using errcode = 'P0001';
  end if;
  if v_order.status = 'cancelled' or v_order.cancelled_at is not null then
    raise exception 'RESTAURANT_ORDER_ALREADY_CANCELLED' using errcode = 'P0001';
  end if;
  if v_order.archived_at is not null or v_order.checkout_closed_at is not null then
    raise exception 'RESTAURANT_ORDER_NOT_ACTIVE' using errcode = 'P0001';
  end if;
  if lower(coalesce(v_order.payment_status, 'unpaid')) = 'paid' then
    raise exception 'RESTAURANT_ORDER_ALREADY_PAID' using errcode = 'P0001';
  end if;

  if jsonb_typeof(coalesce(p_split->'children', '[]'::jsonb)) <> 'array' then
    raise exception 'FINANCIAL_SPLIT_CONTRACT_INVALID' using errcode = 'P0001';
  end if;
  v_child_count := jsonb_array_length(p_split->'children');
  if v_split_intent not in ('by_items', 'equal_payment', 'custom_payment') then
    raise exception 'FINANCIAL_SPLIT_CONTRACT_INVALID' using errcode = 'P0001';
  end if;
  if (v_split_intent = 'by_items' and (v_child_count < 2 or v_child_count > 8))
     or (v_split_intent in ('equal_payment', 'custom_payment') and v_child_count <> 1) then
    raise exception 'FINANCIAL_SPLIT_CHILD_COUNT_INVALID' using errcode = 'P0001';
  end if;

  if v_split_intent in ('equal_payment', 'custom_payment') then
    if jsonb_typeof(v_split_payers) <> 'array' then
      raise exception 'FINANCIAL_SPLIT_PAYER_CONTRACT_INVALID' using errcode = 'P0001';
    end if;
    v_split_payer_count := jsonb_array_length(v_split_payers);
    if v_split_payer_count < 2 or v_split_payer_count > 8 then
      raise exception 'FINANCIAL_SPLIT_PAYER_COUNT_INVALID' using errcode = 'P0001';
    end if;
    if v_split_intent = 'equal_payment' then
      v_equal_base_cents := floor(round(coalesce(v_order.total, 0) * 100)::numeric / v_split_payer_count)::integer;
      v_equal_remainder_cents := mod(round(coalesce(v_order.total, 0) * 100)::integer, v_split_payer_count);
    end if;

    for v_split_payer in select value from jsonb_array_elements(v_split_payers)
    loop
      if jsonb_typeof(v_split_payer) <> 'object' then
        raise exception 'FINANCIAL_SPLIT_PAYER_INVALID' using errcode = 'P0001';
      end if;
      v_payer_id := nullif(btrim(coalesce(v_split_payer->>'payer_id', v_split_payer->>'payerId', v_split_payer->>'label', v_split_payer->>'id', '')), '');
      if v_payer_id is null or v_payer_id !~ '^T[1-8]$' or v_payer_id = any(v_payer_ids) then
        raise exception 'FINANCIAL_SPLIT_PAYER_INVALID' using errcode = 'P0001';
      end if;
      v_payer_ids := array_append(v_payer_ids, v_payer_id);

      v_payer_amount := private.pos_sale_jsonb_numeric(v_split_payer, array['amount','contribution_amount','contributionAmount'], null);
      v_payer_method := private.normalize_pos_sale_payment_method(coalesce(v_split_payer->>'payment_method', v_split_payer->>'paymentMethod', v_split_payer->>'method'));
      if v_payer_amount is null or v_payer_amount <= 0 or v_payer_amount <> round(v_payer_amount, 2)
         or v_payer_method is null or v_payer_method not in ('cash', 'card', 'transfer', 'credit') then
        raise exception 'FINANCIAL_SPLIT_PAYER_INVALID' using errcode = 'P0001';
      end if;
      v_split_payer_index := v_split_payer_index + 1;
      v_split_payer_total := v_split_payer_total + v_payer_amount;
      if v_split_intent = 'equal_payment'
         and v_payer_amount <> (v_equal_base_cents + case when v_split_payer_index <= v_equal_remainder_cents then 1 else 0 end)::numeric / 100 then
        raise exception 'FINANCIAL_SPLIT_EQUAL_DISTRIBUTION_INVALID' using errcode = 'P0001';
      end if;

      if v_payer_method = 'credit' then
        v_credit_payer_count := v_credit_payer_count + 1;
        v_payer_initial_amount := coalesce(private.pos_sale_jsonb_numeric(v_split_payer, array['initial_amount_paid','initialAmountPaid'], null), 0);
        v_payer_initial_method := private.normalize_pos_sale_payment_method(coalesce(v_split_payer->>'initial_payment_method', v_split_payer->>'initialPaymentMethod', 'cash'));
        v_customer_id_snake := nullif(btrim(v_split_payer->>'customer_id'), '');
        v_customer_id_camel := nullif(btrim(v_split_payer->>'customerId'), '');
        if v_customer_id_snake is not null
           and v_customer_id_camel is not null
           and v_customer_id_snake <> v_customer_id_camel then
          raise exception 'FINANCIAL_SPLIT_CREDIT_CUSTOMER_MISMATCH' using errcode = 'P0001';
        end if;
        v_payer_customer_id := coalesce(v_customer_id_snake, v_customer_id_camel);
        if v_credit_payer_count > 1
           or v_payer_customer_id is null
           or v_payer_initial_amount < 0
           or v_payer_initial_amount >= v_payer_amount
           or v_payer_initial_amount <> round(v_payer_initial_amount, 2)
           or v_payer_initial_method not in ('cash', 'card', 'transfer') then
          raise exception 'FINANCIAL_SPLIT_CREDIT_PAYER_INVALID' using errcode = 'P0001';
        end if;
        v_credit_customer_id := v_payer_customer_id;
        v_expected_payment_amount := v_payer_initial_amount;
        v_expected_payment_method := v_payer_initial_method;
      else
        if nullif(btrim(coalesce(v_split_payer->>'customer_id', v_split_payer->>'customerId', '')), '') is not null then
          raise exception 'FINANCIAL_SPLIT_PAYER_INVALID' using errcode = 'P0001';
        end if;
        v_expected_payment_amount := v_payer_amount;
        v_expected_payment_method := v_payer_method;
      end if;

      v_payer_payment_total := 0;
      for v_payment in
        select value from jsonb_array_elements(coalesce((p_split->'children'->0)->'payments', '[]'::jsonb))
      loop
        v_payment_payer_id := nullif(btrim(coalesce(
          v_payment->>'split_payer_id', v_payment->>'splitPayerId',
          v_payment->'metadata'->>'split_payer_id', v_payment->'metadata'->>'splitPayerId', ''
        )), '');
        if v_payment_payer_id = v_payer_id then
          v_payment_method_normalized := private.normalize_pos_sale_payment_method(coalesce(v_payment->>'method', v_payment->>'payment_method', v_payment->>'paymentMethod'));
          v_payment_amount := private.pos_sale_jsonb_numeric(v_payment, array['amount','total'], null);
          if jsonb_typeof(v_payment) <> 'object'
             or v_payment_method_normalized is distinct from v_expected_payment_method
             or v_payment_amount is null or v_payment_amount <= 0 or v_payment_amount <> round(v_payment_amount, 2) then
            raise exception 'FINANCIAL_SPLIT_PAYER_PAYMENT_INVALID' using errcode = 'P0001';
          end if;
          v_payer_payment_total := v_payer_payment_total + v_payment_amount;
        end if;
      end loop;
      if abs(v_payer_payment_total - v_expected_payment_amount) > 0.005 then
        raise exception 'FINANCIAL_SPLIT_PAYER_PAYMENT_MISMATCH' using errcode = 'P0001';
      end if;
    end loop;

    if v_credit_payer_count = 1 then
      v_child := coalesce(p_split->'children'->0, '{}'::jsonb);
      v_child_sale := coalesce(v_child->'sale', '{}'::jsonb);
      v_child_customer_id := nullif(btrim(v_child->>'customer_id'), '');
      v_child_customer_alias_id := nullif(btrim(v_child->>'customerId'), '');
      if v_child_customer_id is not null
         and v_child_customer_alias_id is not null
         and v_child_customer_id <> v_child_customer_alias_id then
        raise exception 'FINANCIAL_SPLIT_CREDIT_CUSTOMER_MISMATCH' using errcode = 'P0001';
      end if;
      v_child_customer_id := coalesce(v_child_customer_id, v_child_customer_alias_id);

      v_sale_customer_id := nullif(btrim(v_child_sale->>'customer_id'), '');
      v_sale_customer_alias_id := nullif(btrim(v_child_sale->>'customerId'), '');
      if v_sale_customer_id is not null
         and v_sale_customer_alias_id is not null
         and v_sale_customer_id <> v_sale_customer_alias_id then
        raise exception 'FINANCIAL_SPLIT_CREDIT_CUSTOMER_MISMATCH' using errcode = 'P0001';
      end if;
      v_sale_customer_id := coalesce(v_sale_customer_id, v_sale_customer_alias_id);

      if (v_child_customer_id is not null and v_child_customer_id <> v_credit_customer_id)
         or (v_sale_customer_id is not null and v_sale_customer_id <> v_credit_customer_id) then
        raise exception 'FINANCIAL_SPLIT_CREDIT_CUSTOMER_MISMATCH' using errcode = 'P0001';
      end if;
    end if;

    if abs(v_split_payer_total - coalesce(v_order.total, 0)) > 0.005 then
      raise exception 'FINANCIAL_SPLIT_PAYER_TOTAL_MISMATCH' using errcode = 'P0001';
    end if;

    for v_payment in
      select value from jsonb_array_elements(coalesce((p_split->'children'->0)->'payments', '[]'::jsonb))
    loop
      v_payment_payer_id := nullif(btrim(coalesce(
        v_payment->>'split_payer_id', v_payment->>'splitPayerId',
        v_payment->'metadata'->>'split_payer_id', v_payment->'metadata'->>'splitPayerId', ''
      )), '');
      if v_payment_payer_id is null or not (v_payment_payer_id = any(v_payer_ids)) then
        raise exception 'FINANCIAL_SPLIT_PAYER_PAYMENT_INVALID' using errcode = 'P0001';
      end if;
    end loop;
  end if;

  for v_child in
    select value
      from jsonb_array_elements(p_split->'children')
  loop
    v_child_index := v_child_index + 1;
    v_child_key := p_internal_idempotency_key || ':child:' || v_child_index::text;
    if jsonb_typeof(v_child) <> 'object' then
      raise exception 'FINANCIAL_SPLIT_CHILD_INVALID' using errcode = 'P0001';
    end if;

    v_child_label := nullif(btrim(coalesce(v_child->>'label', '')), '');
    v_child_sale := coalesce(v_child->'sale', '{}'::jsonb);
    if v_child_label is null or jsonb_typeof(v_child_sale) <> 'object' then
      raise exception 'FINANCIAL_SPLIT_CHILD_INVALID' using errcode = 'P0001';
    end if;
    if v_child_label = any(v_labels) then
      raise exception 'FINANCIAL_SPLIT_LABEL_DUPLICATE' using errcode = 'P0001';
    end if;
    v_labels := array_append(v_labels, v_child_label);

    v_child_sale_id := nullif(btrim(coalesce(v_child_sale->>'id', v_child_sale->>'cloud_sale_id', v_child_sale->>'cloudSaleId', '')), '');
    if v_child_sale_id is null then
      raise exception 'FINANCIAL_SPLIT_SALE_ID_REQUIRED' using errcode = 'P0001';
    end if;
    if v_child_sale_id = any(v_sale_ids) then
      raise exception 'FINANCIAL_SPLIT_SALE_ID_DUPLICATE' using errcode = 'P0001';
    end if;
    v_sale_ids := array_append(v_sale_ids, v_child_sale_id);

    v_payment_method := lower(coalesce(
      nullif(btrim(coalesce(v_child_sale->>'payment_method', v_child_sale->>'paymentMethod', '')), ''),
      'cash'
    ));
    v_is_credit := private.normalize_pos_sale_payment_method(v_payment_method) = 'credit'
      or private.financial_payment_method_v1('sale.credit', v_payment_method) = 'mixed_credit';
    if v_split_intent in ('equal_payment', 'custom_payment')
       and (v_credit_payer_count = 1) is distinct from v_is_credit then
      raise exception 'FINANCIAL_SPLIT_CREDIT_PAYER_INVALID' using errcode = 'P0001';
    end if;
    if v_split_intent in ('equal_payment', 'custom_payment') and v_credit_payer_count = 1 then
      v_child_sale := jsonb_set(v_child_sale, '{customer_id}', to_jsonb(v_credit_customer_id), true);
    end if;
    v_inventory := coalesce((v_child_sale->'metadata'->>'cloudInventoryEffects')::boolean, false);

    if v_is_credit then
      perform private.assert_cloud_sales_credit_enabled(v_context);
      v_child_response := public.pos_create_cloud_sale_credit_unlimited(
        p_license_key,
        p_device_fingerprint,
        p_security_token,
        p_staff_session_token,
        v_child_sale,
        coalesce(v_child->'items', '[]'::jsonb),
        coalesce(v_child->'payments', '[]'::jsonb),
        v_cash_session_id,
        case
          when v_split_intent in ('equal_payment', 'custom_payment') and v_credit_payer_count = 1
            then v_credit_customer_id
          else coalesce(
            nullif(btrim(v_child->>'customer_id'), ''),
            nullif(btrim(v_child_sale->>'customer_id'), ''),
            nullif(btrim(v_child_sale->>'customerId'), '')
          )
        end,
        v_child_key
      );
    elsif v_inventory then
      perform private.assert_cloud_sales_inventory_enabled(v_context);
      v_child_response := public.pos_create_cloud_sale_cashier_inventory_unlimited(
        p_license_key,
        p_device_fingerprint,
        p_security_token,
        p_staff_session_token,
        v_child_sale,
        coalesce(v_child->'items', '[]'::jsonb),
        coalesce(v_child->'payments', '[]'::jsonb),
        v_cash_session_id,
        v_child_key
      );
    else
      perform private.assert_cloud_sales_cashier_enabled(v_context);
      v_child_response := public.pos_create_cloud_sale_cashier_unlimited(
        p_license_key,
        p_device_fingerprint,
        p_security_token,
        p_staff_session_token,
        v_child_sale,
        coalesce(v_child->'items', '[]'::jsonb),
        coalesce(v_child->'payments', '[]'::jsonb),
        v_cash_session_id,
        v_child_key
      );
    end if;

    if coalesce((v_child_response->>'success')::boolean, false) is not true then
      raise exception 'SALE_SPLIT_CHILD_NOT_CONFIRMED:%', coalesce(v_child_response->>'code', 'UNKNOWN') using errcode = 'P0001';
    end if;

    if v_child_response->'sale' is null
       or v_child_response->'sale'->>'id' is null then
      raise exception 'SALE_SPLIT_CHILD_RESPONSE_INVALID' using errcode = 'P0001';
    end if;

    v_sales := v_sales || jsonb_build_array(v_child_response->'sale');
    v_items := v_items || coalesce(v_child_response->'items', '[]'::jsonb);
    v_payments := v_payments || coalesce(v_child_response->'payments', '[]'::jsonb);
    v_children := v_children || jsonb_build_array(jsonb_build_object(
      'label', v_child_label,
      'sale', v_child_response->'sale',
      'items', coalesce(v_child_response->'items', '[]'::jsonb),
      'payments', coalesce(v_child_response->'payments', '[]'::jsonb),
      'cash_session', v_child_response->'cash_session',
      'cash_movement', v_child_response->'cash_movement',
      'customer', v_child_response->'customer',
      'ledger_charge', v_child_response->'ledger_charge',
      'ledger_payment', v_child_response->'ledger_payment',
      'inventory_movements', coalesce(v_child_response->'inventory_movements', '[]'::jsonb),
      'event', v_child_response->'event'
    ));

    v_total := v_total + coalesce((v_child_response->'sale'->>'total')::numeric, 0);
    v_tickets := v_tickets || jsonb_build_array(jsonb_build_object(
      'label', v_child_label,
      'saleId', v_child_response->'sale'->>'id',
      'folio', coalesce(v_child_response->'sale'->>'pos_folio', v_child_response->'sale'->>'folio'),
      'paymentMethod', v_child_response->'sale'->>'payment_method',
      'amountPaid', v_child_response->'sale'->>'amount_paid',
      'saldoPendiente', v_child_response->'sale'->>'balance_due',
      'customerId', v_child_response->'sale'->>'customer_id',
      'total', v_child_response->'sale'->>'total'
    ));
  end loop;

  if v_child_index <> v_child_count then
    raise exception 'FINANCIAL_SPLIT_CHILD_COUNT_INVALID' using errcode = 'P0001';
  end if;
  if abs(round(v_total, 2) - round(coalesce(v_order.total, 0), 2)) > 0.005 then
    raise exception 'RESTAURANT_SPLIT_TOTAL_MISMATCH' using errcode = 'P0001';
  end if;

  select value->>'id', coalesce(value->>'pos_folio', value->>'folio')
    into v_primary_sale_id, v_primary_sale_folio
    from jsonb_array_elements(v_sales)
   limit 1;

  v_payment_summary := jsonb_build_object(
    'source', 'split_bill',
    'splitGroupId', v_split_group_id,
    'parentOrderId', v_parent_order_id,
    'childSaleIds', coalesce((select jsonb_agg(value->>'id') from jsonb_array_elements(v_sales)), '[]'::jsonb),
    'tickets', v_tickets,
    'splitIntent', v_split_intent,
    'splitPayers', case when v_split_intent in ('equal_payment', 'custom_payment') then v_split_payers else '[]'::jsonb end,
    'total', round(v_total, 2),
    'sourceMode', 'cloud_committed'
  );

  v_close_response := public.pos_close_restaurant_order_after_checkout_unlimited(
    p_license_key,
    p_device_fingerprint,
    p_security_token,
    p_staff_session_token,
    v_parent_order_id,
    coalesce(v_primary_sale_id, 'SPLIT-' || v_split_group_id),
    coalesce(v_primary_sale_folio, 'SPLIT-' || v_split_group_id),
    round(v_total, 2),
    v_payment_summary,
    p_internal_idempotency_key || ':restaurant-close'
  );

  if coalesce((v_close_response->>'success')::boolean, false) is not true then
    raise exception 'RESTAURANT_ORDER_CLOSE_NOT_CONFIRMED:%', coalesce(v_close_response->>'code', 'UNKNOWN') using errcode = 'P0001';
  end if;

  select coalesce(max(change_seq), 0)
    into v_latest_change_seq
    from public.pos_sync_events
   where license_id = v_license_id;

  return jsonb_build_object(
    'success', true,
    'mode', 'cloud_split',
    'parent_order_id', v_parent_order_id,
    'split_group_id', v_split_group_id,
    'sales', v_sales,
    'items', v_items,
    'payments', v_payments,
    'children', v_children,
    'restaurant_order_close', v_close_response,
    'total', round(v_total, 2),
    'change_seq', coalesce((v_close_response->>'changeSeq')::bigint, 0),
    'latest_change_seq', v_latest_change_seq,
    'idempotency_key', p_internal_idempotency_key,
    'restaurant_settlement', jsonb_build_object(
      'success', true,
      'parent_order_id', v_parent_order_id,
      'payment_status', 'paid',
      'paid_sale_id', v_primary_sale_id,
      'paid_sale_folio', v_primary_sale_folio,
      'total', round(v_total, 2),
      'status', v_close_response #>> '{order,status}',
      'fulfillment_status', v_close_response #>> '{order,fulfillment_status}'
    )
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.financial_canonical_json_v1(p_value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_key text; v_value jsonb; v_parts text[] := array[]::text[];
begin
  case jsonb_typeof(p_value)
    when 'object' then
      for v_key, v_value in select key, value from jsonb_each(p_value) order by key collate "C" loop
        v_parts := array_append(v_parts, to_jsonb(v_key)::text || ':' || private.financial_canonical_json_v1(v_value));
      end loop;
      return '{' || array_to_string(v_parts, ',') || '}';
    when 'array' then
      return '[' || coalesce((select string_agg(private.financial_canonical_json_v1(value), ',' order by ordinality) from jsonb_array_elements(p_value) with ordinality), '') || ']';
    else return p_value::text;
  end case;
end;
$function$
CREATE OR REPLACE FUNCTION private.financial_cash_movement_allowlist_v2(p_movement jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case
    when jsonb_typeof($1) = 'object' then jsonb_strip_nulls(jsonb_build_object(
      'id', $1->'id',
      'type', $1->'type',
      'amount', $1->'amount',
      'concept', $1->'concept',
      'source', $1->'source',
      'reference_type', $1->'reference_type',
      'reference_id', $1->'reference_id',
      'payment_id', nullif(btrim(coalesce(
        $1->>'payment_id',
        ($1->'metadata')->>'payment_id',
        ($1->'metadata')->>'paymentId',
        ''
      )), ''),
      'created_at', $1->'created_at',
      'server_version', $1->'server_version'
    )) else null
  end;
$function$
CREATE OR REPLACE FUNCTION private.financial_cash_movements_allowlist_v2(p_movements jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select coalesce(
    (
      select jsonb_agg(
        private.financial_cash_movement_allowlist_v2(item)
        order by item_ordinality
      )
      from jsonb_array_elements(
        case
          when jsonb_typeof(coalesce($1, '[]'::jsonb)) = 'array'
            then coalesce($1, '[]'::jsonb)
          else '[]'::jsonb
        end
      ) with ordinality as source(item, item_ordinality)
      where jsonb_typeof(item) = 'object'
    ),
    '[]'::jsonb
  );
$function$
CREATE OR REPLACE FUNCTION private.financial_compact_object_v1(p_object jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
  select case
    when $1 is null or $1 = 'null'::jsonb then $1
    when jsonb_typeof($1) <> 'object' then $1
    else coalesce(
      (
        select jsonb_object_agg(entry.key, entry.value order by entry.key collate "C")
          from jsonb_each($1) as entry(key, value)
         where entry.value <> 'null'::jsonb
      ),
      '{}'::jsonb
    )
  end
$function$
CREATE OR REPLACE FUNCTION private.financial_decimal_v1(p_value jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_numeric numeric;
begin
  if p_value is null or p_value = 'null'::jsonb then return null; end if;
  v_numeric := trim_scale((p_value #>> '{}')::numeric);
  return v_numeric::text;
exception when invalid_text_representation then
  raise exception 'FINANCIAL_NUMERIC_INVALID' using errcode = 'P0001';
end;
$function$
