    when jsonb_typeof($1) = 'object' then jsonb_strip_nulls(jsonb_build_object(
      'entity_type', $1->'entity_type',
      'entity_id', $1->'entity_id',
      'operation', $1->'operation',
      'change_seq', $1->'change_seq',
