CREATE OR REPLACE FUNCTION private.financial_execution_request_v1(p_request jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
begin
  if jsonb_typeof(p_request) <> 'object' then
    raise exception 'FINANCIAL_REQUEST_CONTRACT_INVALID' using errcode = 'P0001';
  end if;
  return p_request;
end;
$function$
CREATE OR REPLACE FUNCTION private.financial_first_nonblank_scalar_v1(p_object jsonb, p_keys text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_key text; v_value jsonb;
begin
  if jsonb_typeof(p_object) <> 'object' then return null; end if;
  foreach v_key in array p_keys loop
    if p_object ? v_key then
      v_value := p_object -> v_key;
