CREATE OR REPLACE FUNCTION private.license_entitlement_state_v1(p_license_id uuid)
 RETURNS TABLE(license_id uuid, plan_code text, plan_name text, expires_at timestamp with time zone, grace_period_ends timestamp with time zone, lifecycle_state text, is_entitled boolean, is_in_grace boolean, effective_features jsonb)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  with source as (
    select
      l.id as license_id,
      coalesce(p.code, l.license_type::text) as plan_code,
      coalesce(p.name, l.product_name::text) as plan_name,
      l.status as administrative_status,
      coalesce(l.is_lifetime, false) as is_lifetime,
      l.expires_at,
      coalesce(p.features, '{}'::jsonb) || coalesce(l.features, '{}'::jsonb) as stored_features
    from public.licenses l
    left join public.plans p on p.id = l.plan_id
    where l.id = p_license_id
  ), classified as (
    select
      source.*,
      case
        when lower(coalesce(source.administrative_status::text, '')) <> 'active'
          then 'administratively_blocked'
        when source.is_lifetime or source.expires_at is null or now() <= source.expires_at
          then 'active'
        when now() <= source.expires_at + interval '7 days'
          then 'grace_period'
        else 'expired'
      end as derived_state
    from source
  )
  select
    classified.license_id,
    classified.plan_code,
    classified.plan_name,
    classified.expires_at,
    case
      when not classified.is_lifetime and classified.expires_at is not null
        then classified.expires_at + interval '7 days'
      else null
    end as grace_period_ends,
    classified.derived_state as lifecycle_state,
    classified.derived_state in ('active', 'grace_period') as is_entitled,
    classified.derived_state = 'grace_period' as is_in_grace,
    case
      when classified.derived_state in ('active', 'grace_period')
        then classified.stored_features
      else '{}'::jsonb
    end as effective_features
  from classified;
$function$
CREATE OR REPLACE FUNCTION private.lock_financial_operation_v1(p_license_id uuid, p_external_idempotency_key text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if nullif(btrim(p_external_idempotency_key), '') is null then
    raise exception 'FINANCIAL_IDEMPOTENCY_KEY_REQUIRED' using errcode = 'P0001';
  end if;
  -- Lock ordering is: tenant/K advisory lock, then financial-operation row,
  -- then the existing financial RPC's own locks.  Receipt only takes the first
  -- lock and reads, so it cannot form a reverse lock cycle.
  perform pg_advisory_xact_lock(hashtextextended(p_license_id::text || ':' || p_external_idempotency_key, 9152026));
end;
$function$
CREATE OR REPLACE FUNCTION private.lock_restaurant_order_settlement_v1(p_license_id uuid, p_local_order_id text)
 RETURNS pos_restaurant_orders
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_order public.pos_restaurant_orders;
begin
  if p_license_id is null or nullif(btrim(p_local_order_id), '') is null then raise exception 'RESTAURANT_PARENT_ORDER_REQUIRED' using errcode = 'P0001'; end if;
  perform pg_advisory_xact_lock(hashtext(p_license_id::text), hashtext('restaurant_split:' || p_local_order_id));
  select * into v_order from public.pos_restaurant_orders o where o.license_id = p_license_id and o.local_order_id = p_local_order_id order by (o.deleted_at is null) desc, o.updated_at desc nulls last, o.id limit 1 for update;
  return v_order;
end;
$function$
