CREATE OR REPLACE FUNCTION private.next_pos_sale_folio(p_license_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_sequence public.pos_folio_sequences;
  v_next bigint;
  v_folio text;
  v_operational_prefix text;
begin
  if p_license_id is null then
    raise exception 'LICENSE_ID_REQUIRED_FOR_FOLIO' using errcode = 'P0001';
  end if;

  perform pg_advisory_xact_lock(hashtext(p_license_id::text), hashtext('pos_sale_folio'));

  v_operational_prefix := private.derive_pos_operational_prefix_v1(p_license_id);

  insert into public.pos_folio_sequences (
    license_id,
    sequence_name,
    current_value,
    prefix,
    padding,
    operational_prefix,
    operational_terminal
  )
  values (
    p_license_id,
    'sale',
    0,
    'V',
    6,
    v_operational_prefix,
    '01'
  )
  on conflict (license_id, sequence_name) do nothing;

  update public.pos_folio_sequences
     set current_value = current_value + 1,
         updated_at = now()
   where license_id = p_license_id
     and sequence_name = 'sale'
  returning * into v_sequence;

  v_next := v_sequence.current_value;
  v_folio := v_sequence.prefix || '-' || lpad(v_next::text, v_sequence.padding, '0');

  return jsonb_build_object(
    'folio', v_folio,
    'sequence', v_next,
    'prefix', v_sequence.prefix,
    'padding', v_sequence.padding,
    'pos_folio', private.format_pos_operational_folio_v1(p_license_id, v_next)
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.normalize_layaway_items_v1(p_items jsonb, p_total numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_item jsonb;
  v_normalized jsonb := '[]'::jsonb;
  v_quantity numeric;
  v_unit_price numeric;
  v_line_subtotal numeric;
  v_line_total numeric;
  v_declared_line_total numeric;
  v_discount_input jsonb;
  v_discount_result jsonb;
  v_discount_amount numeric;
  v_tax_amount numeric;
  v_item_total numeric := 0;
  v_count integer := 0;
begin
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then
    raise exception 'LAYAWAY_ITEMS_INVALID' using errcode = 'P0001';
  end if;

  for v_item in select value from jsonb_array_elements(p_items) loop
    v_count := v_count + 1;
    if jsonb_typeof(v_item) <> 'object' then
      raise exception 'LAYAWAY_ITEM_INVALID' using errcode = 'P0001';
    end if;

    v_quantity := private.layaway_request_numeric_v1(v_item, array['quantity','qty']);
    v_unit_price := private.layaway_request_numeric_v1(v_item, array['unit_price','unitPrice','price']);
    v_declared_line_total := private.layaway_request_numeric_v1(
      v_item, array['line_total','lineTotal','total','exactTotal']
    );

    if v_quantity is null or v_quantity <= 0 or v_unit_price is null or v_unit_price < 0 then
      raise exception 'LAYAWAY_ITEM_AMOUNT_INVALID' using errcode = 'P0001';
    end if;
    v_line_subtotal := round(v_quantity * v_unit_price, 2);

    v_discount_input := coalesce(
      nullif(v_item->'discount', 'null'::jsonb),
      nullif(v_item->'discountAmount', 'null'::jsonb),
      nullif(v_item->'discount_amount', 'null'::jsonb)
    );
    if v_discount_input is null then
      v_discount_amount := private.layaway_request_numeric_v1(
        v_item, array['discount_amount','discountAmount'], null
      );
      if v_discount_amount is not null and v_discount_amount <> 0 then
        v_discount_input := jsonb_build_object(
          'type', 'amount',
          'value', v_discount_amount,
          'reason', coalesce(v_item->>'discountReason', v_item->>'discount_reason')
        );
      end if;
    end if;
    v_discount_result := private.r2b_normalize_discount_v1(v_discount_input, v_line_subtotal, 'line');
    v_discount_amount := coalesce((v_discount_result->>'amount')::numeric, 0);
    v_line_total := round(v_line_subtotal - v_discount_amount, 2);

    v_tax_amount := greatest(coalesce(private.layaway_request_numeric_v1(
      v_item, array['tax_amount','taxAmount'], 0
    ), 0), 0);
    if v_tax_amount > 0.005 then
      raise exception 'LAYAWAY_TAX_SOURCE_UNRESOLVED' using errcode = 'P0001';
    end if;

    if v_declared_line_total is not null and abs(v_declared_line_total - v_line_total) > 0.005 then
      raise exception 'LAYAWAY_ITEM_TOTAL_MISMATCH' using errcode = 'P0001';
    end if;
    v_item_total := v_item_total + v_line_total;
    v_normalized := v_normalized || jsonb_build_array(
      v_item || jsonb_build_object(
        'quantity', v_quantity,
        'unit_price', v_unit_price,
        'line_subtotal', v_line_subtotal,
        'line_total', v_line_total,
        'discount', v_discount_result->'discount',
        'discount_amount', v_discount_amount,
        'tax_amount', 0
      )
    );
  end loop;

  if v_count = 0 then
    raise exception 'LAYAWAY_ITEMS_REQUIRED' using errcode = 'P0001';
  end if;
  if p_total is null or p_total <= 0 then
    raise exception 'LAYAWAY_TOTAL_INVALID' using errcode = 'P0001';
  end if;
  if abs(round(v_item_total, 2) - p_total) > 0.005 then
    raise exception 'LAYAWAY_TOTAL_MISMATCH' using errcode = 'P0001';
  end if;

  return jsonb_build_object('items', v_normalized, 'total', round(v_item_total, 2));
end;
$function$
CREATE OR REPLACE FUNCTION private.normalize_pos_sale_payment_method(p_method text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare
  v_method text := lower(btrim(coalesce(p_method, '')));
begin
  if v_method in ('cash', 'efectivo') then
    return 'cash';
  end if;
  if v_method in ('card', 'tarjeta', 'tarjeta_credito', 'tarjeta_debito', 'debit', 'credit_card', 'debit_card') then
    return 'card';
  end if;
  if v_method in ('transfer', 'transferencia', 'spei', 'bank_transfer') then
    return 'transfer';
  end if;
  if v_method in ('mixed', 'mixto') then
    return 'mixed';
  end if;
  if v_method in ('fiado', 'credit', 'credito', 'crédito', 'debt', 'customer_credit', 'cuenta_cliente') then
    return 'credit';
  end if;
  return nullif(v_method, '');
end;
$function$
CREATE OR REPLACE FUNCTION private.normalize_sale_inventory_item(p_payload jsonb, p_ordinality bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_product_id text;
  v_batch_id text;
  v_quantity numeric;
  v_unit_cost numeric;
  v_stock_source text;
  v_batches jsonb;
  v_selected_modifiers jsonb;
begin
  if jsonb_typeof(coalesce(p_payload, '{}'::jsonb)) <> 'object' then
    raise exception 'SALE_ITEM_PAYLOAD_INVALID' using errcode = 'P0001';
  end if;

  v_product_id := private.pos_sale_jsonb_text(p_payload, array['product_id','productId','parentId']);
  v_batch_id := private.pos_sale_jsonb_text(p_payload, array['batch_id','batchId']);
  v_quantity := private.pos_sale_jsonb_numeric(p_payload, array['quantity','qty'], 0);
  v_unit_cost := private.pos_sale_jsonb_numeric(p_payload, array['unit_cost','unitCost','cost'], null);
  v_stock_source := lower(coalesce(private.pos_sale_jsonb_text(p_payload, array['stock_source','stockSource'], null), ''));
  v_batches := coalesce(p_payload->'batches_used', p_payload->'batchesUsed', p_payload->'metadata'->'batches_used', p_payload->'metadata'->'batchesUsed', '[]'::jsonb);
  v_selected_modifiers := coalesce(p_payload->'selected_modifiers', p_payload->'selectedModifiers', p_payload->'metadata'->'selected_modifiers', p_payload->'metadata'->'selectedModifiers', '[]'::jsonb);

  if v_quantity <= 0 then
    raise exception 'SALE_ITEM_QUANTITY_INVALID' using errcode = 'P0001';
  end if;

  if v_unit_cost is not null and v_unit_cost < 0 then
    raise exception 'SALE_ITEM_AMOUNT_INVALID' using errcode = 'P0001';
  end if;

  if jsonb_typeof(v_batches) <> 'array' then
    v_batches := '[]'::jsonb;
  end if;

  if jsonb_typeof(v_selected_modifiers) <> 'array' then
    v_selected_modifiers := '[]'::jsonb;
  end if;

  return jsonb_build_object(
    'item_id', coalesce(private.pos_sale_jsonb_text(p_payload, array['id','lineId','cartLineId']), 'item:' || p_ordinality::text),
    'product_id', v_product_id,
    'product_name', coalesce(private.pos_sale_jsonb_text(p_payload, array['product_name','productName','name']), 'Producto'),
    'batch_id', v_batch_id,
    'quantity', v_quantity,
    'unit_cost', v_unit_cost,
    'stock_source', nullif(v_stock_source, ''),
    'batches_used', v_batches,
    'selected_modifiers', v_selected_modifiers
  );
end;
$function$
