CREATE OR REPLACE FUNCTION private.record_pos_customer_credit_event(p_license_id uuid, p_entity_type text, p_entity_id text, p_operation text, p_actor_device_id uuid DEFAULT NULL::uuid, p_actor_staff_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb, p_server_version integer DEFAULT 1)
 RETURNS pos_sync_events
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_operation text;
  v_metadata jsonb := coalesce(p_metadata, '{}'::jsonb);
begin
  v_operation := case p_operation
    when 'initial_balance' then 'create'
    when 'migration' then 'create'
    when 'payment' then 'create'
    when 'credit_update' then 'update'
    when 'credit_migration' then 'update'
    when 'customer_payment' then 'movement'
    else p_operation
  end;

  if v_operation is distinct from p_operation then
    v_metadata := v_metadata || jsonb_build_object('credit_operation', p_operation);
  end if;

  return private.record_pos_sync_event(
    p_license_id,
    p_entity_type,
    p_entity_id,
    v_operation,
    p_actor_device_id,
    p_actor_staff_user_id,
    p_idempotency_key,
    v_metadata,
    p_server_version
  );
end;
