CREATE OR REPLACE FUNCTION private.release_layaway_stock_v1(p_license_id uuid, p_layaway_id text, p_actor_device_id uuid, p_actor_staff_user_id uuid, p_actor_key text, p_actor_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_reservation public.pos_layaway_inventory_reservations;
  v_product public.pos_products;
  v_batch public.pos_product_batches;
  v_product_committed numeric;
  v_operation_key text;
begin
  for v_reservation in
    select *
      from public.pos_layaway_inventory_reservations r
     where r.license_id = p_license_id
       and r.layaway_id = p_layaway_id
       and r.status = 'reserved'
     order by r.product_id, coalesce(r.batch_id, ''), r.item_index
     for update
  loop
    v_operation_key := coalesce(p_idempotency_key, p_layaway_id) || ':release:' || v_reservation.item_index::text;
    v_product := null;
    v_batch := null;
    if v_reservation.batch_id is not null then
      select * into v_product
        from public.pos_products p
       where p.license_id = p_license_id and p.id = v_reservation.product_id and p.deleted_at is null
       for update;
      if v_product.id is null then
        raise exception 'LAYAWAY_RESERVATION_SOURCE_MISSING:%', v_reservation.product_id using errcode = 'P0001';
      end if;
      select * into v_batch
        from public.pos_product_batches b
       where b.license_id = p_license_id and b.id = v_reservation.batch_id and b.deleted_at is null
       for update;
      if v_batch.id is null then
        raise exception 'LAYAWAY_RESERVATION_SOURCE_MISSING:%', v_reservation.batch_id using errcode = 'P0001';
      end if;
      update public.pos_product_batches
         set committed_stock = greatest(coalesce(committed_stock, 0) - v_reservation.quantity, 0),
             updated_at = now(), server_version = server_version + 1,
             updated_by_device_id = p_actor_device_id,
             updated_by_staff_user_id = p_actor_staff_user_id,
             last_idempotency_key = v_operation_key
       where license_id = p_license_id and id = v_reservation.batch_id
       returning * into v_batch;
      select coalesce(sum(coalesce(b.committed_stock, 0)), 0)
        into v_product_committed
        from public.pos_product_batches b
       where b.license_id = p_license_id and b.product_id = v_reservation.product_id and b.deleted_at is null;
      update public.pos_products
         set committed_stock = v_product_committed,
             updated_at = now(), server_version = server_version + 1,
             updated_by_device_id = p_actor_device_id,
             updated_by_staff_user_id = p_actor_staff_user_id,
             last_idempotency_key = v_operation_key
       where license_id = p_license_id and id = v_reservation.product_id
       returning * into v_product;
      perform private.record_pos_sync_event(
        p_license_id, 'product_batch', v_reservation.batch_id, 'update', p_actor_device_id,
        p_actor_staff_user_id, v_operation_key,
        jsonb_build_object('reason', 'layaway_stock_released', 'layaway_id', p_layaway_id, 'reservation_id', v_reservation.id),
        v_batch.server_version
      );
      perform private.record_pos_sync_event(
        p_license_id, 'product', v_reservation.product_id, 'update', p_actor_device_id,
        p_actor_staff_user_id, v_operation_key,
        jsonb_build_object('reason', 'layaway_stock_released', 'layaway_id', p_layaway_id, 'reservation_id', v_reservation.id),
        v_product.server_version
      );
    else
      update public.pos_products
         set committed_stock = greatest(coalesce(committed_stock, 0) - v_reservation.quantity, 0),
             updated_at = now(), server_version = server_version + 1,
             updated_by_device_id = p_actor_device_id,
             updated_by_staff_user_id = p_actor_staff_user_id,
             last_idempotency_key = v_operation_key
       where license_id = p_license_id and id = v_reservation.product_id
       returning * into v_product;
      if v_product.id is null then
        raise exception 'LAYAWAY_RESERVATION_SOURCE_MISSING:%', v_reservation.product_id using errcode = 'P0001';
      end if;
      perform private.record_pos_sync_event(
        p_license_id, 'product', v_reservation.product_id, 'update', p_actor_device_id,
        p_actor_staff_user_id, v_operation_key,
        jsonb_build_object('reason', 'layaway_stock_released', 'layaway_id', p_layaway_id, 'reservation_id', v_reservation.id),
        v_product.server_version
      );
    end if;

    update public.pos_layaway_inventory_reservations
       set status = 'released', released_at = now(), server_version = server_version + 1,
           idempotency_key = v_operation_key,
           metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('releasedByActorKey', p_actor_key)
     where license_id = p_license_id and id = v_reservation.id;
  end loop;

  return (
    select coalesce(jsonb_agg(private.pos_layaway_reservation_to_jsonb(r) order by r.item_index), '[]'::jsonb)
      from public.pos_layaway_inventory_reservations r
     where r.license_id = p_license_id and r.layaway_id = p_layaway_id
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.require_active_admin_session(p_license_key text, p_device_fingerprint text, p_device_security_token text, p_admin_session_token text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_license record;
  v_device record;
  v_session record;
begin
  if nullif(btrim(coalesce(p_license_key, '')), '') is null
     or nullif(btrim(coalesce(p_device_fingerprint, '')), '') is null
     or nullif(btrim(coalesce(p_device_security_token, '')), '') is null
     or nullif(btrim(coalesce(p_admin_session_token, '')), '') is null then
    return jsonb_build_object('success', false, 'valid', false, 'code', 'ADMIN_SESSION_REQUIRED');
  end if;

  select
    l.id as license_id,
    l.license_key,
    entitlement.lifecycle_state,
    entitlement.is_entitled,
    entitlement.is_in_grace,
    entitlement.grace_period_ends
  into v_license
  from public.licenses l
  cross join lateral private.license_entitlement_state_v1(l.id) entitlement
  where l.license_key = p_license_key
  limit 1;

  if v_license.license_id is null then
    return jsonb_build_object('success', false, 'valid', false, 'code', 'LICENSE_NOT_ACTIVE');
  end if;
  if v_license.lifecycle_state = 'administratively_blocked' then
    return jsonb_build_object('success', false, 'valid', false, 'code', 'LICENSE_NOT_ACTIVE');
  end if;
  if v_license.is_entitled is not true then
    return jsonb_build_object('success', false, 'valid', false, 'code', 'LICENSE_EXPIRED');
  end if;

  select d.id as device_id, d.device_mode, d.device_role as legacy_device_role
  into v_device
  from public.license_devices d
  where d.license_id = v_license.license_id
    and d.device_fingerprint = p_device_fingerprint
    and d.is_active is true
    and d.device_mode in ('admin_only', 'shared')
    and (d.security_token = p_device_security_token or d.previous_security_token = p_device_security_token)
  limit 1;

  if v_device.device_id is null then
    return jsonb_build_object('success', false, 'valid', false, 'code', 'ADMIN_DEVICE_REQUIRED');
  end if;

  select candidate.id as session_id, candidate.admin_user_id, candidate.expires_at,
         u.username, u.display_name
  into v_session
  from (
    select s.id, s.admin_user_id, s.session_token_hash, s.expires_at, s.created_at
    from public.license_admin_sessions s
    where s.license_id = v_license.license_id
      and s.device_id = v_device.device_id
      and s.revoked_at is null
    order by s.created_at desc
    limit 3
  ) candidate
  join public.license_admin_users u on u.id = candidate.admin_user_id
  where u.license_id = v_license.license_id
    and u.is_owner is true
    and u.is_active is true
    and extensions.crypt(p_admin_session_token, candidate.session_token_hash) = candidate.session_token_hash
  limit 1;

  if v_session.session_id is null then
    return jsonb_build_object('success', false, 'valid', false, 'code', 'ADMIN_SESSION_INVALID');
  end if;

  if v_session.expires_at <= now() then
    update public.license_admin_sessions
    set revoked_at = coalesce(revoked_at, now())
    where id = v_session.session_id;
    return jsonb_build_object('success', false, 'valid', false, 'code', 'ADMIN_SESSION_EXPIRED');
  end if;

  update public.license_admin_sessions
  set last_used_at = now()
  where id = v_session.session_id
    and last_used_at < now() - interval '30 seconds';

  return jsonb_build_object(
    'success', true,
    'valid', true,
    'license_id', v_license.license_id,
    'device_id', v_device.device_id,
    'device_mode', v_device.device_mode,
    'legacy_device_role', v_device.legacy_device_role,
    'admin_session_id', v_session.session_id,
    'admin_user_id', v_session.admin_user_id,
    'admin_user', jsonb_build_object(
      'id', v_session.admin_user_id,
      'username', v_session.username,
      'display_name', v_session.display_name,
      'is_owner', true
    ),
    'expires_at', v_session.expires_at,
    'license_lifecycle_state', v_license.lifecycle_state,
    'license_is_in_grace', v_license.is_in_grace,
    'license_grace_period_ends', v_license.grace_period_ends
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.reserve_financial_operation_v1(p_license_id uuid, p_idempotency_key text, p_request_hash text, p_operation_type text, p_canonical_request jsonb, p_verified_actor_key text, p_verified_device_id uuid, p_cash_session_id text DEFAULT NULL::text, p_verified_cash_station_id text DEFAULT NULL::text)
 RETURNS pos_financial_operations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_existing public.pos_financial_operations;
  v_result public.pos_financial_operations;
  v_expected_hash text;
  v_session public.pos_cash_sessions;
  v_internal_idempotency_key text;
  v_operation_id uuid := extensions.gen_random_uuid();
begin
  if nullif(btrim(p_idempotency_key), '') is null then
    raise exception 'FINANCIAL_IDEMPOTENCY_KEY_REQUIRED' using errcode = 'P0001';
  end if;
  perform private.assert_financial_request_hash_v1(p_request_hash);
  -- Reconstruct the origin-bound H from this invocation before considering an
  -- existing receipt.  A stale H may never turn a changed request into replay.
  if p_cash_session_id is not null then
    select * into v_session from public.pos_cash_sessions s
    where s.license_id = p_license_id and s.id = p_cash_session_id and s.deleted_at is null;
    if v_session.id is null then
      raise exception 'CASH_SESSION_NOT_FOUND' using errcode = 'P0001';
    end if;
  end if;

  v_expected_hash := private.financial_operation_hash(
    p_operation_type, p_canonical_request, p_verified_actor_key,
    p_cash_session_id, coalesce(v_session.cash_station_id, p_verified_cash_station_id)
  );
  if p_request_hash is distinct from v_expected_hash then
    raise exception 'FINANCIAL_REQUEST_HASH_INVALID' using errcode = 'P0001';
  end if;
  perform private.lock_financial_operation_v1(p_license_id, p_idempotency_key);

  -- Financial K/H state is authoritative and takes precedence over a generic
  -- idempotency row.  The latter is consulted only when no financial row exists.
  select * into v_existing from public.pos_financial_operations o
  where o.license_id = p_license_id and o.idempotency_key = p_idempotency_key
  for update;
  if v_existing.id is not null then
    if v_existing.legacy_idempotency_key is distinct from
       private.financial_operation_internal_key_v1(v_existing.operation_type, v_existing.id) then
      raise exception 'FINANCIAL_INTERNAL_IDEMPOTENCY_INTEGRITY' using errcode = 'P0001';
    end if;
    if v_existing.request_hash is distinct from p_request_hash then
      raise exception 'IDEMPOTENCY_CONFLICT' using errcode = 'P0001';
    end if;
    perform private.assert_financial_operation_origin_v1(
      v_existing, p_verified_actor_key, p_verified_device_id, p_cash_session_id
    );
    return v_existing;
  end if;

  -- A generic K in the external namespace predates strict V1 and cannot be
  -- adopted.  V1 itself writes only a server-owned internal namespace below.
  if exists (
    select 1 from public.pos_idempotency_keys k
  where k.license_id = p_license_id and k.idempotency_key = p_idempotency_key
  ) then raise exception 'LEGACY_IDEMPOTENCY_UNVERIFIED' using errcode = 'P0001'; end if;
  v_internal_idempotency_key := private.financial_operation_internal_key_v1(p_operation_type, v_operation_id);
  -- Never adopt a preexisting generic row in this server-generated namespace.
  -- With no strict owner above, this is a collision, not a replay.
  if exists (
    select 1 from public.pos_idempotency_keys k
    where k.license_id = p_license_id and k.idempotency_key = v_internal_idempotency_key
  ) then raise exception 'FINANCIAL_INTERNAL_IDEMPOTENCY_COLLISION' using errcode = 'P0001'; end if;

  insert into public.pos_financial_operations (
    id, license_id, idempotency_key, legacy_idempotency_key, request_hash, operation_type,
    verified_actor_key, verified_device_id, verified_cash_session_id, verified_cash_station_id,
    canonical_request
  ) values (
    v_operation_id, p_license_id, p_idempotency_key, v_internal_idempotency_key, p_request_hash, p_operation_type,
    p_verified_actor_key, p_verified_device_id, p_cash_session_id, coalesce(v_session.cash_station_id, p_verified_cash_station_id),
    p_canonical_request
  ) on conflict (license_id, idempotency_key) do nothing
  returning * into v_result;

  if v_result.id is null then
    raise exception 'FINANCIAL_OPERATION_RESERVATION_FAILED' using errcode = 'P0001';
  end if;
  return v_result;
end;
$function$
CREATE OR REPLACE FUNCTION private.reserve_layaway_stock_v1(p_license_id uuid, p_layaway_id text, p_items jsonb, p_actor_device_id uuid, p_actor_staff_user_id uuid, p_actor_key text, p_actor_name text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item record;
  v_product public.pos_products;
  v_batch public.pos_product_batches;
  v_reservation public.pos_layaway_inventory_reservations;
  v_product_id text;
  v_batch_id text;
  v_quantity numeric;
  v_item_index integer;
  v_product_committed numeric;
  v_previous_committed numeric;
  v_new_committed numeric;
  v_reservation_id text;
  v_operation_key text;
  v_variant_attributes jsonb;
  v_item_attributes jsonb;
  v_requested_size text;
  v_requested_color text;
  v_requested_batch_sku text;
  v_authoritative_item jsonb;
  v_requested_unit_price numeric;
begin
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then
    raise exception 'LAYAWAY_ITEMS_INVALID' using errcode = 'P0001';
  end if;

  for v_item in
    select value as payload, ordinality::integer as item_index
      from jsonb_array_elements(p_items) with ordinality
     order by private.layaway_request_text_v1(value, array['product_id','productId','parentId']),
              private.layaway_request_text_v1(value, array['batch_id','batchId']),
              ordinality
  loop
    v_item_index := v_item.item_index;
    v_product := null;
    v_batch := null;
    v_product_id := private.layaway_request_text_v1(
      v_item.payload, array['product_id','productId','parentId']
    );
    if v_product_id is null then
      raise exception 'LAYAWAY_PRODUCT_REQUIRED' using errcode = 'P0001';
    end if;
    v_quantity := private.layaway_request_numeric_v1(v_item.payload, array['quantity','qty']);
    v_batch_id := private.layaway_request_text_v1(v_item.payload, array['batch_id','batchId']);

    select * into v_product
      from public.pos_products p
     where p.license_id = p_license_id
       and p.id = v_product_id
       and p.deleted_at is null
       and p.is_active is true
     for update;
    if v_product.id is null then
      raise exception 'LAYAWAY_PRODUCT_NOT_SYNCED:%', v_product_id using errcode = 'P0001';
    end if;

    if private.product_uses_batches(v_product) is true then
      if v_batch_id is null then
        raise exception 'LAYAWAY_BATCH_REQUIRED:%', v_product_id using errcode = 'P0001';
      end if;

      select * into v_batch
        from public.pos_product_batches b
       where b.license_id = p_license_id
         and b.id = v_batch_id
         and b.product_id = v_product_id
         and b.deleted_at is null
         and b.is_active is true
         and b.status = 'active'
       for update;
      if v_batch.id is null then
        raise exception 'LAYAWAY_BATCH_NOT_AVAILABLE:%', v_batch_id using errcode = 'P0001';
      end if;
      if v_batch.track_stock is not true then
        raise exception 'LAYAWAY_BATCH_STOCK_UNSAFE:%', v_batch_id using errcode = 'P0001';
      end if;
      v_variant_attributes := case
        when jsonb_typeof(v_item.payload->'variant_attributes') = 'object' then v_item.payload->'variant_attributes'
        when jsonb_typeof(v_item.payload->'variantAttributes') = 'object' then v_item.payload->'variantAttributes'
        else '{}'::jsonb
      end;
      v_item_attributes := case
        when jsonb_typeof(v_item.payload->'attributes') = 'object' then v_item.payload->'attributes'
        else '{}'::jsonb
      end;
      if v_variant_attributes <> '{}'::jsonb
         and (
           jsonb_typeof(coalesce(v_batch.attributes, '{}'::jsonb)) <> 'object'
           or not (coalesce(v_batch.attributes, '{}'::jsonb) @> v_variant_attributes)
           and not (coalesce(v_batch.attributes->'optionValues', '{}'::jsonb) @> v_variant_attributes)
           and not (coalesce(v_batch.metadata->'optionValues', '{}'::jsonb) @> v_variant_attributes)
         ) then
        raise exception 'LAYAWAY_VARIANT_MISMATCH:%', v_batch_id using errcode = 'P0001';
      end if;
      if v_item_attributes <> '{}'::jsonb
         and (
           jsonb_typeof(coalesce(v_batch.attributes, '{}'::jsonb)) <> 'object'
           or (
             not (coalesce(v_batch.attributes, '{}'::jsonb) @> v_item_attributes)
             and not (coalesce(v_batch.attributes->'optionValues', '{}'::jsonb) @> v_item_attributes)
             and not (coalesce(v_batch.metadata->'optionValues', '{}'::jsonb) @> v_item_attributes)
           )
         ) then
        raise exception 'LAYAWAY_VARIANT_MISMATCH:%', v_batch_id using errcode = 'P0001';
      end if;
      v_requested_size := private.layaway_request_text_v1(v_item.payload, array['size','talla']);
      if v_requested_size is not null
         and lower(v_requested_size) <> lower(coalesce(v_batch.attributes->>'size', v_batch.attributes->>'talla', v_batch.metadata->>'size', v_batch.metadata->>'talla', '')) then
        raise exception 'LAYAWAY_VARIANT_MISMATCH:%', v_batch_id using errcode = 'P0001';
      end if;
      v_requested_color := private.layaway_request_text_v1(v_item.payload, array['color','colorName']);
      if v_requested_color is not null
         and lower(v_requested_color) <> lower(coalesce(v_batch.attributes->>'color', v_batch.attributes->>'colorName', v_batch.metadata->>'color', v_batch.metadata->>'colorName', '')) then
        raise exception 'LAYAWAY_VARIANT_MISMATCH:%', v_batch_id using errcode = 'P0001';
      end if;
      v_requested_batch_sku := private.layaway_request_text_v1(v_item.payload, array['batch_sku','batchSku']);
      if v_requested_batch_sku is not null
         and lower(v_requested_batch_sku) <> lower(coalesce(v_batch.sku, '')) then
        raise exception 'LAYAWAY_BATCH_MISMATCH:%', v_batch_id using errcode = 'P0001';
      end if;
      if greatest(coalesce(v_batch.stock, 0) - coalesce(v_batch.committed_stock, 0), 0) < v_quantity then
        raise exception 'INSUFFICIENT_CLOUD_STOCK:%', v_product_id using errcode = 'P0001';
      end if;
    else
      if v_batch_id is not null then
        raise exception 'LAYAWAY_BATCH_NOT_ALLOWED:%', v_product_id using errcode = 'P0001';
      end if;
    end if;

    v_authoritative_item := private.layaway_authoritative_item_v1(v_product, v_batch, v_item.payload);
    v_requested_unit_price := private.layaway_request_numeric_v1(
      v_item.payload, array['unit_price','unitPrice','price']
    );
    if v_requested_unit_price is null
       or abs(v_requested_unit_price - (v_authoritative_item->>'unit_price')::numeric) > 0.005 then
      raise exception 'LAYAWAY_PRICE_MISMATCH:%', v_product_id using errcode = 'P0001';
    end if;

    -- Non-stock products remain a complete snapshot but do not create a
    -- reservation. The decision is server-side; client track_stock is not
    -- authoritative.
    if v_product.track_stock is not true then
      continue;
    end if;

    if v_batch.id is not null then
      v_previous_committed := coalesce(v_batch.committed_stock, 0);
      v_new_committed := v_previous_committed + v_quantity;
      v_operation_key := coalesce(p_idempotency_key, p_layaway_id) || ':reservation:' || v_item_index::text;

      update public.pos_product_batches
         set committed_stock = v_new_committed,
             updated_at = now(),
             server_version = server_version + 1,
             updated_by_device_id = p_actor_device_id,
             updated_by_staff_user_id = p_actor_staff_user_id,
             last_idempotency_key = v_operation_key,
             metadata = coalesce(metadata, '{}'::jsonb)
               || jsonb_build_object('lastLayawayReservationId', p_layaway_id, 'lastLayawayReservationAt', now())
       where license_id = p_license_id and id = v_batch.id
       returning * into v_batch;

      select coalesce(sum(coalesce(b.committed_stock, 0)), 0)
        into v_product_committed
        from public.pos_product_batches b
       where b.license_id = p_license_id
         and b.product_id = v_product_id
         and b.deleted_at is null;
      update public.pos_products
         set committed_stock = v_product_committed,
             updated_at = now(),
             server_version = server_version + 1,
             updated_by_device_id = p_actor_device_id,
             updated_by_staff_user_id = p_actor_staff_user_id,
             last_idempotency_key = v_operation_key,
             metadata = coalesce(metadata, '{}'::jsonb)
               || jsonb_build_object('lastLayawayReservationId', p_layaway_id, 'lastLayawayReservationAt', now())
       where license_id = p_license_id and id = v_product_id
       returning * into v_product;

      v_reservation_id := p_layaway_id || ':reservation:' || v_item_index::text;
      insert into public.pos_layaway_inventory_reservations (
        id, license_id, layaway_id, item_index, product_id, batch_id, quantity, unit_cost,
        stock_before, stock_after, committed_before, committed_after, status,
        created_by_device_id, created_by_staff_user_id, actor_key, actor_name,
        idempotency_key, metadata
      ) values (
        v_reservation_id, p_license_id, p_layaway_id, v_item_index, v_product_id, v_batch_id, v_quantity,
        greatest(coalesce(v_batch.cost, v_product.cost), 0),
        coalesce(v_batch.stock, 0), coalesce(v_batch.stock, 0),
        v_previous_committed, v_new_committed, 'reserved',
        p_actor_device_id, p_actor_staff_user_id, p_actor_key, p_actor_name,
        v_operation_key,
        jsonb_strip_nulls(jsonb_build_object(
          'phase', 'cloud_layaways_server_contract_r1',
          'stock_source', 'batch',
          'variant_attributes', v_item.payload->'variant_attributes',
          'attributes', v_item.payload->'attributes'
        ))
      ) returning * into v_reservation;

      perform private.record_pos_sync_event(
        p_license_id, 'product_batch', v_batch.id, 'update', p_actor_device_id,
        p_actor_staff_user_id, v_operation_key,
        jsonb_build_object('reason', 'layaway_stock_reserved', 'layaway_id', p_layaway_id, 'reservation_id', v_reservation.id),
        v_batch.server_version
      );
      perform private.record_pos_sync_event(
        p_license_id, 'product', v_product_id, 'update', p_actor_device_id,
        p_actor_staff_user_id, v_operation_key,
        jsonb_build_object('reason', 'layaway_stock_reserved', 'layaway_id', p_layaway_id, 'reservation_id', v_reservation.id),
        v_product.server_version
      );
    else
      if greatest(coalesce(v_product.stock, 0) - coalesce(v_product.committed_stock, 0), 0) < v_quantity then
        raise exception 'INSUFFICIENT_CLOUD_STOCK:%', v_product_id using errcode = 'P0001';
      end if;

      v_previous_committed := coalesce(v_product.committed_stock, 0);
      v_new_committed := v_previous_committed + v_quantity;
      v_operation_key := coalesce(p_idempotency_key, p_layaway_id) || ':reservation:' || v_item_index::text;
      update public.pos_products
         set committed_stock = v_new_committed,
             updated_at = now(),
             server_version = server_version + 1,
             updated_by_device_id = p_actor_device_id,
             updated_by_staff_user_id = p_actor_staff_user_id,
             last_idempotency_key = v_operation_key,
             metadata = coalesce(metadata, '{}'::jsonb)
               || jsonb_build_object('lastLayawayReservationId', p_layaway_id, 'lastLayawayReservationAt', now())
       where license_id = p_license_id and id = v_product_id
       returning * into v_product;

      v_reservation_id := p_layaway_id || ':reservation:' || v_item_index::text;
      insert into public.pos_layaway_inventory_reservations (
        id, license_id, layaway_id, item_index, product_id, batch_id, quantity, unit_cost,
        stock_before, stock_after, committed_before, committed_after, status,
        created_by_device_id, created_by_staff_user_id, actor_key, actor_name,
        idempotency_key, metadata
      ) values (
        v_reservation_id, p_license_id, p_layaway_id, v_item_index, v_product_id, null, v_quantity,
        greatest(coalesce(v_product.cost, 0), 0),
        coalesce(v_product.stock, 0), coalesce(v_product.stock, 0),
        v_previous_committed, v_new_committed, 'reserved',
        p_actor_device_id, p_actor_staff_user_id, p_actor_key, p_actor_name,
        v_operation_key,
        jsonb_strip_nulls(jsonb_build_object(
          'phase', 'cloud_layaways_server_contract_r1',
          'stock_source', 'product',
          'variant_attributes', v_item.payload->'variant_attributes',
          'attributes', v_item.payload->'attributes'
        ))
      ) returning * into v_reservation;

      perform private.record_pos_sync_event(
        p_license_id, 'product', v_product_id, 'update', p_actor_device_id,
        p_actor_staff_user_id, v_operation_key,
        jsonb_build_object('reason', 'layaway_stock_reserved', 'layaway_id', p_layaway_id, 'reservation_id', v_reservation.id),
        v_product.server_version
      );
    end if;
  end loop;

  return (
    select coalesce(jsonb_agg(private.pos_layaway_reservation_to_jsonb(r) order by r.item_index), '[]'::jsonb)
      from public.pos_layaway_inventory_reservations r
     where r.license_id = p_license_id and r.layaway_id = p_layaway_id
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.resolve_cash_actor_key(p_context jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor_type text := private.resolve_pos_actor_type(p_context);
  v_actor_id uuid := nullif(p_context->>'actor_id', '')::uuid;
  v_staff_user_id uuid := nullif(p_context->>'staff_user_id', '')::uuid;
  v_admin_user_id uuid := nullif(p_context->>'admin_user_id', '')::uuid;
begin
  if v_actor_type = 'staff' then
    v_actor_id := coalesce(v_actor_id, v_staff_user_id);
    if v_actor_id is null then raise exception 'STAFF_USER_REQUIRED_FOR_CASH' using errcode = 'P0001'; end if;
    return 'staff:' || v_actor_id::text;
  end if;
  v_actor_id := coalesce(v_actor_id, v_admin_user_id);
  if v_actor_id is null then raise exception 'ADMIN_SESSION_REQUIRED' using errcode = 'P0001'; end if;
  return 'admin:' || v_actor_id::text;
end;
$function$
CREATE OR REPLACE FUNCTION private.resolve_cash_actor_name(p_context jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare v_actor_type text := private.resolve_pos_actor_type(p_context); v_name text;
begin
  if v_actor_type = 'staff' then
    v_name := nullif(btrim(coalesce(p_context->'staff_user'->>'display_name', p_context->'staff_user'->>'username', 'Staff')), '');
    return coalesce(v_name, 'Staff');
  end if;
  v_name := nullif(btrim(coalesce(p_context->'admin_user'->>'display_name', p_context->'admin_user'->>'username', 'Administrador')), '');
  return coalesce(v_name, 'Administrador');
end;
$function$
CREATE OR REPLACE FUNCTION private.resolve_cash_station_for_device(p_license_id uuid, p_device_id uuid, p_create_default boolean DEFAULT false)
 RETURNS pos_cash_stations
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_station public.pos_cash_stations;
  v_active_bindings integer;
  v_station_id text := 'cash_station_device_' || p_device_id::text;
  v_station_key text := 'device_default:' || p_device_id::text;
begin
  if p_license_id is null or p_device_id is null then
    raise exception 'CASH_STATION_UNRESOLVED' using errcode = 'P0001';
  end if;

  select count(*) into v_active_bindings
    from public.pos_cash_station_bindings b
   where b.license_id = p_license_id
     and b.device_id = p_device_id
     and b.status = 'active';

  if v_active_bindings > 1 then
    raise exception 'CASH_STATION_BINDING_AMBIGUOUS' using errcode = 'P0001';
  end if;

  select s.* into v_station
    from public.pos_cash_station_bindings b
    join public.pos_cash_stations s
      on s.license_id = b.license_id
     and s.id = b.cash_station_id
   where b.license_id = p_license_id
     and b.device_id = p_device_id
     and b.status = 'active'
   limit 1;

  if v_station.id is not null then
    if v_station.status <> 'active' then
      raise exception 'CASH_STATION_BLOCKED' using errcode = 'P0001';
    end if;
    return v_station;
  end if;

  if not p_create_default then
    raise exception 'CASH_STATION_UNRESOLVED' using errcode = 'P0001';
  end if;

  insert into public.pos_cash_stations (id, license_id, station_key, binding_mode, metadata)
  values (
    v_station_id,
    p_license_id,
    v_station_key,
    'device_default',
    jsonb_build_object('identity_source', 'deterministic-device-bound', 'bound_device_id', p_device_id)
  )
  on conflict (license_id, station_key) do nothing;

  insert into public.pos_cash_station_bindings (
    license_id, cash_station_id, device_id, binding_mode, status, metadata
  ) values (
    p_license_id,
    v_station_id,
    p_device_id,
    'device_default',
    'active',
    jsonb_build_object('identity_source', 'deterministic-device-bound')
  )
  on conflict do nothing;

  select * into v_station
    from public.pos_cash_stations s
   where s.license_id = p_license_id
     and s.station_key = v_station_key
   limit 1;

  if v_station.id is null or v_station.status <> 'active' then
    raise exception 'CASH_STATION_UNRESOLVED' using errcode = 'P0001';
  end if;
  return v_station;
end;
$function$
CREATE OR REPLACE FUNCTION private.resolve_financial_cash_station_v1(p_license_id uuid, p_device_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare v_station_id text;
begin
  select b.cash_station_id into v_station_id from public.pos_cash_station_bindings b
  join public.pos_cash_stations s on s.license_id=b.license_id and s.id=b.cash_station_id
  where b.license_id=p_license_id and b.device_id=p_device_id and b.status='active' and s.status='active';
  if v_station_id is null then raise exception 'CASH_STATION_UNRESOLVED' using errcode='P0001'; end if;
  return v_station_id;
end;
$function$
CREATE OR REPLACE FUNCTION private.resolve_pos_actor_type(p_context jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_actor_type text := nullif(p_context->>'actor_type', '');
  v_device_mode text := nullif(p_context->>'device_mode', '');
  v_legacy_role text := nullif(p_context->>'device_role', '');
begin
  if v_actor_type in ('admin', 'staff') then
    return v_actor_type;
  end if;

  if v_device_mode = 'shared' then
    raise exception 'ACTOR_SESSION_REQUIRED' using errcode = 'P0001';
  end if;

  if v_legacy_role in ('admin', 'staff') then
    return v_legacy_role;
  end if;

  raise exception 'ACTOR_SESSION_REQUIRED' using errcode = 'P0001';
end;
$function$
CREATE OR REPLACE FUNCTION private.resolve_sale_inventory_allocations(p_license_id uuid, p_items jsonb, p_sale_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
AS $function$
declare
  v_expanded_items jsonb;
  v_response jsonb;
begin
  v_expanded_items := private.rest_inv5_expand_sale_inventory_items(p_license_id, p_items, p_sale_id);
  v_response := private.resolve_sale_inventory_allocations_direct_rest_inv5(p_license_id, v_expanded_items, p_sale_id);
  return private.rest_inv5_enrich_inventory_allocations(v_expanded_items, v_response);
end;
$function$
CREATE OR REPLACE FUNCTION private.resolve_sale_inventory_allocations_direct_rest_inv5(p_license_id uuid, p_items jsonb, p_sale_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_item record;
  v_item_norm jsonb;
  v_batch_payload record;
  v_product public.pos_products;
  v_batch public.pos_product_batches;
  v_product_id text;
  v_item_id text;
  v_product_name text;
  v_batch_id text;
  v_quantity numeric;
  v_unit_cost numeric;
  v_batches_used jsonb;
  v_requested_batch_qty numeric;
  v_allocated numeric;
  v_remaining numeric;
  v_available numeric;
  v_available_total numeric;
  v_expired_available_total numeric;
  v_parent_available numeric;
  v_uses_batches boolean;
  v_strict_expiry boolean;
  v_shelf_life_blocked boolean;
  v_response jsonb;
  v_allocations jsonb := '[]'::jsonb;
  v_required_count integer := 0;
begin
  if p_license_id is null then
    raise exception 'LICENSE_ID_REQUIRED_FOR_INVENTORY' using errcode = 'P0001';
  end if;

  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then
    raise exception 'SALE_ITEMS_PAYLOAD_INVALID' using errcode = 'P0001';
  end if;

  for v_item in
    select value as payload, ordinality
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) with ordinality
  loop
    v_item_norm := private.normalize_sale_inventory_item(v_item.payload, v_item.ordinality);
    v_item_id := coalesce(private.pos_sale_jsonb_text(v_item.payload, array['id']), p_sale_id || ':item:' || v_item.ordinality::text);
    v_product_id := nullif(v_item_norm->>'product_id', '');
    v_product_name := coalesce(v_item_norm->>'product_name', 'Producto');
    v_batch_id := nullif(v_item_norm->>'batch_id', '');
    v_quantity := (v_item_norm->>'quantity')::numeric;
    v_unit_cost := nullif(v_item_norm->>'unit_cost', '')::numeric;
    v_batches_used := coalesce(v_item_norm->'batches_used', '[]'::jsonb);

    if v_product_id is null then
      continue;
    end if;

    select * into v_product
    from public.pos_products p
    where p.license_id = p_license_id
      and p.id = v_product_id
    for update;

    if v_product.id is null then
      return jsonb_build_object('ok', false, 'success', false, 'code', 'PRODUCT_NOT_SYNCED_FOR_CLOUD_SALE', 'message', 'Este producto aun no esta listo para venta cloud.', 'product_id', v_product_id, 'product_name', v_product_name, 'requested_quantity', v_quantity, 'available_quantity', 0);
    end if;

    v_product_name := coalesce(v_product.name, v_product_name);
    v_strict_expiry := coalesce(v_product.expiration_mode, 'NONE') = 'STRICT';
    v_shelf_life_blocked := coalesce(v_product.expiration_mode, 'NONE') = 'SHELF_LIFE' and private.pos_cad6_shelf_life_expired_for_sale(v_product);
    v_parent_available := greatest(coalesce(v_product.stock, 0) - coalesce(v_product.committed_stock, 0), 0);

    if v_product.deleted_at is not null or v_product.is_active is not true then
      return jsonb_build_object('ok', false, 'success', false, 'code', 'CLOUD_PRODUCT_NOT_AVAILABLE', 'message', 'El producto no esta activo en la nube.', 'product_id', v_product_id, 'product_name', v_product_name, 'requested_quantity', v_quantity, 'available_quantity', 0);
    end if;

    if v_shelf_life_blocked then
      v_response := jsonb_build_object('ok', false, 'success', false, 'code', 'SHELF_LIFE_EXPIRED_BLOCKED', 'message', 'La vida útil de este producto ya venció. Revisa Caducidad/Merma antes de venderlo.', 'product_id', v_product_id, 'product_name', v_product_name, 'requested_quantity', v_quantity, 'available_quantity', v_parent_available, 'expiration_mode', v_product.expiration_mode, 'shelf_life_target_date', private.pos_cad6_product_shelf_life_target_date(v_product), 'source', 'resolve_sale_inventory_allocations');
      return private.audit_pos_inventory_block(p_license_id, p_sale_id, 'sale.shelf_life_expired_blocked', v_response);
    end if;

    if v_product.track_stock is not true then
      continue;
    end if;

    v_required_count := v_required_count + 1;
    v_uses_batches := private.product_uses_batches(v_product) or v_strict_expiry or v_batch_id is not null or jsonb_array_length(v_batches_used) > 0;

    if not v_uses_batches then
      v_available := v_parent_available;
      if v_available < v_quantity then
        return jsonb_build_object('ok', false, 'success', false, 'code', 'INSUFFICIENT_CLOUD_STOCK', 'message', 'No hay suficiente stock en la nube para completar esta venta.', 'product_id', v_product_id, 'product_name', v_product_name, 'requested_quantity', v_quantity, 'available_quantity', v_available);
      end if;

      v_allocations := v_allocations || jsonb_build_array(jsonb_build_object('sale_id', p_sale_id, 'sale_item_id', v_item_id, 'product_id', v_product_id, 'product_name', v_product_name, 'batch_id', null, 'quantity', v_quantity, 'unit_cost', coalesce(v_unit_cost, v_product.cost), 'stock_source', 'product'));
    else
      v_allocated := 0;
      v_available_total := 0;
      v_expired_available_total := 0;

      if jsonb_array_length(v_batches_used) > 0 then
        for v_batch_payload in
          select value as payload, ordinality
          from jsonb_array_elements(v_batches_used) with ordinality
        loop
          v_batch_id := coalesce(private.pos_sale_jsonb_text(v_batch_payload.payload, array['batch_id','batchId','id']), null);
          v_requested_batch_qty := private.pos_sale_jsonb_numeric(v_batch_payload.payload, array['quantity','qty','usedQuantity','used_quantity'], 0);

          if v_batch_id is null or v_requested_batch_qty <= 0 then
            continue;
          end if;

          select * into v_batch
          from public.pos_product_batches b
          where b.license_id = p_license_id
            and b.product_id = v_product_id
            and b.id = v_batch_id
            and b.deleted_at is null
            and b.is_active is true
          for update;

          if v_batch.id is null then
            return jsonb_build_object('ok', false, 'success', false, 'code', 'CLOUD_BATCH_NOT_AVAILABLE', 'message', 'El lote no esta activo en la nube.', 'product_id', v_product_id, 'product_name', v_product_name, 'batch_id', v_batch_id, 'requested_quantity', v_requested_batch_qty, 'available_quantity', 0);
          end if;

          v_available := greatest(coalesce(v_batch.stock, 0) - coalesce(v_batch.committed_stock, 0), 0);

          if v_strict_expiry and (v_batch.expiry_date is null or private.is_pos_batch_expired_for_sale(v_batch.expiry_date)) then
            v_response := jsonb_build_object('ok', false, 'success', false, 'code', case when v_batch.expiry_date is null then 'NO_CURRENT_BATCH_FOR_STRICT_PRODUCT' else 'STRICT_EXPIRED_BATCH_BLOCKED' end, 'message', 'Este producto no tiene lote vigente disponible. Revisa Caducidad/Merma antes de venderlo.', 'product_id', v_product_id, 'product_name', v_product_name, 'batch_id', v_batch_id, 'batch_sku', v_batch.sku, 'expiry_date', v_batch.expiry_date::date, 'requested_quantity', v_requested_batch_qty, 'available_quantity', 0, 'expired_available_quantity', v_available, 'source', 'resolve_sale_inventory_allocations');
            return private.audit_pos_inventory_block(p_license_id, p_sale_id, 'sale.strict_batch_blocked', v_response);
          end if;

          v_available_total := v_available_total + v_available;

          if v_available < v_requested_batch_qty then
            return jsonb_build_object('ok', false, 'success', false, 'code', 'INSUFFICIENT_CLOUD_STOCK', 'message', 'No hay suficiente stock en la nube para completar esta venta.', 'product_id', v_product_id, 'product_name', v_product_name, 'batch_id', v_batch_id, 'requested_quantity', v_requested_batch_qty, 'available_quantity', v_available);
          end if;

          v_allocated := v_allocated + v_requested_batch_qty;
          v_allocations := v_allocations || jsonb_build_array(jsonb_build_object('sale_id', p_sale_id, 'sale_item_id', v_item_id, 'product_id', v_product_id, 'product_name', v_product_name, 'batch_id', v_batch_id, 'batch_sku', v_batch.sku, 'batch_expiry_date', v_batch.expiry_date::date, 'quantity', v_requested_batch_qty, 'unit_cost', coalesce(v_unit_cost, v_batch.cost, v_product.cost), 'stock_source', 'batch'));
        end loop;

        if abs(v_allocated - v_quantity) > 0.00001 then
          return jsonb_build_object('ok', false, 'success', false, 'code', 'CLOUD_BATCH_ALLOCATION_MISMATCH', 'message', 'Las asignaciones de lote no cuadran con la cantidad vendida.', 'product_id', v_product_id, 'product_name', v_product_name, 'requested_quantity', v_quantity, 'available_quantity', v_available_total);
        end if;
      elsif v_batch_id is not null then
        select * into v_batch
        from public.pos_product_batches b
        where b.license_id = p_license_id
          and b.product_id = v_product_id
          and b.id = v_batch_id
          and b.deleted_at is null
          and b.is_active is true
        for update;

        if v_batch.id is null then
          return jsonb_build_object('ok', false, 'success', false, 'code', 'CLOUD_BATCH_NOT_AVAILABLE', 'message', 'El lote no esta activo en la nube.', 'product_id', v_product_id, 'product_name', v_product_name, 'batch_id', v_batch_id, 'requested_quantity', v_quantity, 'available_quantity', 0);
        end if;

        v_available := greatest(coalesce(v_batch.stock, 0) - coalesce(v_batch.committed_stock, 0), 0);

        if v_strict_expiry and (v_batch.expiry_date is null or private.is_pos_batch_expired_for_sale(v_batch.expiry_date)) then
          v_response := jsonb_build_object('ok', false, 'success', false, 'code', case when v_batch.expiry_date is null then 'NO_CURRENT_BATCH_FOR_STRICT_PRODUCT' else 'STRICT_EXPIRED_BATCH_BLOCKED' end, 'message', 'Este producto no tiene lote vigente disponible. Revisa Caducidad/Merma antes de venderlo.', 'product_id', v_product_id, 'product_name', v_product_name, 'batch_id', v_batch_id, 'batch_sku', v_batch.sku, 'expiry_date', v_batch.expiry_date::date, 'requested_quantity', v_quantity, 'available_quantity', 0, 'expired_available_quantity', v_available, 'source', 'resolve_sale_inventory_allocations');
          return private.audit_pos_inventory_block(p_license_id, p_sale_id, 'sale.strict_batch_blocked', v_response);
        end if;

        if v_available < v_quantity then
          return jsonb_build_object('ok', false, 'success', false, 'code', 'INSUFFICIENT_CLOUD_STOCK', 'message', 'No hay suficiente stock en la nube para completar esta venta.', 'product_id', v_product_id, 'product_name', v_product_name, 'batch_id', v_batch_id, 'requested_quantity', v_quantity, 'available_quantity', v_available);
        end if;

        v_allocations := v_allocations || jsonb_build_array(jsonb_build_object('sale_id', p_sale_id, 'sale_item_id', v_item_id, 'product_id', v_product_id, 'product_name', v_product_name, 'batch_id', v_batch_id, 'batch_sku', v_batch.sku, 'batch_expiry_date', v_batch.expiry_date::date, 'quantity', v_quantity, 'unit_cost', coalesce(v_unit_cost, v_batch.cost, v_product.cost), 'stock_source', 'batch'));
      else
        v_remaining := v_quantity;
        v_available_total := 0;
        v_expired_available_total := 0;

        select coalesce(sum(greatest(coalesce(b.stock, 0) - coalesce(b.committed_stock, 0), 0)), 0)
        into v_expired_available_total
        from public.pos_product_batches b
        where b.license_id = p_license_id
          and b.product_id = v_product_id
          and b.deleted_at is null
          and b.is_active is true
          and b.track_stock is true
          and greatest(coalesce(b.stock, 0) - coalesce(b.committed_stock, 0), 0) > 0
          and ((v_strict_expiry and (b.expiry_date is null or private.is_pos_batch_expired_for_sale(b.expiry_date))) or (v_strict_expiry is not true and private.is_pos_batch_expired_for_sale(b.expiry_date)));

        for v_batch in
          select *
          from public.pos_product_batches b
          where b.license_id = p_license_id
            and b.product_id = v_product_id
            and b.deleted_at is null
            and b.is_active is true
            and b.track_stock is true
            and greatest(coalesce(b.stock, 0) - coalesce(b.committed_stock, 0), 0) > 0
            and (v_strict_expiry is not true or (b.expiry_date is not null and private.is_pos_batch_expired_for_sale(b.expiry_date) is not true))
          order by b.expiry_date asc nulls last, b.created_at asc, b.id asc
          for update
        loop
          v_available := greatest(coalesce(v_batch.stock, 0) - coalesce(v_batch.committed_stock, 0), 0);
          v_available_total := v_available_total + v_available;

          if v_remaining > 0 then
            v_requested_batch_qty := least(v_remaining, v_available);
            v_remaining := v_remaining - v_requested_batch_qty;
            v_allocations := v_allocations || jsonb_build_array(jsonb_build_object('sale_id', p_sale_id, 'sale_item_id', v_item_id, 'product_id', v_product_id, 'product_name', v_product_name, 'batch_id', v_batch.id, 'batch_sku', v_batch.sku, 'batch_expiry_date', v_batch.expiry_date::date, 'quantity', v_requested_batch_qty, 'unit_cost', coalesce(v_unit_cost, v_batch.cost, v_product.cost), 'stock_source', 'batch', 'fefo', true));
          end if;
        end loop;

        if v_remaining > 0.00001 then
          if v_uses_batches and v_parent_available > 0 and v_available_total <= 0 then
            v_response := jsonb_build_object('ok', false, 'success', false, 'code', 'PRODUCT_STOCK_WITHOUT_BATCH', 'message', 'Este producto no tiene lote vigente disponible. Revisa Caducidad/Merma antes de venderlo.', 'product_id', v_product_id, 'product_name', v_product_name, 'requested_quantity', v_quantity, 'available_quantity', v_available_total, 'parent_available_quantity', v_parent_available, 'expired_available_quantity', v_expired_available_total, 'source', 'resolve_sale_inventory_allocations');
            return private.audit_pos_inventory_block(p_license_id, p_sale_id, 'sale.product_stock_without_batch', v_response);
          end if;

          if v_strict_expiry then
            v_response := jsonb_build_object('ok', false, 'success', false, 'code', case when v_expired_available_total > 0 then 'STRICT_EXPIRED_BATCH_BLOCKED' else 'NO_CURRENT_BATCH_FOR_STRICT_PRODUCT' end, 'message', 'Este producto no tiene lote vigente disponible. Revisa Caducidad/Merma antes de venderlo.', 'product_id', v_product_id, 'product_name', v_product_name, 'requested_quantity', v_quantity, 'available_quantity', v_available_total, 'expired_available_quantity', v_expired_available_total, 'source', 'resolve_sale_inventory_allocations');
            return private.audit_pos_inventory_block(p_license_id, p_sale_id, 'sale.no_current_batch_for_strict_product', v_response);
          end if;

          return jsonb_build_object('ok', false, 'success', false, 'code', 'INSUFFICIENT_CLOUD_STOCK', 'message', 'No hay suficiente stock en la nube para completar esta venta.', 'product_id', v_product_id, 'product_name', v_product_name, 'requested_quantity', v_quantity, 'available_quantity', v_available_total);
        end if;
      end if;
    end if;
  end loop;

  return jsonb_build_object('ok', true, 'success', true, 'inventory_effect_status', case when v_required_count > 0 then 'applied' else 'not_required' end, 'allocations', v_allocations);
end;
$function$
CREATE OR REPLACE FUNCTION private.rest_inv5_build_sale_inventory_requirements(p_sale_id text, p_item_norm jsonb, p_source_product pos_products)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_requirements jsonb := '[]'::jsonb;
  v_item_id text := nullif(p_item_norm->>'item_id', '');
  v_item_quantity numeric := coalesce(nullif(p_item_norm->>'quantity', '')::numeric, 0);
  v_recipe jsonb := coalesce(p_source_product.recipe, '[]'::jsonb);
  v_ingredient record;
  v_modifier record;
  v_target_id text;
  v_component_quantity numeric;
  v_needed_quantity numeric;
  v_component_unit text;
  v_modifier_id text;
  v_modifier_name text;
begin
  if v_item_quantity <= 0 then
    return '[]'::jsonb;
  end if;

  if jsonb_typeof(v_recipe) <> 'array' then
    v_recipe := '[]'::jsonb;
  end if;

  if jsonb_array_length(v_recipe) > 0 then
    for v_ingredient in select value as payload, ordinality from jsonb_array_elements(v_recipe) with ordinality loop
      v_target_id := private.pos_sale_jsonb_text(v_ingredient.payload, array['ingredientId','ingredient_id','productId','product_id','targetId','id'], null);
      v_component_quantity := private.pos_sale_jsonb_numeric(v_ingredient.payload, array['quantity','ingredientQuantity','ingredient_quantity','qty'], 0);
      v_component_unit := private.pos_sale_jsonb_text(v_ingredient.payload, array['unit','ingredientUnit','ingredient_unit'], null);
      v_needed_quantity := v_component_quantity * v_item_quantity;

      if v_target_id is not null and v_needed_quantity > 0 then
        v_requirements := v_requirements || jsonb_build_array(jsonb_build_object(
          'sale_id', p_sale_id,
          'sale_item_id', v_item_id,
          'source', 'recipe',
          'source_product_id', p_source_product.id,
          'source_product_name', p_source_product.name,
          'product_id', v_target_id,
          'quantity', v_needed_quantity,
          'component_quantity', v_component_quantity,
          'component_unit', v_component_unit,
          'component_key', 'recipe:' || coalesce(v_target_id, 'unknown') || ':' || v_ingredient.ordinality::text
        ));
      end if;
    end loop;
  elsif p_source_product.track_stock is true then
    v_requirements := v_requirements || jsonb_build_array(jsonb_build_object(
      'sale_id', p_sale_id,
      'sale_item_id', v_item_id,
      'source', 'product',
      'source_product_id', p_source_product.id,
      'source_product_name', p_source_product.name,
      'product_id', p_source_product.id,
      'quantity', v_item_quantity,
      'component_quantity', v_item_quantity,
      'component_unit', null,
      'component_key', 'product:' || p_source_product.id
    ));
  end if;

  for v_modifier in select value as payload, ordinality from jsonb_array_elements(coalesce(p_item_norm->'selected_modifiers', '[]'::jsonb)) with ordinality loop
    if private.rest_inv5_modifier_tracks_inventory(v_modifier.payload) is not true then
      continue;
    end if;

    v_target_id := private.pos_sale_jsonb_text(v_modifier.payload, array['ingredientId','ingredient_id'], null);
    v_component_quantity := private.rest_inv5_modifier_inventory_quantity(v_modifier.payload);
    v_needed_quantity := v_component_quantity * v_item_quantity;
    v_component_unit := private.pos_sale_jsonb_text(v_modifier.payload, array['ingredientUnit','ingredient_unit','unit'], null);
    v_modifier_id := coalesce(private.pos_sale_jsonb_text(v_modifier.payload, array['id','modifierId','modifier_id','optionId','option_id'], null), 'modifier:' || v_modifier.ordinality::text);
    v_modifier_name := private.pos_sale_jsonb_text(v_modifier.payload, array['name','label','optionName','option_name'], null);

    if v_target_id is not null and v_needed_quantity > 0 then
      v_requirements := v_requirements || jsonb_build_array(jsonb_build_object(
        'sale_id', p_sale_id,
        'sale_item_id', v_item_id,
        'source', 'modifier',
        'source_product_id', p_source_product.id,
        'source_product_name', p_source_product.name,
        'product_id', v_target_id,
        'quantity', v_needed_quantity,
        'component_quantity', v_component_quantity,
        'component_unit', v_component_unit,
        'component_key', 'modifier:' || v_modifier_id || ':' || coalesce(v_target_id, 'unknown') || ':' || v_modifier.ordinality::text,
        'modifier_id', v_modifier_id,
        'modifier_name', v_modifier_name
      ));
    end if;
  end loop;

  return v_requirements;
end;
$function$
CREATE OR REPLACE FUNCTION private.rest_inv5_enrich_inventory_allocations(p_expanded_items jsonb, p_response jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
declare
  v_alloc record;
  v_expanded_item jsonb;
  v_enriched jsonb := '[]'::jsonb;
  v_synthetic_id text;
  v_original_id text;
  v_meta jsonb;
begin
  if coalesce((p_response->>'ok')::boolean, false) is not true then
    return p_response;
  end if;

  for v_alloc in
    select value as payload, ordinality
    from jsonb_array_elements(coalesce(p_response->'allocations', '[]'::jsonb)) with ordinality
  loop
    v_synthetic_id := nullif(v_alloc.payload->>'sale_item_id', '');
    v_expanded_item := null;

    select e.value into v_expanded_item
    from jsonb_array_elements(coalesce(p_expanded_items, '[]'::jsonb)) e(value)
    where e.value->>'id' = v_synthetic_id
    limit 1;

    v_meta := coalesce(v_expanded_item->'metadata', '{}'::jsonb);
    v_original_id := coalesce(nullif(v_meta->>'originalSaleItemId', ''), v_synthetic_id);

    v_enriched := v_enriched || jsonb_build_array(
      (v_alloc.payload - 'sale_item_id') || jsonb_build_object(
        'sale_item_id', v_original_id,
        'inventory_source', coalesce(nullif(v_meta->>'inventorySource', ''), 'product'),
        'source_product_id', nullif(v_meta->>'sourceProductId', ''),
        'source_product_name', nullif(v_meta->>'sourceProductName', ''),
        'component_key', nullif(v_meta->>'componentKey', ''),
        'component_quantity', nullif(v_meta->>'componentQuantity', '')::numeric,
        'component_unit', nullif(v_meta->>'componentUnit', ''),
        'modifier_id', nullif(v_meta->>'modifierId', ''),
        'modifier_name', nullif(v_meta->>'modifierName', '')
      )
    );
  end loop;

  return p_response || jsonb_build_object(
    'allocations', v_enriched,
    'inventory_effect_status', case when jsonb_array_length(v_enriched) > 0 then 'applied' else 'not_required' end
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.rest_inv5_expand_sale_inventory_items(p_license_id uuid, p_items jsonb, p_sale_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  v_item record;
  v_req record;
  v_item_norm jsonb;
  v_source_product public.pos_products;
  v_requirements jsonb;
  v_expanded jsonb := '[]'::jsonb;
  v_original_id text;
  v_synthetic_id text;
  v_source text;
  v_metadata jsonb;
begin
  if jsonb_typeof(coalesce(p_items, '[]'::jsonb)) <> 'array' then
    raise exception 'SALE_ITEMS_PAYLOAD_INVALID' using errcode = 'P0001';
  end if;

  for v_item in
    select value as payload, ordinality
    from jsonb_array_elements(coalesce(p_items, '[]'::jsonb)) with ordinality
  loop
    v_item_norm := private.normalize_sale_inventory_item(v_item.payload, v_item.ordinality);
    v_original_id := coalesce(private.pos_sale_jsonb_text(v_item.payload, array['id','lineId','cartLineId'], null), p_sale_id || ':item:' || v_item.ordinality::text);

    select * into v_source_product
    from public.pos_products p
    where p.license_id = p_license_id
      and p.id = nullif(v_item_norm->>'product_id', '');

    if v_source_product.id is null or v_source_product.deleted_at is not null or v_source_product.is_active is not true then
      v_expanded := v_expanded || jsonb_build_array(v_item.payload);
      continue;
    end if;

    v_requirements := private.rest_inv5_build_sale_inventory_requirements(p_sale_id, v_item_norm, v_source_product);

    for v_req in
      select value as payload, ordinality
      from jsonb_array_elements(coalesce(v_requirements, '[]'::jsonb)) with ordinality
    loop
      if nullif(v_req.payload->>'product_id', '') is null or coalesce(nullif(v_req.payload->>'quantity', '')::numeric, 0) <= 0 then
        continue;
      end if;

      v_source := coalesce(v_req.payload->>'source', 'product');
      v_synthetic_id := v_original_id || '::rest_inv5::' || md5(v_req.payload::text || ':' || v_req.ordinality::text);
      v_metadata := coalesce(v_item.payload->'metadata', '{}'::jsonb) || jsonb_build_object(
        'originalSaleItemId', v_original_id,
        'inventorySource', v_source,
        'sourceProductId', v_req.payload->>'source_product_id',
        'sourceProductName', v_req.payload->>'source_product_name',
        'componentKey', v_req.payload->>'component_key',
        'componentQuantity', nullif(v_req.payload->>'component_quantity', '')::numeric,
        'componentUnit', nullif(v_req.payload->>'component_unit', ''),
        'modifierId', nullif(v_req.payload->>'modifier_id', ''),
        'modifierName', nullif(v_req.payload->>'modifier_name', ''),
        'restaurantInventoryPhase', 'rest_inv_5_cloud_restaurant_inventory'
      );

      v_expanded := v_expanded || jsonb_build_array(jsonb_build_object(
        'id', v_synthetic_id,
        'product_id', v_req.payload->>'product_id',
        'product_name', coalesce(v_req.payload->>'source_product_name', v_item_norm->>'product_name', 'Producto'),
        'quantity', nullif(v_req.payload->>'quantity', '')::numeric,
        'unit_cost', nullif(v_item_norm->>'unit_cost', '')::numeric,
        'batch_id', case when v_source = 'product' then nullif(v_item_norm->>'batch_id', '') else null end,
        'batches_used', case when v_source = 'product' then coalesce(v_item_norm->'batches_used', '[]'::jsonb) else '[]'::jsonb end,
        'metadata', v_metadata
      ));
    end loop;
  end loop;

  return v_expanded;
end;
$function$
CREATE OR REPLACE FUNCTION private.rest_inv5_modifier_inventory_quantity(p_modifier jsonb)
 RETURNS numeric
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_has_explicit boolean;
  v_quantity numeric;
begin
  if p_modifier is null or jsonb_typeof(p_modifier) <> 'object' then
    return null;
  end if;

  v_has_explicit := (p_modifier ? 'ingredientQuantity') or (p_modifier ? 'ingredient_quantity');

  if v_has_explicit then
    v_quantity := private.pos_sale_jsonb_numeric(p_modifier, array['ingredientQuantity','ingredient_quantity'], null);
    if v_quantity is not null and v_quantity > 0 then
      return v_quantity;
    end if;
    return null;
  end if;

  if p_modifier ? 'quantity' then
    v_quantity := private.pos_sale_jsonb_numeric(p_modifier, array['quantity'], null);
    if v_quantity is not null and v_quantity > 0 then
      return v_quantity;
    end if;
  end if;

  return null;
end;
$function$
CREATE OR REPLACE FUNCTION private.rest_inv5_modifier_tracks_inventory(p_modifier jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v_ingredient_id text;
  v_quantity numeric;
begin
  if p_modifier is null or jsonb_typeof(p_modifier) <> 'object' then
    return false;
  end if;

  v_ingredient_id := private.pos_sale_jsonb_text(
    p_modifier,
    array['ingredientId','ingredient_id'],
    null
  );
  v_quantity := private.rest_inv5_modifier_inventory_quantity(p_modifier);

  return v_ingredient_id is not null
    and v_quantity is not null
    and v_quantity > 0;
end;
$function$
CREATE OR REPLACE FUNCTION private.sanitize_financial_response_idempotency_v1(p_value jsonb, p_external_idempotency_key text, p_internal_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare v_key text; v_value jsonb; v_result jsonb := '{}'::jsonb;
begin
  if jsonb_typeof(p_value) = 'array' then
    return coalesce((select jsonb_agg(private.sanitize_financial_response_idempotency_v1(value, p_external_idempotency_key, p_internal_idempotency_key) order by ordinality) from jsonb_array_elements(p_value) with ordinality), '[]'::jsonb);
  end if;
  if jsonb_typeof(p_value) <> 'object' then return p_value; end if;
  for v_key, v_value in select key, value from jsonb_each(p_value) loop
    if lower(v_key) in ('idempotency_key','last_idempotency_key')
       and v_value = to_jsonb(p_internal_idempotency_key) then
      v_result := v_result || jsonb_build_object(v_key, p_external_idempotency_key);
    else
      v_result := v_result || jsonb_build_object(v_key, private.sanitize_financial_response_idempotency_v1(v_value, p_external_idempotency_key, p_internal_idempotency_key));
    end if;
  end loop;
  return v_result;
end;
$function$
CREATE OR REPLACE FUNCTION private.touch_license_staff_session_seen(p_session_id uuid, p_min_interval interval DEFAULT '00:00:30'::interval)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if p_session_id is null then
    return;
  end if;

  update public.license_staff_sessions ss
  set last_seen_at = now()
  where ss.id in (
    select locked_session.id
    from public.license_staff_sessions locked_session
    where locked_session.id = p_session_id
      and (
        locked_session.last_seen_at is null
        or locked_session.last_seen_at < now() - coalesce(p_min_interval, '30 seconds'::interval)
      )
    for update skip locked
  );
end;
$function$
CREATE OR REPLACE FUNCTION private.validate_customer_payment_allocations(p_allocations jsonb, p_amount numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO ''
AS $function$
declare
  v_item jsonb;
  v_total numeric := 0;
  v_amount numeric;
  v_result jsonb := '[]'::jsonb;
begin
  if p_allocations is null then
    return '[]'::jsonb;
  end if;

  if jsonb_typeof(p_allocations) <> 'array' then
    raise exception 'CUSTOMER_PAYMENT_ALLOCATIONS_INVALID' using errcode = 'P0001';
  end if;

  for v_item in select value from jsonb_array_elements(p_allocations)
  loop
    v_amount := coalesce((v_item->>'amount_applied')::numeric, (v_item->>'amountApplied')::numeric, 0);
    if v_amount < 0 then
      raise exception 'CUSTOMER_PAYMENT_ALLOCATION_NEGATIVE' using errcode = 'P0001';
    end if;
    if v_amount > 0 then
      v_total := v_total + v_amount;
      v_result := v_result || jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
        'sale_id', coalesce(v_item->>'sale_id', v_item->>'saleId'),
        'amount_applied', v_amount,
        'previous_sale_balance', nullif(coalesce(v_item->>'previous_sale_balance', v_item->>'previousSaleBalance'), '')::numeric,
        'new_sale_balance', nullif(coalesce(v_item->>'new_sale_balance', v_item->>'newSaleBalance'), '')::numeric,
        'metadata', coalesce(v_item->'metadata', '{}'::jsonb)
      )));
    end if;
  end loop;

  if v_total > p_amount then
    raise exception 'CUSTOMER_PAYMENT_ALLOCATIONS_EXCEED_AMOUNT' using errcode = 'P0001';
  end if;

  return v_result;
end;
$function$
CREATE OR REPLACE FUNCTION private.validate_pos_sync_context(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_license record;
  v_device record;
  v_features jsonb;
  v_actor_token text := nullif(btrim(coalesce(p_staff_session_token, '')), '');
  v_admin_auth jsonb := null;
  v_admin_valid boolean := false;
  v_staff_session record;
  v_staff_valid boolean := false;
  v_actor_type text;
  v_actor_id uuid;
  v_actor_session_id uuid;
  v_actor_permissions jsonb := '{}'::jsonb;
  v_staff_payload jsonb := null;
  v_admin_payload jsonb := null;
begin
  select
    l.id,
    l.license_key,
    entitlement.plan_code,
    entitlement.plan_name,
    entitlement.expires_at,
    entitlement.grace_period_ends,
    entitlement.lifecycle_state,
    entitlement.is_entitled,
    entitlement.is_in_grace,
    entitlement.effective_features
  into v_license
  from public.licenses l
  cross join lateral private.license_entitlement_state_v1(l.id) entitlement
  where l.license_key = p_license_key
  limit 1;

  if v_license.id is null then
    raise exception 'LICENSE_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_license.lifecycle_state = 'administratively_blocked' then
    raise exception 'LICENSE_NOT_ACTIVE' using errcode = 'P0001';
  end if;
  if v_license.is_entitled is not true then
    raise exception 'LICENSE_EXPIRED' using errcode = 'P0001';
  end if;

  select d.id, d.license_id, d.device_fingerprint, d.security_token,
         d.previous_security_token, d.is_active, d.device_mode,
         d.device_role as legacy_device_role,
         d.staff_user_id as legacy_staff_user_id, d.realtime_topic
  into v_device
  from public.license_devices d
  where d.license_id = v_license.id
    and d.device_fingerprint = p_device_fingerprint
  limit 1;

  if v_device.id is null then raise exception 'DEVICE_NOT_ALLOWED' using errcode = 'P0001'; end if;
  if v_device.is_active is not true then raise exception 'DEVICE_NOT_ACTIVE' using errcode = 'P0001'; end if;
  if v_device.security_token is null or nullif(p_security_token, '') is null then
    raise exception 'DEVICE_TOKEN_REQUIRED' using errcode = 'P0001';
  end if;
  if p_security_token <> v_device.security_token
     and (v_device.previous_security_token is null or p_security_token <> v_device.previous_security_token) then
    raise exception 'DEVICE_TOKEN_INVALID' using errcode = 'P0001';
  end if;
  if v_actor_token is null then raise exception 'ACTOR_SESSION_REQUIRED' using errcode = 'P0001'; end if;

  v_features := coalesce(v_license.effective_features, '{}'::jsonb);

  if v_device.device_mode in ('admin_only', 'shared') then
    v_admin_auth := private.require_active_admin_session(
      p_license_key, p_device_fingerprint, p_security_token, v_actor_token
    );
    v_admin_valid := coalesce((v_admin_auth->>'success')::boolean, false);
  end if;

  if v_device.device_mode in ('staff_only', 'shared') then
    select ss.id as session_id, ss.expires_at, s.id as staff_user_id,
           s.username, s.display_name, s.role_name, s.permissions,
           s.is_active as staff_is_active
    into v_staff_session
    from public.license_staff_sessions ss
    join public.license_staff_users s on s.id = ss.staff_user_id
    where ss.license_id = v_license.id
      and ss.device_id = v_device.id
      and s.license_id = v_license.id
      and ss.revoked_at is null
      and extensions.crypt(v_actor_token, ss.session_token_hash) = ss.session_token_hash
    order by ss.created_at desc
    limit 1;

    if v_staff_session.session_id is not null then
      if v_staff_session.expires_at <= now() then
        update public.license_staff_sessions
        set revoked_at = coalesce(revoked_at, now())
        where id = v_staff_session.session_id;
        raise exception 'STAFF_SESSION_EXPIRED' using errcode = 'P0001';
      end if;
      if v_staff_session.staff_is_active is not true then
        raise exception 'STAFF_USER_INACTIVE' using errcode = 'P0001';
      end if;
      v_staff_valid := true;
    end if;
  end if;

  if v_admin_valid and v_staff_valid then
    raise exception 'ACTOR_SESSION_AMBIGUOUS' using errcode = 'P0001';
  end if;
  if not v_admin_valid and not v_staff_valid then
    raise exception 'ACTOR_SESSION_INVALID' using errcode = 'P0001';
  end if;

  if v_admin_valid then
    v_actor_type := 'admin';
    v_actor_id := (v_admin_auth->>'admin_user_id')::uuid;
    v_actor_session_id := (v_admin_auth->>'admin_session_id')::uuid;
    v_actor_permissions := jsonb_build_object('*', true);
    v_admin_payload := v_admin_auth->'admin_user';
  else
    v_actor_type := 'staff';
    v_actor_id := v_staff_session.staff_user_id;
    v_actor_session_id := v_staff_session.session_id;
    v_actor_permissions := coalesce(v_staff_session.permissions, '{}'::jsonb);
    v_staff_payload := jsonb_build_object(
      'id', v_staff_session.staff_user_id,
      'username', v_staff_session.username,
      'display_name', v_staff_session.display_name,
      'role_name', v_staff_session.role_name,
      'permissions', v_actor_permissions
    );
    perform private.touch_license_staff_session_seen(v_staff_session.session_id, '30 seconds'::interval);
  end if;

  return jsonb_strip_nulls(jsonb_build_object(
    'license_id', v_license.id,
    'license_key', v_license.license_key,
    'device_id', v_device.id,
    'device_mode', v_device.device_mode,
    'legacy_device_role', v_device.legacy_device_role,
    'actor_type', v_actor_type,
    'actor_id', v_actor_id,
    'actor_key', v_actor_type || ':' || v_actor_id::text,
    'actor_session_id', v_actor_session_id,
    'actor_permissions', v_actor_permissions,
    'device_role', v_actor_type,
    'staff_user_id', case when v_actor_type = 'staff' then v_actor_id else null end,
    'staff_permissions', case when v_actor_type = 'staff' then v_actor_permissions else '{}'::jsonb end,
    'staff_user', v_staff_payload,
    'admin_user_id', case when v_actor_type = 'admin' then v_actor_id else null end,
    'admin_session_id', case when v_actor_type = 'admin' then v_actor_session_id else null end,
    'admin_user', v_admin_payload,
    'plan_code', v_license.plan_code,
    'plan_name', v_license.plan_name,
    'features', v_features,
    'realtime_topic', v_device.realtime_topic,
    'license_lifecycle_state', v_license.lifecycle_state,
    'license_is_in_grace', v_license.is_in_grace,
    'license_expires_at', v_license.expires_at,
    'license_grace_period_ends', v_license.grace_period_ends
  ));
end;
$function$
CREATE OR REPLACE FUNCTION public.build_pos_rpc_rate_limited_response(p_rate_limit jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  SELECT jsonb_build_object(
    'success', false,
    'code', COALESCE(NULLIF(p_rate_limit->>'code', ''), 'RPC_RATE_LIMITED'),
    'message', COALESCE(NULLIF(p_rate_limit->>'message', ''), 'Demasiados intentos. Espera unos minutos e intenta de nuevo.'),
    'retry_after_seconds', COALESCE((p_rate_limit->>'retry_after_seconds')::integer, 30)
  );
$function$
CREATE OR REPLACE FUNCTION public.enforce_pos_rpc_rate_limit_v2(p_license_key text, p_device_fingerprint text, p_staff_session_token text, p_rpc_name text, p_scope text, p_max_attempts integer, p_window_seconds integer, p_block_seconds integer, p_code text DEFAULT 'RPC_RATE_LIMITED'::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_now timestamp with time zone := now();
  v_license_key text := COALESCE(NULLIF(BTRIM(COALESCE(p_license_key, '')), ''), '__missing_license__');
  v_device_fingerprint text := COALESCE(NULLIF(BTRIM(COALESCE(p_device_fingerprint, '')), ''), '__missing_device__');
  v_staff_session_hash text := NULL;
  v_rpc_name text := COALESCE(NULLIF(BTRIM(COALESCE(p_rpc_name, '')), ''), '__missing_rpc__');
  v_scope text := COALESCE(NULLIF(BTRIM(COALESCE(p_scope, '')), ''), 'RPC');
  v_max_attempts integer := GREATEST(COALESCE(p_max_attempts, 1), 1);
  v_window_seconds integer := GREATEST(COALESCE(p_window_seconds, 60), 1);
  v_block_seconds integer := GREATEST(COALESCE(p_block_seconds, 60), 1);
  v_code text := COALESCE(NULLIF(BTRIM(COALESCE(p_code, '')), ''), 'RPC_RATE_LIMITED');
  v_window_start timestamp with time zone;
  v_request_count integer := 0;
  v_retry_after_seconds integer := 0;
  v_blocked_until timestamp with time zone;
  v_metadata jsonb := COALESCE(p_metadata, '{}'::jsonb);
BEGIN
  IF NULLIF(BTRIM(COALESCE(p_staff_session_token, '')), '') IS NOT NULL THEN
    v_staff_session_hash := encode(extensions.digest(p_staff_session_token, 'sha256'), 'hex');
  END IF;

  SELECT max(blocked_until)
  INTO v_blocked_until
  FROM public.pos_rpc_rate_limits
  WHERE license_key = v_license_key
    AND device_fingerprint = v_device_fingerprint
    AND rpc_name = v_rpc_name
    AND scope = v_scope
    AND COALESCE(staff_session_hash, ''::text) = COALESCE(v_staff_session_hash, ''::text)
    AND blocked_until IS NOT NULL
    AND blocked_until > v_now;

  IF v_blocked_until IS NOT NULL THEN
    v_retry_after_seconds := GREATEST(CEIL(extract(epoch FROM (v_blocked_until - v_now)))::integer, 1);

    RETURN jsonb_build_object(
      'allowed', false,
      'code', v_code,
      'message', 'Demasiados intentos. Espera unos minutos e intenta de nuevo.',
      'scope', v_scope,
      'rpc_name', v_rpc_name,
      'request_count', 0,
      'max_requests', v_max_attempts,
      'window_seconds', v_window_seconds,
      'blocked_until', v_blocked_until,
      'retry_after_seconds', v_retry_after_seconds
    );
  END IF;

  v_window_start := to_timestamp(
    floor(extract(epoch FROM v_now) / v_window_seconds) * v_window_seconds
  );

  INSERT INTO public.pos_rpc_rate_limits (
    license_key,
    device_fingerprint,
    staff_session_hash,
    rpc_name,
    scope,
    window_start,
    window_seconds,
    request_count,
    blocked_until,
    last_limited_at,
    metadata,
    created_at,
    updated_at
  )
  VALUES (
    v_license_key,
    v_device_fingerprint,
    v_staff_session_hash,
    v_rpc_name,
    v_scope,
    v_window_start,
    v_window_seconds,
    1,
    NULL,
    NULL,
    v_metadata,
    v_now,
    v_now
  )
  ON CONFLICT (
    license_key,
    device_fingerprint,
    rpc_name,
    window_start,
    window_seconds,
    (COALESCE(staff_session_hash, ''::text))
  )
  DO UPDATE SET
    request_count = public.pos_rpc_rate_limits.request_count + 1,
    scope = EXCLUDED.scope,
    metadata = COALESCE(public.pos_rpc_rate_limits.metadata, '{}'::jsonb) || COALESCE(EXCLUDED.metadata, '{}'::jsonb),
    updated_at = EXCLUDED.updated_at
  RETURNING request_count INTO v_request_count;

  IF v_request_count > v_max_attempts THEN
    v_blocked_until := v_now + make_interval(secs => v_block_seconds);
    v_retry_after_seconds := GREATEST(v_block_seconds, 1);

    UPDATE public.pos_rpc_rate_limits
    SET blocked_until = v_blocked_until,
        last_limited_at = v_now,
        updated_at = v_now
    WHERE license_key = v_license_key
      AND device_fingerprint = v_device_fingerprint
      AND rpc_name = v_rpc_name
      AND window_start = v_window_start
      AND window_seconds = v_window_seconds
      AND COALESCE(staff_session_hash, ''::text) = COALESCE(v_staff_session_hash, ''::text);

    RETURN jsonb_build_object(
      'allowed', false,
      'code', v_code,
      'message', 'Demasiados intentos. Espera unos minutos e intenta de nuevo.',
      'scope', v_scope,
      'rpc_name', v_rpc_name,
      'request_count', v_request_count,
      'max_requests', v_max_attempts,
      'window_seconds', v_window_seconds,
      'blocked_until', v_blocked_until,
      'retry_after_seconds', v_retry_after_seconds
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'scope', v_scope,
    'rpc_name', v_rpc_name,
    'request_count', v_request_count,
    'max_requests', v_max_attempts,
    'window_seconds', v_window_seconds,
    'retry_after_seconds', 0
  );
END;
$function$
CREATE OR REPLACE FUNCTION public.pos_adjust_initial_cash_fund(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_cash_session_id text DEFAULT NULL::text, p_new_opening_amount numeric DEFAULT 0, p_reason text DEFAULT NULL::text, p_expected_version integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
      DECLARE
        v_rate_limit jsonb;
      BEGIN
        v_rate_limit := public.enforce_pos_rpc_rate_limit_v2(
          p_license_key := $1,
          p_device_fingerprint := $2,
          p_staff_session_token := $4,
          p_rpc_name := 'pos_adjust_initial_cash_fund',
          p_scope := 'POS_WRITE',
          p_max_attempts := 60,
          p_window_seconds := 600,
          p_block_seconds := 300,
          p_code := 'RPC_RATE_LIMITED',
          p_metadata := '{}'::jsonb
        );

        IF COALESCE((v_rate_limit->>'allowed')::boolean, false) IS FALSE THEN
          RETURN public.build_pos_rpc_rate_limited_response(v_rate_limit)::jsonb;
        END IF;

        RETURN public.pos_adjust_initial_cash_fund_unlimited($1, $2, $3, $4, $5, $6, $7, $8, $9)::jsonb;
      END;
      $function$
CREATE OR REPLACE FUNCTION public.pos_adjust_initial_cash_fund_unlimited(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_cash_session_id text DEFAULT NULL::text, p_new_opening_amount numeric DEFAULT 0, p_reason text DEFAULT NULL::text, p_expected_version integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_license_id uuid;
  v_device_id uuid;
  v_staff_user_id uuid;
  v_actor_key text;
  v_actor_name text;
  v_session public.pos_cash_sessions;
  v_movement public.pos_cash_movements;
  v_event public.pos_sync_events;
  v_response jsonb;
  v_idem public.pos_idempotency_keys;
  v_inserted_idem boolean;
  v_reason text := nullif(btrim(coalesce(p_reason, '')), '');
  v_previous numeric;
  v_delta numeric;
begin
  v_context := private.validate_pos_sync_context(p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token);
  perform private.assert_cloud_cash_sync_enabled(v_context);
  perform private.assert_cash_permission(v_context);

  v_license_id := (v_context->>'license_id')::uuid;
  v_device_id := (v_context->>'device_id')::uuid;
  v_staff_user_id := nullif(v_context->>'staff_user_id', '')::uuid;
  v_actor_key := private.resolve_cash_actor_key(v_context);
  v_actor_name := private.resolve_cash_actor_name(v_context);

  if coalesce(p_new_opening_amount, 0) < 0 then
    raise exception 'OPENING_AMOUNT_INVALID' using errcode = 'P0001';
  end if;
  if v_reason is null then
    raise exception 'CASH_ADJUST_REASON_REQUIRED' using errcode = 'P0001';
  end if;

  v_inserted_idem := private.insert_pos_idempotency_processing(
    v_license_id,
    p_idempotency_key,
    'cash.adjust_initial_fund',
    'cash_session',
    p_cash_session_id,
    null
  );

  if not v_inserted_idem then
    select * into v_idem
    from public.pos_idempotency_keys
    where license_id = v_license_id
      and idempotency_key = p_idempotency_key
    limit 1;

    if v_idem.status = 'completed' and v_idem.response_payload is not null then
      return v_idem.response_payload;
    end if;

    return jsonb_build_object(
      'success', false,
      'code', 'IDEMPOTENCY_PROCESSING',
      'message', 'El ajuste ya esta en proceso.',
      'idempotency_key', p_idempotency_key
    );
  end if;

  select * into v_session
  from public.pos_cash_sessions s
  where s.license_id = v_license_id
    and s.id = p_cash_session_id
    and s.deleted_at is null
  for update;

  if v_session.id is null then
    raise exception 'CASH_SESSION_NOT_FOUND' using errcode = 'P0001';
  end if;
  if v_session.status <> 'open' then
    raise exception 'CASH_SESSION_NOT_OPEN' using errcode = 'P0001';
  end if;
  perform private.assert_cash_session_station(v_license_id, v_device_id, v_session.id);
  if v_session.actor_key <> v_actor_key then
    raise exception 'CASH_HANDOFF_REQUIRED' using errcode = 'P0001';
  end if;
  if p_expected_version is not null and p_expected_version <> v_session.server_version then
    v_response := jsonb_build_object(
      'success', false,
      'code', 'VERSION_CONFLICT',
      'message', 'La caja fue modificada en otro dispositivo.',
      'cash_session', private.pos_cash_session_to_jsonb(v_session),
      'idempotency_key', p_idempotency_key
    );
    perform private.complete_pos_idempotency(v_license_id, p_idempotency_key, v_response);
    return v_response;
  end if;

  v_previous := coalesce(v_session.opening_amount, 0);
  v_delta := coalesce(p_new_opening_amount, 0) - v_previous;

  if v_delta = 0 then
    v_response := jsonb_build_object(
      'success', true,
      'no_change', true,
      'cash_session', private.pos_cash_session_to_jsonb(v_session),
      'message', 'El fondo inicial ya tenia ese monto.',
      'idempotency_key', p_idempotency_key
    );
    perform private.complete_pos_idempotency(v_license_id, p_idempotency_key, v_response);
    return v_response;
  end if;

  update public.pos_cash_sessions
  set opening_amount = p_new_opening_amount,
      last_idempotency_key = p_idempotency_key,
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('last_initial_fund_adjust_reason', v_reason)
  where license_id = v_license_id
    and id = p_cash_session_id
  returning * into v_session;

  insert into public.pos_cash_movements (
    id,
    license_id,
    cash_session_id,
    device_id,
    staff_user_id,
    actor_key,
    type,
    amount,
    concept,
    source,
    created_by_device_id,
    created_by_staff_user_id,
    actor_name,
    idempotency_key,
    metadata
  ) values (
    'mov_' || replace(gen_random_uuid()::text, '-', ''),
    v_license_id,
    v_session.id,
    v_session.device_id,
    v_session.staff_user_id,
    v_session.actor_key,
    'fondo_inicial_ajuste',
    abs(v_delta),
    'Ajuste fondo inicial: ' || v_previous::text || ' -> ' || p_new_opening_amount::text || '. Motivo: ' || v_reason,
    'manual',
    v_device_id,
    v_staff_user_id,
    v_actor_name,
    p_idempotency_key,
    jsonb_build_object('previous_amount', v_previous, 'new_amount', p_new_opening_amount, 'delta', v_delta, 'reason', v_reason)
  ) returning * into v_movement;

  v_session := private.recalculate_pos_cash_session_totals(v_license_id, v_session.id, true);

  perform private.record_pos_cash_event(
    v_license_id,
    v_session.id,
    'INITIAL_FUND_ADJUSTED',
    v_device_id,
    v_staff_user_id,
    v_actor_name,
    jsonb_build_object('movement_id', v_movement.id, 'previous_amount', v_previous, 'new_amount', p_new_opening_amount)
  );

  v_event := private.record_pos_sync_event(
    v_license_id,
    'cash_session',
    v_session.id,
    'adjust',
    v_device_id,
    v_staff_user_id,
    p_idempotency_key,
    jsonb_build_object('cash_session_id', v_session.id, 'movement_id', v_movement.id, 'actor_key', v_session.actor_key),
    v_session.server_version
  );

  v_response := jsonb_build_object(
    'success', true,
    'cash_session', private.pos_cash_session_to_jsonb(v_session),
    'movement', private.pos_cash_movement_to_jsonb(v_movement),
    'event', to_jsonb(v_event),
    'change_seq', v_event.change_seq,
    'idempotency_key', p_idempotency_key
  );
  perform private.complete_pos_idempotency(v_license_id, p_idempotency_key, v_response);
  return v_response;
end;
$function$
CREATE OR REPLACE FUNCTION public.pos_admin_close_cash_session(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_cash_session_id text DEFAULT NULL::text, p_closing_mode text DEFAULT NULL::text, p_counted_amount numeric DEFAULT NULL::numeric, p_next_shift_fund numeric DEFAULT NULL::numeric, p_reason_code text DEFAULT NULL::text, p_comments text DEFAULT NULL::text, p_expected_version integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_rate_limit jsonb;
begin
  v_rate_limit := public.enforce_pos_rpc_rate_limit_v2(
    p_license_key := p_license_key,
    p_device_fingerprint := p_device_fingerprint,
    p_staff_session_token := p_staff_session_token,
    p_rpc_name := 'pos_admin_close_cash_session',
    p_scope := 'POS_WRITE',
    p_max_attempts := 20,
    p_window_seconds := 600,
    p_block_seconds := 300,
    p_code := 'RPC_RATE_LIMITED',
