CREATE OR REPLACE FUNCTION public.pos_admin_close_cash_session_unlimited(p_license_key text, p_device_fingerprint text, p_security_token text, p_staff_session_token text DEFAULT NULL::text, p_cash_session_id text DEFAULT NULL::text, p_closing_mode text DEFAULT NULL::text, p_counted_amount numeric DEFAULT NULL::numeric, p_next_shift_fund numeric DEFAULT NULL::numeric, p_reason_code text DEFAULT NULL::text, p_comments text DEFAULT NULL::text, p_expected_version integer DEFAULT NULL::integer, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_context jsonb;
  v_admin_auth jsonb;
  v_actor_key text;
begin
  v_context := private.validate_pos_sync_context(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token
  );
  perform private.assert_cloud_cash_sync_enabled(v_context);

  v_admin_auth := private.require_active_admin_session(
    p_license_key, p_device_fingerprint, p_security_token, p_staff_session_token
  );
  if coalesce((v_admin_auth->>'success')::boolean, false) is not true then
    raise exception '%', coalesce(v_admin_auth->>'code', 'ADMIN_SESSION_REQUIRED') using errcode = 'P0001';
  end if;

  v_actor_key := private.resolve_cash_actor_key(v_context);

  return private.execute_admin_cash_close_v2(
    (v_admin_auth->>'license_id')::uuid,
    (v_admin_auth->>'device_id')::uuid,
    (v_admin_auth->>'admin_user_id')::uuid,
    (v_admin_auth->>'admin_session_id')::uuid,
    coalesce(
      nullif(btrim(v_admin_auth->'admin_user'->>'display_name'), ''),
      nullif(btrim(v_admin_auth->'admin_user'->>'username'), ''),
      'Administrador'
    ),
    v_actor_key,
    p_cash_session_id,
    p_closing_mode,
    p_counted_amount,
    p_next_shift_fund,
    p_reason_code,
    p_comments,
    p_expected_version,
    p_idempotency_key,
    'cash.admin_close',
    null
  );
end;
