CREATE OR REPLACE FUNCTION private.emit_business_profile_updated_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  v_license_key text;
  v_profile_revision bigint;
begin
  if tg_op = 'UPDATE'
     and row(
       old.business_name,
       old.phone_number,
       old.address,
       old.logo_url,
       old.business_type
     ) is not distinct from row(
       new.business_name,
       new.phone_number,
       new.address,
       new.logo_url,
       new.business_type
     ) then
    return new;
  end if;

  select l.license_key
  into v_license_key
  from public.licenses l
  where l.id = new.license_id;

  if v_license_key is null then
    return new;
  end if;

  v_profile_revision := floor(
    extract(epoch from coalesce(new.updated_at, new.created_at, now())) * 1000
  )::bigint;

  insert into public.license_events (
    license_key,
    event_type,
    metadata
  ) values (
    v_license_key,
    'BUSINESS_PROFILE_UPDATED',
    jsonb_build_object(
      'profile_id', new.id,
      'updated_at', new.updated_at,
      'profile_revision', v_profile_revision,
      'business_type', to_jsonb(
        coalesce(new.business_type, array[]::public.business_category[])
      )
    )
  );

  return new;
end;
